public static String abbreviateInteger(long number, int decPlaces) {
    String suffix = "";
    double abbreviated = number;
    DecimalFormat decimalFormat = new DecimalFormat("###.#");

    if (number >= 1000000) {
        suffix = "M";
        abbreviated = number / 1000000.0;
    } else if (number >= 1000) {
        suffix = "K";
        abbreviated = number / 1000.0;
    }

    decimalFormat.setMaximumFractionDigits(decPlaces);
    String result = decimalFormat.format(abbreviated);
    return result + suffix;
}
