public <T> boolean login(String user, String password, boolean remember, HttpServletRequest request, HttpServletResponse response) {
    // Check the user's password
    boolean passwordCorrect = checkPassword(user, password);

    // Execute the login request
    if (passwordCorrect) {
        // Set user info in session
        User userInfo = getUserInfo(user);
        request.getSession().setAttribute("userInfo", userInfo);

        // Set cookie if 'remember' is true
        if (remember) {
            Cookie userCookie = new Cookie("user", user);
            Cookie passwordCookie = new Cookie("password", password);
            response.addCookie(userCookie);
            response.addCookie(passwordCookie);
        }

        return true; //login success
    } else {
        return false; //login failed
    }
}

