public List<List<Long>> getOffsetsFromDate(Date firstDate, TimeUnit timeUnit, List<Date> runtimes) {
    List<List<Long>> offsets = new ArrayList<>();

    long firstDateTime = firstDate.getTime();

    for (Date runtime : runtimes) {
        long runtimeTime = runtime.getTime();
        long diff = runtimeTime - firstDateTime;
        long diffInUnits = timeUnit.convert(diff, TimeUnit.MILLISECONDS);

        List<Long> offsetList = new ArrayList<>();
        for (long i = 0; i < diffInUnits; i++) {
            offsetList.add(i);
        }

        offsets.add(offsetList);
    }

    return offsets;
}
