public XElement parseXML(XMLStreamReader in) throws XMLStreamException {
    XElement root = null;
    Stack<XElement> stack = new Stack<>();

    while (in.hasNext()) {
        int event = in.next();

        switch (event) {
            case XMLStreamConstants.START_ELEMENT:
                XElement element = new XElement(in.getLocalName());

                for (int i = 0; i < in.getAttributeCount(); i++) {
                    element.addAttribute(in.getAttributeLocalName(i), in.getAttributeValue(i));
                }

                if (root == null) {
                    root = element;
                }

                if (!stack.isEmpty()) {
                    stack.peek().addElement(element);
                }

                stack.push(element);
                break;

            case XMLStreamConstants.CHARACTERS:
                if (!in.isWhiteSpace()) {
                    stack.peek().setText(in.getText());
                }
                break;

            case XMLStreamConstants.END_ELEMENT:
                stack.pop();
                break;
        }
    }

    in.close();

    return root;
}
