public static Color buildGrayColor(Enum gColor) {
    int grayValue = 0;
    switch (gColor) {
        case LIGHT:
            grayValue = 220;
            break;
        case MEDIUM:
            grayValue = 128;
            break;
        case DARK:
            grayValue = 80;
            break;
        default:
            throw new IllegalArgumentException("Color not supported.");
    }
    return Color.rgb(grayValue, grayValue, grayValue);
}

