public Optional<ReplaceInList> repairLocalCommand(ReplaceInList toRepair, ReplaceInList repairAgainst) {
    if (toRepair == null || repairAgainst == null) {
        return Optional.empty();
    }

    if (!toRepair.getListName().equals(repairAgainst.getListName())) {
        return Optional.empty();
    }

    if (toRepair.getElementIndex() > -1) {
        if (toRepair.getElementIndex() >= repairAgainst.getElements().size()) {
            // The element has disappeared from the remote list, drop the local command.
            return Optional.empty();
        }

        return Optional.of(new ReplaceInList(toRepair.getListName(), toRepair.getElementIndex(),
                repairAgainst.getElements().get(toRepair.getElementIndex())));
    } else {
        List<String> elements = repairAgainst.getElements();
        if (toRepair.getListSize() > elements.size()) {
            // The remote list has become shorter than the original size, drop the command.
            return Optional.empty();
        }

        return Optional.of(new ReplaceInList(toRepair.getListName(), 0, elements));
    }
}
