@Override
    public void sawOpcode(int seen) {
        int index;
        switch (state) {
            case SEEN_NOTHING:
                if (seen == Const.BIPUSH) {
                    arraySize = getIntConstant();
                    if (arraySize > 0) {
                        state = State.SEEN_ARRAY_SIZE;
                    }
                } else if ((seen >= Const.ICONST_M1) && (seen <= Const.ICONST_5)) {
                    arraySize = seen - Const.ICONST_M1 - 1;
                    if (arraySize > 0) {
                        state = State.SEEN_ARRAY_SIZE;
                    }
                }
            break;
            case SEEN_ARRAY_SIZE:
                if ((seen == Const.ANEWARRAY) || (seen == Const.NEWARRAY)) {
                    state = State.SEEN_NEWARRAY;
                    storeCount = 0;
                } else {
                    state = State.SEEN_NOTHING;
                }
            break;
            case SEEN_NEWARRAY:
                if (seen == Const.DUP) {
                    state = State.SEEN_DUP;
                } else {
                    state = State.SEEN_NOTHING;
                }
            break;
            case SEEN_DUP:
                if (seen == Const.BIPUSH) {
                    index = getIntConstant();
                } else if ((seen >= Const.ICONST_M1) && (seen <= Const.ICONST_5)) {
                    index = seen - Const.ICONST_M1 - 1;
                } else {
                    state = State.SEEN_NOTHING;
                    return;
                }
                if (index != storeCount) {
                    state = State.SEEN_NOTHING;
                } else {
                    state = State.SEEN_INDEX;
                }
            break;
            case SEEN_INDEX:
                if ((seen == Const.LDC) || (seen == Const.LDC_W)) {
                    state = State.SEEN_LDC;
                } else {
                    state = State.SEEN_NOTHING;
                }
            break;
            case SEEN_LDC:
                if ((seen >= Const.IASTORE) && (seen <= Const.SASTORE)) {
                    if ((++storeCount) == arraySize) {
                        state = State.SEEN_INDEX_STORE;
                    } else {
                        state = State.SEEN_NEWARRAY;
                    }
                }
            break;
            case SEEN_INDEX_STORE:
                if (OpcodeUtils.isAStore(seen)) {
                    bugReporter.reportBug(new BugInstance(this, BugType.SACM_STATIC_ARRAY_CREATED_IN_METHOD.name(),
                            (arraySize < 3) ? LOW_PRIORITY : ((arraySize < 10) ? NORMAL_PRIORITY : HIGH_PRIORITY)).addClass(this).addMethod(this)
                                    .addSourceLine(this, getPC()));
                }
                state = State.SEEN_NOTHING;
            break;
        }
    },0

public String generatePluginConfig(String controllerHost, int controllerPort, String user, String password, String targetPath) {
    String pluginConfig = null;
    try {
        JMXServiceURL url = new JMXServiceURL("service:jmx:rmi:///jndi/rmi://" + controllerHost + ":" + controllerPort + "/jmxrmi");
        Map<String, Object> env = new HashMap<>();
        env.put(JMXConnectorFactory.PROTOCOL_PROVIDER_PACKAGES, "com.sun.management.jmxremote");
        env.put(JMXCredentialManager.USERNAME, user);
        env.put(JMXCredentialManager.PASSWORD, password);
        JMXConnector jmxc = JMXConnectorFactory.connect(url, env);
        try {
            MBeanServerConnection mbsc = jmxc.getMBeanServerConnection();
            ObjectName mbeanName = new ObjectName("com.example:type=PluginConfigGenerator");
            String[] signature = new String[] { String.class.getName() };
            Object[] params = new Object[] { targetPath };
            pluginConfig = (String) mbsc.invoke(mbeanName, "generatePluginConfig", params, signature);
        } finally {
            jmxc.close();
        }
    } catch (Exception e) {
        e.printStackTrace();
    }
    return pluginConfig;
}
