public VirtualConnections processRequest(Request req, Map<String, String> options, List<Queue> queues) {
    // Check if the request is already associated with a work queue
    String queueName = req.getWorkQueue();
    if (queueName != null && !queueName.isEmpty()) {
        // If yes, send it to that work queue
        for (Queue queue : queues) {
            if (queue.getName().equals(queueName)) {
                return queue.sendRequest(req, options);
            }
        }
    } else {
        // If not, round robin the request amongst our set of queues
        int queueIndex = req.getQueueIndex();
        for (int i = 0; i < queues.size(); i++) {
            queueIndex++;
            if (queueIndex >= queues.size()) {
                queueIndex = 0;
            }
            Queue queue = queues.get(queueIndex);
            if (queue.isAccepting()) {
                req.setQueueIndex(queueIndex);
                return queue.sendRequest(req, options);
            }
        }
    }
    // If no work queue is available, return null
    return null;
}
