public void writeResultsToChannelBuffer(ChannelBuffer channelBuffer) throws Exception {
  try {
    for (Result result : results) {
      // iterate over all the results and add meta data where appropriate
      if (result.needsMetaData()) {
        channelBuffer.writeBytes(result.getMetaData());
      }
      // write the result to the channel buffer
      channelBuffer.writeBytes(result.getResultData());
    }
  } catch (Exception ex) {
    // If something goes wrong, throw an exception
    throw new Exception("Something went wrong while writing the results to the channel buffer", ex);
  }
}
