import org.openscience.cdk.interfaces.IAtomContainer;

public IAtomContainer beamToCDK(BeamGraph g, boolean kekule) {
    if (!g.isExpanded()) {
        g = Functions.expand(g);
    }
    if (!g.isOrganicSubset()) {
        throw new IllegalArgumentException("The Beam graph contains organic subset atoms.");
    }
    IAtomContainer ac = BeamConverter.toMulti(g);
    if (kekule) {
        ac = Kekulizer.kekulize(ac);
    }
    return ac;
