public class RangeLimitedPercentileTimer {

  private final PercentileTimer percentileTimer;
  private final long min;
  private final long max;

  public RangeLimitedPercentileTimer(int[] percentilesToTrack, long min, long max){
    percentileTimer = new PercentileTimer(percentilesToTrack);
    this.min = min;
    this.max = max;
  }

  public void update(long duration){
    if(duration >= min && duration <= max){
