public String appendAndParse(String value, char decimalSeparator) {
    StringBuilder sb = new StringBuilder(value);
    int separatorPosition = sb.indexOf(String.valueOf(decimalSeparator));
    if (separatorPosition == -1) {
        // no decimal separator found, assume integer value
        sb.append(decimalSeparator).append("0");
    } else if (separatorPosition == sb.length() - 1) {
        // decimal separator found at end, assume decimal value followed by zero
        sb.append("0");
    }
    return sb.toString();
}
