public static double[][] diagonalMatrix(double[] values) {
    int n = values.length;
    double[][] matrix = new double[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                matrix[i][j] = values[i];
            } else {
                matrix[i][j] = 0.0;
            }
        }
    }
    return matrix;
}
