public Collection<String> getAllSvnBranches(String url, String username, String password) {
    Collection<String> branches = new ArrayList<>();

    SVNRepository repository = null;

    try {
        FSRepositoryFactory.setup();
        repository = SVNRepositoryFactory.create(SVNURL.parseURIEncoded(url));
        final ISVNAuthenticationProvider authProvider = new SVNBasicAuthentication(username, password);
        repository.setAuthenticationProvider(authProvider);

        Collection<SVNDirEntry> dirEntries = repository.getDir(".", -1, null, (Collection<SVNDirEntry>) null);

        for (SVNDirEntry svnDirEntry : dirEntries) {
            String branchName = svnDirEntry.getName();
            if (!svnDirEntry.isTruncated() && !svnDirEntry.getKind().toString().equalsIgnoreCase("file") && branchName.startsWith("branches")) {
                branches.add(branchName);
            }
        }

    } catch (SVNAuthenticationException sae) {
        // Handle authentication exception
    } catch (SVNException e) {
        // Handle SVN exception
    } finally {
        if (repository != null) {
            repository.closeSession();
        }
    }
    return branches;
}
