public Page retrievePreviousPage(Page currentPage, TwilioRestClient client) throws TwilioException {
    if(currentPage == null) {
        throw new IllegalArgumentException("currentPage cannot be null");
    }

    if(client == null) {
        throw new IllegalArgumentException("client cannot be null");
    }

    String previousPageUrl = currentPage.getAdjacentPageUrls().getPreviousPageUrl();

    if(previousPageUrl == null) {
        throw new RuntimeException("There is no previous page to retrieve");
    }

    ResourceSet<?> resourceSet = client.request(previousPageUrl, HttpMethod.GET, null, null).getResourceSet();

    return new Page(currentPage.getPageSize(), previousPageUrl, resourceSet);
}
