public void pruneNeighbors(int[][] image, boolean[][] keepRegion) {
    int numRows = image.length;
    int numCols = image[0].length;

    for (int row = 1; row < numRows - 1; row++) {
        for (int col = 1; col < numCols - 1; col++) {
            if (!keepRegion[row][col]) {
                continue;
            }

            boolean prune = true;
            int currPixelVal = image[row][col];

            // Check top neighbor
            if (keepRegion[row - 1][col] && image[row - 1][col] == currPixelVal) {
                prune = false;
            }
            // Check bottom neighbor
            else if (keepRegion[row + 1][col] && image[row + 1][col] == currPixelVal) {
                prune = false;
            }
            // Check left neighbor
            else if (keepRegion[row][col - 1] && image[row][col - 1] == currPixelVal) {
                prune = false;
            }
            // Check right neighbor
            else if (keepRegion[row][col + 1] && image[row][col + 1] == currPixelVal) {
                prune = false;
            }

            if (prune) {
                keepRegion[row][col] = false;
            }
        }
    }
}
