public int getElementWiseStride(Buffer buffer) {
    if (buffer instanceof FloatBuffer) {
        return ((FloatBuffer) buffer).array().length;
    } else if (buffer instanceof DoubleBuffer) {
        return ((DoubleBuffer) buffer).array().length;
    } else if (buffer instanceof IntBuffer) {
        return ((IntBuffer) buffer).array().length;
    } else if (buffer instanceof LongBuffer) {
        return ((LongBuffer) buffer).array().length;
    } else if (buffer instanceof CharBuffer) {
        return ((CharBuffer) buffer).array().length;
    } else if (buffer instanceof ShortBuffer) {
        return ((ShortBuffer) buffer).array().length;
    } else {
        throw new IllegalArgumentException("Invalid buffer type");
    }
}
