public static int updateGlobalCentroid(double[] overallCentroid, Instances rel, int[] clusters, double[][] centroids) {

  int numberOfClusters = centroids.length;
  int numberOfAttributes = rel.numAttributes();

  // Reset overallCentroid
  for(int i = 0; i < numberOfAttributes; i++) {
    overallCentroid[i] = 0;
  }

  // Calculate new overallCentroid
  for(int i = 0; i < rel.numInstances(); i++) {
    int clusterIndex = clusters[i];
    Instance instance = rel.instance(i);
    for(int j = 0; j < numberOfAttributes; j++) {
      overallCentroid[j] += (centroids[clusterIndex][j] - overallCentroid[j]) / (i + 1);
    }
  }

  return numberOfClusters;
}
