public Collection<String> getWordWordDependencies(List<SyntaxNode> nodes) {
    Collection<String> dependencies = new ArrayList<String>();
    for (SyntaxNode node : nodes) {
        String mother = node.getSyntacticCategory();
        String head = node.getHead().getSyntacticCategory();
        String daughter = node.getDaughter().getSyntacticCategory();
        String dependency = mother + "-" + head + "-" + daughter;
        dependencies.add(dependency);
    }
    return dependencies;
}
