import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.zip.DataFormatException;
import java.util.zip.Inflater;

public byte[] inflate(byte[] zipinput, int start) throws DataFormatException, IOException {
    Inflater inflater = new Inflater();
    inflater.setInput(zipinput, start, zipinput.length - start);
    ByteArrayOutputStream outputStream = new ByteArrayOutputStream(zipinput.length);
    byte[] buffer = new byte[1024];
    while (!inflater.finished()) {
        int count = inflater.inflate(buffer);
        outputStream.write(buffer, 0, count);
    }
    outputStream.close();
    byte[] inflated = outputStream.toByteArray();
    return inflated;
}
