public static String getClassDescriptor(String fieldSignature) {
   int arrayCount = 0;
   while (fieldSignature.charAt(arrayCount) == '[') {
      arrayCount++;
   }
   if (fieldSignature.charAt(arrayCount) == 'L') {
      int semicolonIndex = fieldSignature.indexOf(';');
      return "L" + fieldSignature.substring(arrayCount + 1, semicolonIndex) + ";";
   }
   switch (fieldSignature.charAt(arrayCount)) {
