public void addMappingType(String index, String mappingType, String mappingFilename) throws IOException {
    GetMappingsRequest getMappingsRequest = new GetMappingsRequest().indices(index).types(mappingType);
    boolean exists = client.indices().existsType(getMappingsRequest, RequestOptions.DEFAULT);
    if (!exists) {
        PutMappingRequest putMappingRequest = new PutMappingRequest(index);
        String jsonString = readMappingFile(mappingFilename);
        putMappingRequest.source(jsonString, XContentType.JSON);
        putMappingRequest.type(mappingType);
        putMappingRequest.timeout(TimeValue.timeValueMinutes(1));
        AcknowledgedResponse putMappingResponse = client.indices().putMapping(putMappingRequest, RequestOptions.DEFAULT);
        if (!putMappingResponse.isAcknowledged()) {
            throw new IOException("Error adding mapping type " + mappingType + " to index " + index);
        }
    } else {
        // Mapping type already exists, no action is required
    }
}

private static String readMappingFile(String mappingFilename) throws IOException {
    try (InputStream inputStream = new FileInputStream(mappingFilename)) {
        ByteArrayOutputStream result = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int length;
        while ((length = inputStream.read(buffer)) != -1) {
            result.write(buffer, 0, length);
        }
        return result.toString(StandardCharsets.UTF_8.name());
    }
}
