@Override
public Dialog createDialog(SIPTransaction transaction) throws SipException {
    // Check if the transaction is a server transaction
    if (!(transaction instanceof SIPServerTransaction)) {
        throw new SipException("Invalid transaction type, expected SIPServerTransaction");
    }

    // Get the request from the transaction
    SIPRequest request = ((SIPServerTransaction) transaction).getRequest();

    // Create a new dialog
    Dialog dialog = new DialogImpl(transaction);

    // Initialize the dialog
    dialog.initialize();

    // Set the remote tag
    String remoteTag = request.getFromTag();
    if (remoteTag != null) {
        dialog.setRemoteTag(remoteTag);
    }

    // Set the local tag
    String localTag = Utils.getInstance().generateTag();
    dialog.setLocalTag(localTag);

    // Set the call id
    dialog.setCallId(request.getCallId().getCallId());

    // Set the remote sequence number
    dialog.setRemoteSequenceNumber(request.getCSeq().getSeqNumber());

    // Set the remote URI
    dialog.setRemoteParty(request.getRequestURI());

    // Set the local URI
    dialog.setLocalParty(request.getTo().getAddress());

    // Add the dialog to the transaction's dialog set
    SIPTransactionStack stack = transaction.getSIPStack();
    stack.addDialog(dialog);

    return dialog;
