public void checkReportURL(String reportURL) throws BlackDuckIntegrationException, InterruptedException {
    int elapsedTime = 0; // in seconds
    int maxElapsedTime = 30 * 60; // 30 minutes in seconds
    boolean reportGenerated = false;

    while (elapsedTime < maxElapsedTime && !reportGenerated) {
        // Wait for 5 seconds before each check
        Thread.sleep(5000);

        // Check if the report has a finished time available
        // Update reportGenerated accordingly
        reportGenerated = isReportGenerated(reportURL);

        elapsedTime += 5;
    }

    // If the report has not been generated yet after 30 minutes,
    // throw a BlackDuckIntegrationException
    if (!reportGenerated) {
        throw new BlackDuckIntegrationException("Report generation timed out after 30 minutes.");
    }
}

