public List<Image> generateCompositedAnimationFrames(CharacterDescriptor descriptor, String action) throws NoSuchComponentException, IllegalArgumentException {
    List<Image> frames = new ArrayList<>();
    for (String componentName : descriptor.getComponentNames()) {
        Component component = descriptor.getComponent(componentName);
        if (!component.supportsAction(action)) {
            throw new IllegalArgumentException("Component does not support specified action: " + componentName);
        }
        Image image = component.getAnimationFrame(action);
        if (image == null) {
            throw new NoSuchComponentException("No animation frame found for component: " + componentName);
        }
        frames.add(image);
    }
    return frames;
}
