import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.ArrayList;
import java.util.List;

public class DNSUtils {

    public static void setDNSAddresses(List<String> addresses) throws UnknownHostException {
        List<InetAddress> inetAddresses = new ArrayList<InetAddress>();
        for(String address : addresses) {
            InetAddress inetAddress = InetAddress.getByName(address);
            inetAddresses.add(inetAddress);
        }
        java.security.Security.setProperty("networkaddress.cache.ttl" , "0");
        java.security.Security.setProperty("networkaddress.cache.negative.ttl" , "0");
        sun.net.InetAddressCachePolicy.setIfNotSet(sun.net.InetAddressCachePolicy.NEVER);

        java.lang.reflect.Field cacheField;
        try {
            cacheField = InetAddress.class.getDeclaredField("addressCache");
            cacheField.setAccessible(true);
            Object obj = cacheField.get(null);
            java.lang.reflect.Method clearMethod = obj.getClass().getDeclaredMethod("clear");
            clearMethod.invoke(obj);
        } catch (Exception e) {
            e.printStackTrace();
        }
        for(InetAddress inetAddress : inetAddresses) {
            System.setProperty("sun.net.spi.nameservice.nameservers", inetAddress.getHostAddress());
            System.setProperty("sun.net.spi.nameservice.provider.1", "dns,sun");
            java.security.Security.setProperty("networkaddress.cache.ttl", "0");
            java.security.Security.setProperty("networkaddress.cache.negative.ttl", "0");
        }
    }
}

