import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Sha3HashFunction {

    public static String sha3(String input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA3-256");
            byte[] hashedByteArray = digest.digest(input.getBytes());
            StringBuilder hashedStringBuilder = new StringBuilder();
            for (byte b : hashedByteArray) {
                hashedStringBuilder.append(String.format("%02x", b));
            }
            return hashedStringBuilder.toString();
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
            return null;
        }
    }
}
