    if (!relativeOrAbsoluteUri.startsWith("/")) {
        relativeOrAbsoluteUri = "/" + relativeOrAbsoluteUri;
    }
    URI uri = new URI(uriList);
    return uri.resolve(relativeOrAbsoluteUri);
}
