public byte[] decrypt(byte[] cipherData) {
    try {
        byte[] initVector = Arrays.copyOfRange(cipherData, 0, 16);
        byte[] payload = Arrays.copyOfRange(cipherData, 16, cipherData.length - 32);
        byte[] signature = Arrays.copyOfRange(cipherData, cipherData.length - 32, cipherData.length);

        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5PADDING");
        SecretKeySpec secretKeySpec = new SecretKeySpec("SecretKey1234567".getBytes("UTF-8"), "AES");
        IvParameterSpec ivParameterSpec = new IvParameterSpec(initVector);
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec, ivParameterSpec);
        byte[] decrypted = cipher.doFinal(payload);

        String signatureStr = new String(signature, StandardCharsets.UTF_8);
        MessageDigest crypt = MessageDigest.getInstance("SHA-1");
        crypt.reset();
        crypt.update(new String(decrypted, StandardCharsets.UTF_8).getBytes("UTF-8"));
        byte[] digest = crypt.digest();

        if (Arrays.equals(digest, signature)) {      //I'(signature) == I(signature) for success, different for failure
            return ByteBuffer.allocate(initVector.length + decrypted.length + signature.length)
              .put(initVector)
              .put(decrypted)
              .put(signature)
              .array();
        } else {
            return new byte[0];
        }
    } catch (Exception e) {
        e.printStackTrace();
        return new byte[0];
    }
}
