public ApplicationContext getApplicationContext(JobExecutionContext context) throws SchedulerException {
    // Obtain the JobDetail associated with the JobExecutionContext
    JobDetail jobDetail = context.getJobDetail();

    // Obtain the JobDataMap associated with the JobDetail
    JobDataMap jobDataMap = jobDetail.getJobDataMap();

    // Obtain the ApplicationContext object from the JobDataMap
    ApplicationContext applicationContext = (ApplicationContext) jobDataMap.get("applicationContext");

    // Check if the ApplicationContext object is not null
    if (applicationContext == null) {
        // Throw a SchedulerException if the ApplicationContext object is null
        throw new SchedulerException("Could not obtain ApplicationContext from JobDataMap");
    }

    // Return the ApplicationContext object
    return applicationContext;
}
