public class ResourceFinder {

    /**
     * Finds classpath resources.
     *
     * @param resource the name of the resource to find.
     * @return a Collection of URLs matching the resource name. If no resources could be found, then this will be empty.
     * @since 2.1
     */
    public static List<URL> findResources(String resource) {
        List<URL> urls = new ArrayList<>();

        try {
            Enumeration<URL> urlEnumeration = Thread.currentThread().getContextClassLoader().getResources(resource);

            while (urlEnumeration.hasMoreElements()) {
                URL url = urlEnumeration.nextElement();
                urls.add(url);
            }

        } catch (IOException e) {
            // handle exception
        }

        return Collections.unmodifiableList(urls);
    }
}
