public long getTimeDuration(String name, String vStr, String unit) {
    String[] units = {"ns", "us", "ms", "s", "m", "h", "d"};
    long[] conversions = {1, 1000, 1000*1000, 1000*1000*1000, 
                          1000*1000*1000*60, 1000*1000*1000*60*60, 1000*1000*1000*60*60*24};
    int index = -1;
    for (int i = 0; i < units.length; i++) {
        if (vStr.endsWith(units[i])) {
            index = i;
            break;
        }
    }
    long duration;
    if (index != -1) {
        duration = conversions[index] * Long.parseLong(vStr.substring(0, vStr.length()-units[index].length()));
    } else {
        duration = Long.parseLong(vStr);
    }
    if (unit != null) {
        for (int i = 0; i < units.length; i++) {
            if (unit.equals(units[i])) {
                duration /= conversions[i];
                break;
            }
        }
    }
    return duration;
}
