public void startEchoService(ServerSocket serverSocket) {
    try {
        // Continuously listen for incoming client connections
        while (true) {
            Socket clientSocket = serverSocket.accept();
            // Start a new thread to handle each client connection
            new Thread(() -> {
                try {
                    BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
                    PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true);
                    String inputLine;
                    // Continuously read incoming messages from the client
                    while ((inputLine = in.readLine()) != null) {
                        // Echo the message back to the client
                        out.println(inputLine);
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                } finally {
                    // Close the client socket when the client disconnects
                    try {
                        clientSocket.close();
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }).start();
        }
    } catch (IOException e) {
        e.printStackTrace();
    }
}
