public static <T, U, V, W, R> TriFunction<T, U, V, W, R>
memoizeQuadFunction(QuadFunction<T, U, V, W, R> fn) {
    Map<String, R> cache = new ConcurrentHashMap<>();
    return (t, u, v, w) -> cache.computeIfAbsent(t.toString() + ":" + u.toString() + ":" + v.toString() + ":" + w.toString(),
            key -> fn.apply(t, u, v, w));
}
