public static DataURI parseDataURI(String uri) throws IllegalArgumentException {
    Pattern pattern = Pattern.compile("^data:([^,]+)?,(.+)$");
    Matcher matcher = pattern.matcher(uri);

    if (!matcher.find()) {
        throw new IllegalArgumentException("Invalid data URI string");
    }

    String mimeType = matcher.group(1);
    String data = matcher.group(2);

    try {
        byte[] decodedData = Base64.getDecoder().decode(data);
        return new DataURI(mimeType, decodedData);
    } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException("Invalid base64 string in data URI", e);
    }
}
