public void copyAcroform(PdfReader reader) throws IOException, BadPdfFormatException {
    if (reader == null)
        throw new IllegalArgumentException("Reader cannot be null");

    if (!reader.hasAcroForm())
        throw new BadPdfFormatException("The input file must contain an acroform");

    PdfDictionary acroform = reader.getAcroForm();
    PdfDictionary newAcroform = new PdfDictionary();

    for (PdfName key : acroform.getKeys()) {
        newAcroform.put(key, acroform.get(key));
    }

    PdfWriter writer = new PdfWriter("output.pdf");

    try (PdfDocument document = new PdfDocument(reader, writer)) {
        document.getCatalog().put(PdfName.AcroForm, newAcroform);
    }
}
