		final String result;
		if (idx < 0) {
			if (end < fullPath.length() - 1) {
				result = fullPath.substring(0, end + 1);
			} else {
				result = fullPath;
			}
		} else {
			result = fullPath.substring(idx + 1, end + 1);
		}
