public int parseInlineMarkdown(StringBuilder out, String in, int start, char token) {
    if (token == '\0') {
        return -1;
    }
    if (start >= in.length()) {
        return -1;
    }
    int pos = start;
    while (pos < in.length()) {
        char c = in.charAt(pos);
        if (c == token) {
            return pos;
        }
        if (c == '\\') {
            out.append(in.charAt(pos + 1));
            pos += 2;
            continue;
        }
        if (c == '`') {
            out.append(parseInlineCode(out, in, pos));
            continue;
        }
        if (c == '[') {
            out.append(parseInlineLink(out, in, pos));
            continue;
        }
        if (c == '!') {
            out.append(parseInlineImage(out, in, pos));
            continue;
        }
        if (c == '<') {
            int tempPos = parseInlineHTML(out, in, pos);
            if (tempPos != -1) {
                pos = tempPos;
                continue;
            }
        }
        out.append(c);
        pos++;
    }
    return -1;
}
