public static byte[] serialize(CoroutineRunner runner) {
    if (runner == null) {
        throw new NullPointerException("Coroutine runner cannot be null");
    }
    try {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ObjectOutputStream objectOutputStream = new ObjectOutputStream(byteArrayOutputStream);
        objectOutputStream.writeObject(runner);
        objectOutputStream.flush();
        return byteArrayOutputStream.toByteArray();
    } catch (IOException ex) {
        throw new IllegalArgumentException("Failed to serialize coroutine runner", ex);
    }
}
