import java.util.Collection;
import java.util.Comparator;
import java.util.HashSet;
import java.util.Set;

public class EntryUtils {

    public static <T> Set<T> processEntries(Collection<T> entries, Comparator<? super T> sameComparator) {
        Set<T> uniqueEntries = new HashSet<>();
        if (sameComparator == null) {
            for (T entry : entries) {
                if (entry != null) {
                    uniqueEntries.add(entry);
                }
            }
        } else {
            for (T entry : entries) {
                if (entry != null && !uniqueEntries.contains(entry)) {
                    uniqueEntries.add(entry);
                }
            }
        }
        return uniqueEntries;
    }
}
