public static void closeAndShutdown(Closeable closeable, ExecutorService executorService, long timeout, TimeUnit timeUnit) {
    try {
        if (closeable != null) {
            closeable.close();
        }
    } catch (Exception ex) {
        // ignore exception
    }

    if (executorService != null) {
        try {
            executorService.shutdown();
            executorService.awaitTermination(timeout, timeUnit);
        } catch (InterruptedException ex) {
            Thread.currentThread().interrupt();
        }
    }
}
