public static int copyUpToByteLimit(OutputStream os, InputStream is, int byteLimit, byte[] buffer) throws IOException{
    int totalBytesCopied = 0;
    int bytesRead = 0;
    while(totalBytesCopied < byteLimit && (bytesRead = is.read(buffer, 0, Math.min(buffer.length, byteLimit - totalBytesCopied))) > 0){
        os.write(buffer, 0, bytesRead);
        totalBytesCopied += bytesRead;
    }
    return totalBytesCopied;
}
