public JSONObject multipleQueriesOnIndex(List<IndexQuery> queries, String strategy, RequestOptions requestOptions) throws AlgoliaException {
    try {
        String body = new Gson().toJson(queries);

        URIBuilder uriBuilder = new URIBuilder("_msearch");

        if (strategy != null) {
            uriBuilder.addParameter("strategy", strategy);
        }

        StringContent content = new StringContent(body, ContentType.APPLICATION_JSON);

        Request request = new Request(HttpMethod.POST, uriBuilder.build(), content)
                .addOption(requestOptions);

        Response response = transport.execute(request);

        if (response.getStatusCode() == HttpStatus.SC_OK) {
            String rawBody = response.getBody();
            return new JSONObject(rawBody);
        } else {
            throw new AlgoliaException(response);
        }
    } catch (URISyntaxException | IOException e) {
        throw new AlgoliaException(e);
    }
