import java.io.BufferedWriter;
import java.io.FileWriter;
import java.io.IOException;
import java.util.List;

public class FormulaWriter<T> {

    public void write(String fileName, Graph<T> graph) throws IOException {

        BufferedWriter writer = new BufferedWriter(new FileWriter(fileName));

        List<List<Integer>> clauses = graph.getClauses();

        // Write the number of variables and clauses in the file
        writer.write("p cnf " + graph.getNumberOfVariables() + " " + clauses.size() + "\n");

        for(List<Integer> clause : clauses) {
            for(Integer literal : clause) {
                writer.write(literal + " ");
            }
            writer.write("0\n");
        }

        writer.close();
    }

}
