public StructuredQueryDefinition matchContainerWithCriteriaWords(String constraintName, double weight, String... words) {
    List<StructuredQueryBuilder.ConstructedQuery> queries = new ArrayList<>();

    for (String word : words) {
        queries.add(new StructuredQueryBuilder.ConstructedQuery(
                StructuredQueryBuilder.word(constraintName, word),
                StructuredQueryBuilder.Weight.of(weight)
        ));
    }

    StructuredQueryBuilder.QueryBuilder queryBuilder = StructuredQueryBuilder.and(queries);

    return StructuredQueryBuilder.containerQuery(constraintName, queryBuilder);
}
