public void dispatchDelayedVariableEvents(Execution execution) {
    // Code to retrieve the delayed variable events for the given execution
    List<DelayedVariableEvent> delayedVariableEvents = getDelayedVariableEvents(execution);

    // Dispatching the delayed variable events on the scope of the execution
    for (DelayedVariableEvent delayedVariableEvent : delayedVariableEvents) {
        Scope scope = execution.getScope();
        Variable variable = scope.getVariable(delayedVariableEvent.getVariableName());

        // Updating the value of the variable on the scope
        variable.setValue(delayedVariableEvent.getVariableValue());

        // Clearing the delayed variable event
        clearDelayedVariableEvent(delayedVariableEvent);
    }
}

