public void setClusterCenter(int[][] image, int clusterX, int clusterY) {
    int minGradient = Integer.MAX_VALUE;
    int centerPixelX = clusterX;
    int centerPixelY = clusterY;
    for (int i = clusterX - 1; i <= clusterX + 1; i++) {
        for (int j = clusterY - 1; j <= clusterY + 1; j++) {
            if (i >= 0 && i < image.length && j >= 0 && j < image[0].length) {
                if (image[i][j] < minGradient) {
                    minGradient = image[i][j];
                    centerPixelX = i;
                    centerPixelY = j;
                }
            }
        }
    }
    // Set the cluster center to the pixel with the smallest gradient in the 3x3 neighborhood
    clusterX = centerPixelX;
    clusterY = centerPixelY;
}
