import com.restfb.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;

public class CookieValidator {
    public static void validate(String cookie, String appSecret) {
        String[] components = cookie.split("\\.");
        if (components.length < 2) {
            throw new IllegalStateException("Invalid cookie format");
        }
        String encodedSignature = components[0];
        String encodedPayload = components[1];

        String expectedSignature;
        try {
            Mac hmac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(appSecret.getBytes(), "HmacSHA256");
            hmac.init(keySpec);
            byte[] digest = hmac.doFinal(encodedPayload.getBytes());
            expectedSignature = new String(Base64.encodeBytes(digest)).replace("\n", "");
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("Invalid algorithm: " + e.getMessage());
        } catch (InvalidKeyException e) {
            throw new IllegalStateException("Invalid key: " + e.getMessage());
        }

        if (!encodedSignature.equals(expectedSignature)) {
            throw new IllegalStateException("Invalid signature");
        }
    }
}
