public static ApplicationException recreateApplicationException(byte[] description) throws Exception {
    ByteArrayInputStream bis = new ByteArrayInputStream(description);
    ObjectInputStream ois = new ObjectInputStream(bis);
    ErrorDescription error = (ErrorDescription) ois.readObject();
    ois.close();
    bis.close();

    Class<?> clazz = Class.forName(error.getType());
    Constructor<?> constructor = clazz.getConstructor(String.class, Throwable.class);
    ApplicationException newException = (ApplicationException) constructor.newInstance(error.getMessage(), null);
    newException.setCategory(error.getCategory());

    return newException;
}
