public Set<Integer> computeMedoids(Set<Integer> m, Set<Integer> m_best, Set<Integer> m_bad, Random random) {
    Set<Integer> m_current = new HashSet<Integer>(m);
    double bestDist = computeDistance(m, m_best);
    for (int i = 0; i < m.size(); i++) {
        int medoid = new ArrayList<Integer>(m).get(i);
        if (!m_best.contains(medoid)) {
            Set<Integer> m_new = new HashSet<Integer>(m_current);
            m_new.remove(medoid);
            m_new.add(m_best.toArray(new Integer[0])[random.nextInt(m_best.size())]);
            double newDist = computeDistance(m, m_new);
            if (newDist < bestDist) {
                m_current = m_new;
                bestDist = newDist;
            }
            else {
                m_bad.add(medoid);
            }
        }
    }
    return m_current;
}

