import java.lang.reflect.Method;

public class MethodDeclarationBuilder {

   private int protection;
   private String returnType;
   private String methodName;
   private StringBuilder statementBuilder;

   public MethodDeclarationBuilder(int protection, String returnType, String methodName) {
      this.protection = protection;
      this.returnType = returnType;
      this.methodName = methodName;
      this.statementBuilder = new StringBuilder();
   }

   public void addStatement(String statement) {
      statementBuilder.append(statement);
   }

   public Method build() throws NoSuchMethodException {
      Class<?>[] emptyArray = new Class<?>[0];
      return getClass().getMethod(methodName, emptyArray);
   }

   @Override
   public String toString() {
      StringBuilder builder = new StringBuilder();
      builder.append(protectionToString(protection));
      builder.append(" ");
      builder.append(returnType);
      builder.append(" ");
      builder.append(methodName);
      builder.append("() {");
      builder.append(statementBuilder.toString());
      builder.append("}");
      return builder.toString();
   }

   private String protectionToString(int protection) {
      switch (protection) {
         case 0:
            return "public";
         case 1:
            return "package";
         case 2:
            return "protected";
         case 3:
            return "private";
         default:
            return "";
      }
   }

   public static MethodDeclarationBuilder startStaticMethod(int protection, String returnType, String methodName) {
      return new MethodDeclarationBuilder(protection, returnType, methodName);
   }

   public MethodDeclarationBuilder endMethod() {
      return this;
   }
}
