public void verifyHdfsConversions(String sb) throws IllegalArgumentException {
    // List of required hdfs conversions
    List<String> conversions = Arrays.asList("s", "d", "f", "l", "t", "u", "o", "x");

    // Extract the path portion of the endpoint
    int index = sb.indexOf("://");
    String path = sb.substring(index + 3);

    // Check if all required conversions are present
    for (String conversion : conversions) {
        if (!path.contains("%" + conversion)) {
            throw new IllegalArgumentException("Endpoint format string does not specify required hdfs conversion: %" + conversion);
        }
    }
}
