public static LocalDate getThirdWednesdayOfMonth(LocalDate original) {
    LocalDate thirdWednesday = original.withDayOfMonth(1);
    int count = 0;
    while (count < 2) {
        if (thirdWednesday.getDayOfWeek() == DayOfWeek.WEDNESDAY) {
            count++;
        }
        thirdWednesday = thirdWednesday.plusDays(1);
    }
    return thirdWednesday;
}
