    public static void periodicallyAppendConnection(Socket socket, long interval, TimeUnit unit) {
        ScheduledExecutorService executor = Executors.newSingleThreadScheduledExecutor();

        // Use a CompletableFuture to make sure that the periodic task keeps running
        CompletableFuture<Void> future = new CompletableFuture<>();

        executor.scheduleAtFixedRate(() -> {
            // Refresh the aperture periodically
            refreshAperture(targetAperture);

            // Add or remove reactive sockets as needed to match the target aperture
            int numSocketsToAdd = targetAperture.getNumSockets() - existingSockets.size();
            int numSocketsToRemove = existingSockets.size() - targetAperture.getNumSockets();

            while (numSocketsToAdd-- > 0) {
                addReactiveSocket(createNewSocket());
            }

            while (numSocketsToRemove-- > 0 && !existingSockets.isEmpty()) {
                removeReactiveSocket(existingSockets.remove());
            }

            // Add a new connection periodically
            addReactiveSocket(socket);
        }, 0, interval, unit);

        // Make sure the future never completes
        future.join();
    }
}
