import java.io.File;
import java.util.function.Consumer;

public void consumeSubFilePaths(String startDirectoryPath, Consumer<File> consumer) {
    File startDirectory = new File(startDirectoryPath);
    if (!startDirectory.isDirectory()) {
        throw new IllegalArgumentException("startDirectoryPath must refer to a directory");
    }
    consumeSubFilePaths(startDirectory, consumer);
}

private void consumeSubFilePaths(File directory, Consumer<File> consumer) {
    File[] subFiles = directory.listFiles();
    if (subFiles != null) {
        for (File subFile : subFiles) {
            if (subFile.isDirectory()) {
                consumeSubFilePaths(subFile, consumer);
            } else {
                consumer.accept(subFile);
            }
        }
    }
}
