public static String createIPv6MixedAddress(String[] segs) {
    String ipv6Prefix = "0000:0000:0000:0000:0000:ffff:"; // IPv6 prefix for IPv4 embedded address
    String ipv4Address = segs[6] + "." + segs[7] + "." + segs[8] + "." + segs[9]; // Create IPv4 address string
    String ipv6Address = ""; // Initialize empty IPv6 address string
    for (int i = 0; i < 6; i++) {
        ipv6Address += segs[i] + ":"; // Append first 6 segments to IPv6 address string
    }
    ipv6Address += ipv6Prefix + ipv4Address; // Append IPv4 embedded address to IPv6 address string
    return ipv6Address;
}
