public byte[] compressValue(byte[] value, byte[] prefix) throws SupportException {
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try (CompressorOutputStream cos = new CompressorStreamFactory()
            .createCompressorOutputStream(CompressorStreamFactory.GZIP, baos)) {
        cos.write(prefix);
        cos.write(value);
        cos.finish();
        return baos.toByteArray();
    } catch (IOException e) {
        throw new SupportException("Compression failed.", e);
    }
}
