import io.netty.util.CharsetUtil;

public static Charset fetchCharsetFromContentType(String contentTypeValue) {
    String charset = CharsetUtil.ISO_8859_1.name();
    if (contentTypeValue != null) {
        int charsetIndex = contentTypeValue.indexOf("charset=");
        if (charsetIndex >= 0) {
            charset = contentTypeValue.substring(charsetIndex + 8);
            try {
                Charset.forName(charset);
            } catch (Exception e) {
                charset = CharsetUtil.ISO_8859_1.name();
            }
        }
    }
    return Charset.forName(charset);
}
