      if (TraceComponent.isAnyTracingEnabled() && tc.isDebugEnabled()) JmfTr.debug(this, tc, "Compatibility violation (deleting variant):"
                                             + " var CaseCount = " + var.getCaseCount()
                                             + ", varIsAccess " + varIsAccess
