    }
    if (isEmpty(var.getCase(1))) {


      JMFType compare = var.getCase(0);
      if (varIsAccess)
        recordCompatibilityInfo(compare, accSchema, nonVar, encSchema);
      else
        recordCompatibilityInfo(nonVar, accSchema, compare, encSchema);
