/**
 * Internal method to write out all children JSON objects attached to this JSON object.
 *
 * @param writer The writer to use while writing the JSON text.
 * @param depth The indention depth of the JSON text.
 * @param compact Flag to denote whether or not to write in nice indent format, or compact format.
 * @throws IOException Thrown if an error occurs on write.
 */
private void writeChildrenJson(final Writer writer, final int depth, final boolean compact) throws IOException {
    if (this.children.isEmpty()) {
        return;
    }

    final int newDepth = compact ? 0 : depth + 1;
    final String indent = compact ? "" : String.format("%" + newDepth * 4 + "s", "");

    writer.write('[');
    if (!compact) {
        writer.write('\n');
    }

    boolean firstChild = true;
    for (final Json child : this.children) {
        if (!firstChild) {
            writer.write(',');
            if (!compact) {
                writer.write('\n');
            }
        }

        writer.write(indent);
        child.writeJson(writer, newDepth, compact);
        firstChild = false;
    }

    if (!compact) {
        writer.write('\n');
        writer.write(String.format("%" + depth * 4 + "s", ""));
    }

    writer.write(']');
}
