public static <T> T extractValues(Object da, Class<T> type) throws DevFailed {
    if (type == null || da == null) {
        throw new IllegalArgumentException("Invalid arguments");
    }
    if (type != double.class && type != double[].class && type != double[][].class) {
        throw new IllegalArgumentException("Invalid output type");
    }
    if (da instanceof DevState) {
        throw new DevFailed("Invalid value type");
    }
    if (type == double.class) {
        return type.cast(NumberUtil.extractScalarFromNumber(da));
    } else if (type == double[].class) {
        return type.cast(NumberUtil.extractSpectrumFromNumber(da));
    } else { // type == double[][].class
        return type.cast(NumberUtil.extractImageFromNumber(da));
    }
}
