public String computeProperName(DMNNode node) {
    String name = node.getModelName();
    DMNModel model = node.getModel();
    if (model != null) {
        DMNImporter importer = model.getImporter();
        if (importer != null) {
            DMNModel importModel = importer.getImportModel(node);
            if (importModel != null) {
                DMNElement importElement = importModel.getElementById(node.getId());
                if (importElement != null) {
                    String prefix = importModel.getModelName();
                    if (importModel.getParentModel() != model) {
                        prefix = computeProperName(model.getDefinitions());
                    }
                    name = prefix + "." + importElement.getName();
                }
            }
        }
    }
    return name;
}
