public void addGarbageCollectionMetrics(Result result){
    //Logic to retrieve garbage collection metrics
    long garbageCollectionTime = ManagementFactory.getGarbageCollectorMXBeans()
                            .stream()
                            .mapToLong(gc -> gc.getCollectionTime())
                            .sum();

    long garbageCollectionCount = ManagementFactory.getGarbageCollectorMXBeans()
                            .stream()
                            .mapToLong(gc -> gc.getCollectionCount())
                            .sum();

    //Updating the Result object with the retrieved metrics
    result.addMetric("Garbage Collection Time", garbageCollectionTime);
    result.addMetric("Garbage Collection Count", garbageCollectionCount);
}
