public static String getRelativePath(String baseDir, File file) {
    String absoluteFilePath = file.getAbsolutePath();
    String absoluteBaseDir = new File(baseDir).getAbsolutePath();
    if (!absoluteFilePath.startsWith(absoluteBaseDir)) {
        throw new IllegalArgumentException("File is not contained within the specified base directory");
    }
    int substringIndex = absoluteBaseDir.length();
    if (!absoluteBaseDir.endsWith(File.separator)) {
        substringIndex++;
    }
    String relativePath = absoluteFilePath.substring(substringIndex);
    if (relativePath.startsWith(File.separator)) {
        relativePath = relativePath.substring(1);
    }
    return relativePath;
}
