public void readBytesFromStream(InputStream in, int lengthToRead) throws IOException {
    byte[] byteArray = new byte[lengthToRead];
    int totalBytesRead = 0;
    int bytesRead = 0;
    while (totalBytesRead < lengthToRead && (bytesRead = in.read(byteArray, totalBytesRead, lengthToRead - totalBytesRead)) != -1) {
        totalBytesRead += bytesRead;
    }
}
