@Override
public Matrix4d rotateAround(Quaterniondc quat, double x, double y, double z, Matrix4d dest) {
    double num = quat.x() + quat.x();
    double num2 = quat.y() + quat.y();
    double num3 = quat.z() + quat.z();
    double num4 = quat.x() * num;
    double num5 = quat.y() * num2;
    double num6 = quat.z() * num3;
    double num7 = quat.x() * num2;
    double num8 = quat.x() * num3;
    double num9 = quat.y() * num3;
    double num10 = quat.w() * num;
    double num11 = quat.w() * num2;
    double num12 = quat.w() * num3;
    double m00 = (1.0 - (num5 + num6)) * x + (num7 - num12) * y + (num8 + num11) * z;
    double m01 = (num7 + num12) * x + (1.0 - (num4 + num6)) * y + (num9 - num10) * z;
    double m02 = (num8 - num11) * x + (num9 + num10) * y + (1.0 - (num4 + num5)) * z;
    double m10 = (num7 - num12) * x + (1.0 - (num4 + num6)) * y + (num8 - num11) * z;
    double m11 = (1.0 - (num5 + num6)) * y + (num7 + num12) * x + (num9 + num10) * z;
    double m12 = (num9 - num10) * x + (num8 + num11) * y + (1.0 - (num4 + num5)) * z;
    double m20 = (num8 + num11) * x + (num9 - num10) * y + (1.0 - (num4 + num5)) * z;
    double m21 = (num9 + num10) * x + (num8 - num11) * y + (1.0 - (num4 + num5)) * z;
    double m22 = (1.0 - (num5 + num6)) * z + (num8 - num11) * x + (num9 - num10) * y;
    double nm00 = m00 * m00 + m01 * m01 + m02 * m02 + dest.m30() * dest.m30();
    double nm01 = m10 * m00 + m11 * m01 + m12 * m02 + dest.m31() * dest.m30();
    double nm02 = m20 * m00 + m21 * m01 + m22 * m02 + dest.m32() * dest.m30();
    double nm10 = m00 * dest.m10() + m01 * dest.m11() + m02 * dest.m12() + dest.m30() * dest.m33();
    double nm11 = m10 * dest.m10() + m11 * dest.m11() + m12 * dest.m12() + dest.m31() * dest.m33();
    double nm12 = m20 * dest.m10() + m21 * dest.m11() + m22 * dest.m12() + dest.m32() * dest.m33();
    double nm20 = m00 * dest.m20() + m01 * dest.m21() + m02 * dest.m22() + dest.m30() * dest.m23();
    double nm21 = m10 * dest.m20() + m11 * dest.m21() + m12 * dest.m22() + dest.m31() * dest.m23();
    double nm22 = m20 * dest.m20() + m21 * dest.m21() + m22 * dest.m22() + dest.m32() * dest.m23();
    double nm30 = m00 * dest.m30() + m01 * dest.m31() + m02 * dest.m32() + dest.m33() * dest.m30();
    double nm31 = m10 * dest.m30() + m11 * dest.m31() + m12 * dest.m32() + dest.m33() * dest.m31();
    double nm32 = m20 * dest.m30() + m21 * dest.m31() + m22 * dest.m32() + dest.m33() * dest.m32();
    dest.m00(nm00);
    dest.m01(nm01);
    dest.m02(nm02);
    dest.m10(nm10);
    dest.m11(nm11);
    dest.m12(nm12);
    dest.m20(nm20);
    dest.m21(nm21);
    dest.m22(nm22);
    dest.m30(nm30);
    dest.m31(nm31);
    dest.m32(nm32);
    return dest;
}
