public List<DVD> getTopDvdRentals(String country, int limit) throws RottenTomatoesException {
    List<DVD> topDvdRentals = new ArrayList<>();
    try {
        URL url = new URL("https://api.rottentomatoes.com/api/public/v1.0/lists/dvds/top_rentals.json?apikey={YOUR_API_KEY}&country=" + country + "&limit=" + limit);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("GET");
        BufferedReader br = new BufferedReader(new InputStreamReader((conn.getInputStream())));
        String line;
        StringBuilder response = new StringBuilder();
        while ((line = br.readLine()) != null) {
            response.append(line);
        }
        JsonNode root = new ObjectMapper().readTree(response.toString());

        for (JsonNode dvd: root.path("movies")) {
            String title = dvd.path("title").asText();
            String synopsis = dvd.path("synopsis").asText();
            int year = dvd.path("year").asInt();
            int runtime = dvd.path("runtime").asInt();

            JsonNode posters = dvd.path("posters");
            String thumbnail = posters.path("thumbnail").asText();
            String profile = posters.path("profile").asText();
            String detailed = posters.path("detailed").asText();

            DVD currentDvd = new DVD(title, synopsis, year, runtime, thumbnail, profile, detailed);
            topDvdRentals.add(currentDvd);
        }
    } catch (IOException e) {
        throw new RottenTomatoesException("Failed to fetch the top DVD rentals", e);
    }

    return topDvdRentals;
}
