import java.io.File;
import java.io.IOException;
import java.util.ArrayList;

import cern.colt.matrix.DoubleMatrix1D;
import cern.colt.matrix.DoubleMatrix2D;
import cern.colt.matrix.impl.DenseDoubleMatrix2D;

import edu.ucla.sspace.svd.SvdAlgorithm;
import edu.ucla.sspace.svd.SvdException;
import edu.ucla.sspace.svd.SvdlibcSvdAlgorithm;

public class SvdUtil {

  private static final SvdAlgorithm SVD_ALGORITHM = new SvdlibcSvdAlgorithm();

  public static Matrix[] computeSVD(File matrix, int dimensions) {
    try {
       // Load the matrix
       DoubleMatrix2D matrixToTransform = readMatrix(matrix);

       // Compute the SVD
       edu.ucla.sspace.svd.SVD svd = 
           SVD_ALGORITHM.factor(new DenseDoubleMatrix2D(matrixToTransform.toArray()), dimensions);

       // Convert the results to the format expected by the caller
       Matrix[] results = new Matrix[3];
       results[0] = new Matrix(svd.leftSingularVectors().viewDice().toArray());
       results[1] = new Matrix(svd.singularValues().toArray());
       results[2] = new Matrix(svd.rightSingularVectors().toArray());

       return results;
     } catch (IOException e) {
       throw new SvdException("Error loading matrix for SVD", e);
     }
  }

  /**
   * Reads a text file containing a matrix
   * @param matrixFile The file containing the matrix
   * @returns The matrix in the file
   */
  private static DoubleMatrix2D readMatrix(File matrixFile) throws IOException {
    ArrayList<String> lines = FileUtils.readLines(matrixFile);
    DoubleMatrix2D result = new DenseDoubleMatrix2D(lines.size(), lines.get(0).split("[ \t]").length);

    for (int i = 0; i < lines.size(); i++) {
      String[] entries = lines.get(i).split("[ \t]");
      for (int j = 0; j < entries.length; j++) {
        result.set(i,j,Double.parseDouble(entries[j]));
      }
    }
    return result;
  }
}
