public static Type getTargetType(Method method, Class<?> clazz) {
    Type type = method.getGenericReturnType();
    if (type instanceof TypeVariable) {
        Map<TypeVariable<?>, Type> typeVariableMap = getTypeVariableMap(clazz);
        type = typeVariableMap.getOrDefault(type, type);
    }
    return type;
}

private static Map<TypeVariable<?>, Type> getTypeVariableMap(Class<?> clazz) {
    Map<TypeVariable<?>, Type> typeVariableMap = new HashMap<>();
    if (clazz.getSuperclass() != null) {
        typeVariableMap.putAll(getTypeVariableMap(clazz.getSuperclass()));
    }
    Type[] genericInterfaces = clazz.getGenericInterfaces();
    for (Type genericInterface : genericInterfaces) {
        Class<?> interfaceType;
        if (genericInterface instanceof ParameterizedType) {
            interfaceType = (Class<?>) ((ParameterizedType) genericInterface).getRawType();
        } else {
            interfaceType = (Class<?>) genericInterface;
        }
        Map<TypeVariable<?>, Type> interfaceTypeVariableMap = getTypeVariableMap(interfaceType);
        TypeVariable<?>[] typeVariables = interfaceType.getTypeParameters();
        for (int i = 0; i < typeVariables.length; i++) {
            TypeVariable<?> typeVariable = typeVariables[i];
            Type type = ((ParameterizedType) genericInterface).getActualTypeArguments()[i];
            if (typeVariableMap.containsKey(type)) {
                type = typeVariableMap.get(type);
            } else if (type instanceof TypeVariable) {
                TypeVariable<?> variableType = (TypeVariable<?>) type;
                if (interfaceTypeVariableMap.containsKey(variableType)) {
                    type = interfaceTypeVariableMap.get(variableType);
                }
            }
            typeVariableMap.put(typeVariable, type);
        }
    }
    return typeVariableMap;
}
