public class MyPass {

    private RedeclarationCheckHandler redeclarationHandler;
    private boolean validityCheckMode;

    // Constructor and other methods omitted for brevity

    private ScopeCreator createScopeCreator() {
        ScopeCreator scopeCreator = new ScopeCreator();
        if (!validityCheckMode) {
            scopeCreator.setDeclaratorHandler(redeclarationHandler);
        }
        return scopeCreator;
    }

    private static class RedeclarationCheckHandler implements IDeclaratorHandler {

        private CharArrayMap<IASTDeclaration> declarations = new CharArrayMap<>(10, true);

        @Override
        public boolean checkDeclarator(IASTName declarator, IASTDeclaration declaration) {
            if (declarations.containsKey(declarator.toCharArray())) {
                // Handle redeclaration error
                return false;
            }
            declarations.put(declarator.toCharArray(), declaration);
            return true;
        }
    }
}
