public static boolean checkUpperCase(String str) {
    boolean hasUpperCaseLetters = false;
    for (char c : str.toCharArray()) {
        if (Character.isLetter(c) && !Character.isUpperCase(c)) {
            return false; // if at least one letter is not uppercase, return false
        } else if (Character.isUpperCase(c)) {
            hasUpperCaseLetters = true; // set to true if there is at least one uppercase letter
        }
    }
    return hasUpperCaseLetters; // return true if there are uppercase letters, false otherwise
}
