public double computeRMSE(double[] actualValues, double[] predictedValues) {
    double sum = 0;

    for (int i = 0; i < actualValues.length; i++) {
        double error = actualValues[i] - predictedValues[i];
        sum += error * error;
    }

    double meanSquaredError = sum / actualValues.length;
    double rootMeanSquaredError = Math.sqrt(meanSquaredError);

    return rootMeanSquaredError;
}
