public Class<?> getSystemForClass(Class<?> clazz) {
    SecurityManager security = System.getSecurityManager();
    if (security != null) {
        security.checkPermission(new ReflectPermission("getClassLoader"));
    }
    ClassLoader classLoader = clazz.getClassLoader();

    if (classLoader == null) {
        return ClassLoader.getSystemClassLoader().loadClass(clazz.getName());
    } else {
        String name = clazz.getName().replace('.', '/') + ".class";
        URL resource = classLoader.getResource(name);
        try {
            return Class.forName(clazz.getName(), true, classLoader);
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Failed to load " + clazz, e);
        }
    }
}
