public Set<List<Vertex>> findCycles(DirectedGraph directedGraph) {
    Set<List<Vertex>> cycles = new HashSet<>();

    for (Vertex vertex : directedGraph.getVertices()) {
        visit(vertex, new ArrayList<>(), cycles);
    }

    return cycles;
}

private static void visit(Vertex vertex, List<Vertex> path, Set<List<Vertex>> cycles) {

    for (Vertex childVertex : vertex.getChildren()) {
        if (path.contains(childVertex)) {
            List<Vertex> cycle = new ArrayList<>();
            cycle.addAll(path.subList(path.indexOf(childVertex), path.size()));
            cycle.add(childVertex);
            cycles.add(cycle);
        } else {
            List<Vertex> childPath = new ArrayList<>(path);
            childPath.add(childVertex);
            visit(childVertex, childPath, cycles);
        }
    }
}
