public static String transformTag(List<String> urls, String cfml, String tag, String url) {
    String pattern = "<" + tag + "\\b[^>]*?\\b(href|src)=[\"\']?\\K[^\"\'>]+";
    Pattern regex = Pattern.compile(pattern);
    Matcher matcher = regex.matcher(cfml);
    while (matcher.find()) {
        String href = matcher.group();
        if (!href.startsWith("http") && !href.startsWith("https")) {
            String newUrl = url + href;
            if (urls.contains(newUrl)) {
                continue;
            }
            urls.add(newUrl);
            cfml = cfml.replace(href, newUrl);
        }
    }
    return cfml;
}
