public BoundingBox getOverlapBoundingBox(BoundingBox boundingBox, BoundingBox boundingBox2, boolean allowEmpty) {
    double maxLat = Math.min(boundingBox.getNorthLatitude(), boundingBox2.getNorthLatitude());
    double minLat = Math.max(boundingBox.getSouthLatitude(), boundingBox2.getSouthLatitude());
    double maxLon = Math.min(boundingBox.getEastLongitude(), boundingBox2.getEastLongitude());
    double minLon = Math.max(boundingBox.getWestLongitude(), boundingBox2.getWestLongitude());

    if (!allowEmpty && (minLat > maxLat || minLon > maxLon)) {
        return null;
    }

    return new BoundingBox(maxLat, minLat, maxLon, minLon);
}
