public class NumericVecFromString {

  public static Vec createNumericVecFromString(String src) {
    BufferedString bStr = new BufferedString(src);
    Frame fr = ParseDataset.parse(Key.make(), new Key[]{Key.make()}, new byte[][]{bStr.getBytes()});
    fr = fr.toIced();
    Vec numericVec = fr.anyVec();
    for (long i = 0; i < numericVec.length(); ++i) {
      if (numericVec.isNA(i))
        continue;
      final double value = numericVec.at(i);
      if (Double.isNaN(value)) {
        numericVec.setNA(i);
      } else {
        numericVec.set(i, value);
      }
    }
    return numericVec;
  }

}
