public static <T> Collection<T> sample(Collection<T> c, int n, Random r) {
    List<T> list = new ArrayList<>(c);
    int count = Math.min(n, c.size());
    for (int i = 0; i < count; i++) {
        int rndIndex = r.nextInt(list.size());
        T temp = list.get(i);
        list.set(i, list.get(rndIndex));
        list.set(rndIndex, temp);
    }
    return list.subList(0, count);
}
