public int readVarInt32(byte[] buffer, int offset) {
    int result = 0;
    int shift = 0;
    byte b;
    do {
        if (shift >= 32) {
            throw new RuntimeException("Malformed varint.");
        }
        b = buffer[offset++];
        result |= (b & 0x7f) << shift;
        shift += 7;
    } while ((b & 0x80) != 0);

    return result;
}
