public boolean matchType(Object expectedType, Object actualType) {
    if (expectedType == null || actualType == null) {
        return false;
    }

    if (expectedType instanceof Class) {
        return ((Class<?>) expectedType).isAssignableFrom(actualType.getClass());
    }

    if (expectedType instanceof Type) {
        return ((Type) expectedType).equals(actualType.getClass());
    }

    if (expectedType instanceof TypeCode) {
        return matchTypeByName(((TypeCode) expectedType).id(), actualType.getClass());
    }

    if (expectedType instanceof String) {
        return matchTypeByName((String) expectedType, actualType.getClass());
    }

    return false;
}

private boolean matchTypeByName(String expectedTypeName, Class<?> actualType) {
    try {
        Class<?> expectedTypeClass = Class.forName(expectedTypeName);
        return expectedTypeClass.isAssignableFrom(actualType);
    } catch (ClassNotFoundException e) {
        return false;
    }
}
