public VirtualConnection readHTTPHeaderAndData(int numBytes, ByteBuffer[] requestBuffers) {
    try {
        // Read the header
        ByteBuffer headerBuffer = ByteBuffer.allocate(numBytes);
        int bytesRead = channel.read(headerBuffer);
        if (bytesRead < 0) {
            // End of stream
            return null;
        }

        // Read the data
        ByteBuffer dataBuffer = ByteBuffer.allocate(numBytes - bytesRead);
        bytesRead += channel.read(dataBuffer);
        if (bytesRead > numBytes) {
            // Too many bytes requested
            throw new IllegalArgumentException("Too many bytes requested");
        }

        // Copy the read data into the request buffers
        int bufferIndex = 0;
        for (ByteBuffer buffer : requestBuffers) {
            buffer.put(headerBuffer);
            int remaining = buffer.remaining();
            if (remaining > 0) {
                buffer.put(dataBuffer, bufferIndex, Math.min(remaining, dataBuffer.remaining()));
                bufferIndex += remaining;
            }
        }
        return virtualConnection;
    } catch (IOException e) {
        // Error reading from stream
        return null;
    }
}
