public void autoWiden(int[][] frame1, int[][] frame2) {
  if (frame1[0].length == 0 || frame2[0].length == 0) {
    return; // shortcut if one frame has zero columns
  } else if (frame1[0].length == 1 && frame2[0].length > 1) {
    int val = frame1[0][0];
    int[][] widenedFrame = new int[frame1.length][frame2[0].length];
    for (int i = 0; i < widenedFrame.length; i++) {
      for (int j = 0; j < widenedFrame[0].length; j++) {
        widenedFrame[i][j] = val;
      }
    }
    frame1 = widenedFrame;
  } else if (frame1[0].length > 1 && frame2[0].length == 1) {
    int val = frame2[0][0];
    int[][] widenedFrame = new int[frame2.length][frame1[0].length];
    for (int i = 0; i < widenedFrame.length; i++) {
      for (int j = 0; j < widenedFrame[0].length; j++) {
        widenedFrame[i][j] = val;
      }
    }
    frame2 = widenedFrame;
  } else { // frames have same column count
    for (int i = 0; i < frame1.length; i++) {
      for (int j = 0; j < frame1[0].length; j++) {
        if (frame1[i][j] == -1) {
          frame1[i][j] = frame2[i][j];
        } else if (frame2[i][j] == -1) {
          frame2[i][j] = frame1[i][j];
        }
      }
    }
  }
}
