		} else {

			hessian = new HessianSchurComplement_DDRM();
		}
		UnconLeastSqLevenbergMarquardtSchur_F64<DMatrixRMaj> lm =
				new UnconLeastSqLevenbergMarquardtSchur_F64<>(new MatrixMath_DDRM(),hessian);
		lm.configure(config);
		return lm;
