public void ensureCapacity(int[] ties, int id) {
    if (ties.length == 0) {
        ties = new int[1];
        ties[0] = id;
    } else if (ties.length == 1 && ties[0] == 0) {
        ties[0] = id;
    } else {
        int[] newArray = new int[ties.length + 1];
        System.arraycopy(ties, 0, newArray, 0, ties.length);
        newArray[ties.length] = id;
        ties = newArray;
    }
}
