public static int[] arrayOperationsNondesctructive(int[] arr1, int[] arr2, String operation) {
    int[] resArr = new int[arr1.length];
    if(operation == "+") {
        for (int i = 0; i < arr1.length; i++) {
            resArr[i] = arr1[i] + arr2[i];
        }
    }
    else if (operation == "-") {
        for (int i = 0; i < arr1.length; i++) {
            resArr[i] = arr1[i] - arr2[i];
        }
    }
    else if (operation == "*") {
        for (int i = 0; i < arr1.length; i++) {
            resArr[i] = arr1[i] * arr2[i];
        }
    }
    else if (operation == "/") {
        for (int i = 0; i < arr1.length; i++) {
            resArr[i] = arr1[i] / arr2[i];
        }
    }
    return resArr;
}
