public byte[] getBytes(ByteBuffer buf, int start, int length, boolean copy) {
    if (copy) {
        byte[] bytes = new byte[length];
        for (int i = 0; i < length; i++) {
            bytes[i] = buf.get(start + i);
        }
        return bytes;
    } else {
        if (buf.hasArray()) {
            return Arrays.copyOfRange(buf.array(), start + buf.arrayOffset(), start + buf.arrayOffset() + length);
        } else {
            byte[] bytes = new byte[length];
            for (int i = 0; i < length; i++) {
                bytes[i] = buf.get(start + i);
            }
            return bytes;
        }
    }
}
