public static void rotateImage(int[][] image) {
    int n = image.length;

    // transpose the image
    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            int temp = image[i][j];
            image[i][j] = image[j][i];
            image[j][i] = temp;
        }
    }

    // reverse each row
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n/2; j++) {
            int temp = image[i][j];
            image[i][j] = image[i][n-1-j];
            image[i][n-1-j] = temp;
        }
    }
}
