import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.attribute.FileAttribute;
import java.nio.file.attribute.FileTime;
import java.util.Objects;

public class FileMimeTypeChecker {

    /**
     * Returns the mime type of a file without checking the file extension.
     *
     * @param barr         the bytes of the file.
     * @param defaultValue the default value to return if the mime type cannot be determined.
     * @return the mime type of the file.
     */
    public String getMimeType(byte[] barr, String defaultValue) {
        try (InputStream is = Files.newInputStream(createTempFile(barr))) {
            return Files.probeContentType(createTempFile(barr));
        } catch (IOException e) {
            return defaultValue;
        }
    }

    /**
     * Create a temporary file from the given byte array.
     */
    private Path createTempFile(byte[] barr) throws IOException {
        Path path = Paths.get(Objects.requireNonNull(createTempDir()), "tempfile");
        Files.write(path, barr);
        return path;
    }

    /**
     * Create a temporary directory to hold the temp file.
     */
    private Path createTempDir() throws IOException {
        Path dir = Files.createTempDirectory("tempdir", new FileAttribute[]{});
        dir.toFile().deleteOnExit();
        return dir;
    }
}
