public List<Method> findUnoverriddenMethods(Class<?>[] interfaces) {
    List<Method> unoverriddenMethods = new ArrayList<>();
    for (Class<?> intf : interfaces) {
        for (Method method : intf.getDeclaredMethods()) {
            boolean overridden = false;
            for (Class<?> subIntf : intf.getInterfaces()) {
                if (Arrays.asList(interfaces).contains(subIntf)) {
                    continue;
                }
                try {
                    Method subMethod = subIntf.getMethod(method.getName(), method.getParameterTypes());
                    if (subMethod != null && !subMethod.getDeclaringClass().equals(intf)) {
                        overridden = true;
                        break;
                    }
                } catch (NoSuchMethodException e) {
                    // Method not found, continue search in further extended interface
                }
            }
            if (!overridden) {
                unoverriddenMethods.add(method);
            }
        }
        // Recursively search in extended interfaces
        unoverriddenMethods.addAll(findUnoverriddenMethods(intf.getInterfaces()));
    }
    return unoverriddenMethods;
}
