public Series addSeries(String seriesName, List<?> xData, List<? extends Number> yData, List<? extends Number> errorBars) {
    if (xData.size() != yData.size()) {
        throw new IllegalArgumentException("X-axis and Y-axis data have different sizes.");
    }
    Series series = new Series(seriesName);
    for (int i = 0; i < xData.size(); i++) {
        DataPoint dataPoint = new DataPoint(xData.get(i), yData.get(i));
        if (errorBars != null && i < errorBars.size()) {
            dataPoint.setCustomProperty("ErrorBarValue", errorBars.get(i));
        }
        series.getData().add(dataPoint);
    }
    return series;
}
