public static <E> E yieldOnlyElement(Iterable<E> iterable) {
    Iterator<E> iterator = iterable.iterator();
    if (!iterator.hasNext()) {
        throw new IllegalArgumentException("No elements found");
    }
    E element = iterator.next();
    if (iterator.hasNext()) {
        throw new IllegalStateException("More than one element found");
    }
    return element;
}
