public static double[][] positiveDefiniteCopy(double[][] matrix) {
    // Copy the matrix to a new array
    double[][] copy = new double[matrix.length][matrix[0].length];
    for (int i = 0; i < matrix.length; i++) {
        System.arraycopy(matrix[i], 0, copy[i], 0, matrix[0].length);
    }

    // Compute the eigenvalue decomposition of the matrix
    EigenvalueDecomposition eigen = new EigenvalueDecomposition(new Matrix(copy));
    double[] eigenvalues = eigen.getRealEigenvalues();

    // Find the minimum eigenvalue
    double minEigenvalue = Double.MAX_VALUE;
    for (double val : eigenvalues) {
        if (val < minEigenvalue) {
            minEigenvalue = val;
        }
    }

    // Check if the min eigenvalue is negative or very small
    if (minEigenvalue < 0 || minEigenvalue < Math.ulp(1.0)) {
        // Add a small positive constant to the diagonal of the matrix
        double epsilon = Math.ulp(1.0);
        for (int i = 0; i < copy.length; i++) {
            copy[i][i] += epsilon;
        }
    }

    return copy;
}
