public static void setChannelToNio(Channel channel) {
    EventLoopGroup group = new NioEventLoopGroup();
    ManagedChannel managedChannel = (ManagedChannel) channel;
    managedChannel = managedChannel.toBuilder()
        .eventLoopGroup(group)
        .overrideAuthority(managedChannel.authority())
        .build();
    ManagedChannelProvider.setDefaultLoadBalancingPolicy("round_robin");
    ManagedChannelProvider.builder().defaultSynchronizeChannels(true);
    ManagedChannelProvider.builder().maxHedgedAttempts(10);
    ManagedChannelProvider.builder().keepAliveTime(60, TimeUnit.SECONDS);
    ManagedChannelProvider.builder().keepAliveTimeout(60, TimeUnit.SECONDS);
    ManagedChannelProvider.builder().keepAliveWithoutCalls(true);
    ManagedChannelProvider.builder().idleTimeout(180, TimeUnit.SECONDS);
    ManagedChannelProvider.builder().usePlaintext();
}
