public List<Biomorph> nonRandomMutation(List<Biomorph> selectedCandidates, Random rng) {
    if (selectedCandidates.isEmpty()) {
        return Collections.emptyList();
    }

    List<Biomorph> mutatedCandidates = new ArrayList<>();
    int[] mutatedIndexes = new int[selectedCandidates.size()];

    for (int i = 0; i < selectedCandidates.size(); i++) {
        int newIndex = rng.nextInt(selectedCandidates.size());
        while (contains(mutatedIndexes, newIndex)) {
            newIndex = rng.nextInt(selectedCandidates.size());
        }
        mutatedIndexes[i] = newIndex;
        mutatedCandidates.add(selectedCandidates.get(newIndex).mutate());
    }

    return mutatedCandidates;
}

