public static SimpleRecurrentUnit[] simpleRecurrentUnit(String baseName, Configuration configuration) {
    int memoryDimension = configuration.getMemoryDimension();
    double[][] initialMemory = configuration.getInitialMemory();
    double[][][] weights = configuration.getWeights();
    double[][][] biases = configuration.getBiases();
    double[][][] peepholes = configuration.getPeepholes();

    SimpleRecurrentUnit[] srus = new SimpleRecurrentUnit[memoryDimension];
    for (int i = 0; i < memoryDimension; i++) {
        String outputName = baseName + "_" + i;
        srus[i] = SimpleRecurrentUnit.builder()
                .input(SingleNeuron.builder().name(outputName + "_input").build())
                .previousOutput(SingleNeuron.builder().name(outputName + "_output_previous").build())
                .memory(SingleNeuron.builder().name(outputName + "_memory").initialValue(initialMemory[i][0]).build())
                .updateGate(Sigmoid.builder()
                        .name(outputName + "_update_gate")
                        .weights(weights[i][0])
                        .biases(biases[i][0])
                        .inputNames(outputName + "_input", outputName + "_memory", outputName + "_output_previous")
                        .build())
                .resetGate(Sigmoid.builder()
                        .name(outputName + "_reset_gate")
                        .weights(weights[i][1])
                        .biases(biases[i][1])
                        .inputNames(outputName + "_input", outputName + "_memory", outputName + "_output_previous")
                        .build())
                .output(Sigmoid.builder()
                        .name(outputName + "_output")
                        .weights(weights[i][2])
                        .biases(biases[i][2])
                        .peepholeWeights(peepholes[i])
                        .inputNames(outputName + "_input", outputName + "_reset_gate_output", outputName + "_memory")
                        .build())
                .build();
    }
    return srus;
}
