public static double computeLineLength(List<Point> pts) {
    double length = 0.0;
    Point prevPt = null;
    for (Point pt : pts) {
        if (Double.isNaN(pt.getZ())) {
            return 0.0;
        }
        if (prevPt != null) {
            length += prevPt.distance3D(pt);
        }
        prevPt = pt;
    }
    return length;
}
