    Configuration config = configAdmin.getConfiguration("org.apache.cxf.osgi", null);
    Dictionary<String, Object> mergedProps = new Hashtable<>();

    Enumeration<String> keys = serviceRefProps.keys();
    while(keys.hasMoreElements()) {
        String key = keys.nextElement();
        mergedProps.put(key, serviceRefProps.get(key));
    }

    keys = portProps.keys();
    while(keys.hasMoreElements()) {
        String key = keys.nextElement();
        mergedProps.put(key, portProps.get(key));
    }

    config.update(mergedProps);
}
