@Override
public void addRangeEmpty(int start, int end) {
    if (end <= start) {
        return;
    }
    Node node = root.lookup(start, end, true);
    while (node != null) {
        int cmpStart = Integer.compare(start, node.getStart());
        int cmpEnd = Integer.compare(node.getEnd(), end);
        if (cmpStart > 0) {
            split(node, start);
            node = node.right;
            continue;
        }
        if (cmpEnd > 0) {
            split(node, end);
            node = node.right;
            continue;
        }
        if (cmpStart == 0 && cmpEnd == 0) {
            node.empty = true;
            node = node.parent;
            continue;
        }
        if (cmpStart == 0) {
            split(node, end);
            node = node.parent;
            continue;
        }
        if (cmpEnd == 0) {
            split(node, start);
            node = node.parent;
            continue;
        }
        Node newNode = new Node(start, end, true);
        if (cmpStart < 0 && cmpEnd > 0) {
            Node left = new Node(node.getStart(), start, false);
            Node right = new Node(end, node.getEnd(), false);
            node.setLeft(left);
            left.parent = node;
            node.setRight(right);
            right.parent = node;
            node = newNode;
            continue;
        }
        if (cmpStart < 0) {
            Node left = new Node(node.getStart(), start, false);
            node.setLeft(left);
            left.parent = node;
            node = newNode;
            continue;
        }
        if (cmpEnd > 0) {
            Node right = new Node(end, node.getEnd(), false);
            node.setRight(right);
            right.parent = node;
            node = newNode;
            continue;
        }
    }
    root.maxEnd = Math.max(root.maxEnd, end);
