public static void makeDirectMethodCall(Method method) {
    // get the bridge method, if it exists
    Method bridgeMethod = null;
    for (Method m : method.getDeclaringClass().getDeclaredMethods()) {
        if (m.isBridge() && m.getName().equals(method.getName()) && Arrays.equals(m.getParameterTypes(), method.getParameterTypes())) {
            bridgeMethod = m;
            break;
        }
    }

    // if a bridge method was found, make a direct method call
    if (bridgeMethod != null) {
        try {
            bridgeMethod.setAccessible(true);
            bridgeMethod.invoke(null);
        } catch (IllegalAccessException e) {
            e.printStackTrace();
        } catch (InvocationTargetException e) {
            e.printStackTrace();
        }
    }
