public Set<Integer> getFreeVariableIndexes(String expression, String variableName) {
    Set<Integer> indexes = new HashSet<>();
    int index = 0;
    while (index != -1) {
        index = expression.indexOf(variableName, index);
        if (index != -1) {
            boolean isFreeVariable = true;
            for (int i = 0; i < expression.length(); i++) {
                if (i != index && expression.charAt(i) == variableName.charAt(0)) {
                    if (i > index && expression.substring(index, i).matches("[a-zA-Z0-9_]+")) {
                        isFreeVariable = false;
                        break;
                    } else if (i < index && expression.substring(i, index).matches("[a-zA-Z0-9_]+")) {
                        isFreeVariable = false;
                        break;
                    }
                }
            }
            if (isFreeVariable) {
                indexes.add(index);
            }
            index++;
        }
    }
    return indexes;
}
