public void skipBytes(long size, InputStream input) throws IOException {
    long totalSkipped = 0;
    while (totalSkipped < size) {
        long skipped = input.skip(size - totalSkipped);
        if (skipped == 0) {
            int nextByte = input.read();
            if (nextByte == -1) {
                throw new EOFException("End of stream reached before skipping required bytes");
            }
            skipped = 1;
        }
        totalSkipped += skipped;
    }
}
