public void scaleMolecule(IAtomContainer atomCon, Dimension areaDim, double fillFactor, HashMap renderingCoordinates) {
    double desiredArea = areaDim.getWidth() * areaDim.getHeight() * (fillFactor / 100.0);
    Rectangle2D moleculeBounds = calculateBounds(atomCon, renderingCoordinates);
    double moleculeArea = moleculeBounds.getWidth() * moleculeBounds.getHeight();

    double scaleFactor = Math.sqrt(desiredArea / moleculeArea);

    for (IAtom atom : atomCon.atoms()) {
        Point2d point = (Point2d) renderingCoordinates.get(atom);
        double newX = point.x * scaleFactor + (areaDim.getWidth() - moleculeBounds.getWidth() * scaleFactor) / 2.0;
        double newY = point.y * scaleFactor + (areaDim.getHeight() - moleculeBounds.getHeight() * scaleFactor) / 2.0;
        point.x = newX;
        point.y = newY;
    }
}
