public Statistics fetchSpilloverPolicyStats(Netscaler netscaler) {
        // First, we need to get a list of all spilloverpolicy_stats resources on the Netscaler
        List<SpilloverPolicyStats> spilloverPolicyStatsList = netscaler.getSpilloverPolicyStatsList();

        // We will use this object to accumulate the statistics data
        Statistics statistics = new Statistics();

        // Loop through each spilloverpolicy_stats resource and fetch the statistics data
        for (SpilloverPolicyStats spilloverPolicyStats : spilloverPolicyStatsList) {
            // Use the Netscaler API to fetch the statistics data for this spilloverpolicy_stats resource
            SpilloverPolicyStatsStats stats = netscaler.getSpilloverPolicyStatsStats(spilloverPolicyStats.getName());

            // Add the statistics data to our accumulator object
            statistics.add(stats);
        }

        // Finally, return the accumulated statistics data for all spilloverpolicy_stats resources
        return statistics;
    }
