import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

public static List<String> getNormalForms(String word) {
    List<String> normalForms = new ArrayList<>();
    Locale trLocale = new Locale("tr", "TR"); // Turkish locale
    Locale enLocale = new Locale("en", "US"); // English locale

    String wordLowerCase = word.toLowerCase(trLocale); // Convert the word to lowercase for Turkish
    String wordLowerCaseRemoved = wordLowerCase.replaceAll("[^\\p{L}\\s]", ""); // Remove special characters and digits

    // Get normal forms for Turkish and English
    normalForms.add(wordLowerCaseRemoved);
    normalForms.add(wordLowerCaseRemoved.toLowerCase(trLocale));
    normalForms.add(wordLowerCaseRemoved.toLowerCase(enLocale));
    return normalForms;
}
