            Contents == null || Contents.isEmpty()) {
        throw new PopbillException(-99999999, "필수 입력값이 정상적으로 입력되지 않았습니다.");
    }

    String postData = "";

    postData += "Dm=" + KeyType.toString() + "&";
    postData += "Receiver=" + ReceiverNum + "&";
    postData += "Sender=" + SenderNum + "&";
    postData += "Contents=" + Contents;

    URL url = new URL(getServiceURL() + "/Taxinvoice/SMS");
    HttpURLConnection con = (HttpURLConnection) url.openConnection();
    con.setRequestMethod("POST");
    con.setRequestProperty("Accept", "application/json");
    con.setRequestProperty("Content-Type", "application/x-www-form-urlencoded;charset=UTF-8");

    con.setRequestProperty("Authorization", "Bearer " + getToken(CorpNum));

    con.setDoOutput(true);
    try (OutputStreamWriter wr = new OutputStreamWriter(con.getOutputStream())) {
        wr.write(postData);
        wr.flush();
    }

    int responseCode = con.getResponseCode();
    Response response = new Response();
    response.setCode(responseCode);
    if (responseCode == HttpStatus.SC_OK) {
        response.setMessage(readStream(con.getInputStream()));
    } else {
        response.setMessage(readStream(con.getErrorStream()));
    }
    return response;
}
