public String[] readStringPool(int[] offsets) throws IOException {
    RandomAccessFile raf = new RandomAccessFile("file.dex", "r");
    String[] strings = new String[offsets.length];
    for (int i = 0; i < offsets.length; i++) {
        raf.seek(offsets[i]);
        int size = readUnsignedLeb128(raf);
        byte[] bytes = new byte[size];
        raf.read(bytes);
        strings[i] = new String(bytes, StandardCharsets.UTF_8);
    }
    raf.close();
    return strings;
}

private int readUnsignedLeb128(RandomAccessFile raf) throws IOException {
    int value = 0;
    int shift = 0;
    byte b;
    do {
        b = raf.readByte();
        value |= (b & 0x7f) << shift;
        shift += 7;
    } while ((b & 0x80) != 0);
    return value;
}
