public boolean isEqual(String filename) {
  if(filename == null) {
    return false;
  }
  String extension = getFileExtension(filename);
  if(extension == null || !extension.equals("jpi") && !extension.equals("hpi")) {
    return false;
  }
  String possibleMatch = filename.replace(extension, (extension.equals("hpi") ? "jpi" : "hpi"));
  return new File(possibleMatch).exists();
}

private String getFileExtension(String filename) {
  int dotIndex = filename.lastIndexOf(".");
  if(dotIndex == -1 || dotIndex == filename.length() - 1) {
    return null;
  }
  return filename.substring(dotIndex + 1).toLowerCase();
}
