public void validateSTObject(ST st, Set<String> expectedArguments) {
    if (st == null || expectedArguments == null) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<String> missingArguments = new HashSet<>(expectedArguments);
    Map<String, Object> stAttributes = st.getAttributes();

    for (String key : stAttributes.keySet()) {
        if (missingArguments.contains(key)) {
            missingArguments.remove(key);
        }
    }

    for (String missingArg : missingArguments) {
        st.addMissing(missingArg);
    }
}
