public String getNullValueSelectStatement() {
    for (ColumnType type : types) {
        if (type == ColumnType.STRING || type == ColumnType.TEXT) {
            return "SELECT * FROM table WHERE column_name IS NULL;";
        } else if (type == ColumnType.NUMBER || type == ColumnType.DECIMAL) {
            return "SELECT * FROM table WHERE column_name IS NULL OR column_name = 0;";
        } else if (type == ColumnType.DATE || type == ColumnType.TIME || type == ColumnType.TIMESTAMP) {
            return "SELECT * FROM table WHERE column_name IS NULL OR column_name = '0000-00-00';";
        }
    }
    return null;
}
