public ServiceResponse publishEventsToEventGrid(String topicHostname, Event[] events) throws IllegalArgumentException {

    // validate the parameters
    if (topicHostname == null || topicHostname.isEmpty())
        throw new IllegalArgumentException("Topic host name cannot be null or empty.");

    if (events == null || events.length == 0)
        throw new IllegalArgumentException("Events array cannot be null or empty.");

    // create the Event Grid client to call the API
    EventGridClient client = new EventGridClientBuilder()
        .credential(new AzureKeyCredential(System.getenv("EVENT_GRID_KEY")))
        .endpoint(topicHostname)
        .buildClient();

    // publish the events to the topic
    client.sendEvents(events);

    // return the success response
    return new ServiceResponse(200, "Events successfully published to Event Grid.");
}
