public static Map<String, String> parseLogLine(String logLine) {
    Map<String, String> keyValueMap = new HashMap<>();
    String keyValueString = logLine;
    if (logLine.contains("{")) {
        keyValueString = logLine.substring(logLine.indexOf("{") + 1, logLine.indexOf("}"));
    }
    String[] keyValuePairs = keyValueString.split(",");
    for (String keyValuePair : keyValuePairs) {
        String[] keyValue = keyValuePair.split("=");
        if (keyValue.length >= 2) {
            keyValueMap.put(keyValue[0].trim(), keyValue[1].trim());
        }
    }
    return keyValueMap;
}
