public String updateDocfile(String docfile, String optionsDocumentation) throws Exception {
    try {
        // read the docfile content
        String docContent = readFile(docfile);

        // update the docfile with the options documentation
        String updatedDocContent = docContent.replaceAll("COMMAND-LINE ARGUMENTS", optionsDocumentation);

        // write the updated content to the docfile
        writeFile(docfile, updatedDocContent);

        return updatedDocContent;
    } catch (Exception e) {
        throw new Exception("Error updating docfile: " + e.getMessage());
    }
}

