    public static <T> HashSet<T> adaptToHashSet(Object data, Class<T> type) {
        HashSet<T> set = new HashSet<T>();
        if (data instanceof HashSet<?>) {
            HashSet<?> inputData = (HashSet<?>) data;
            for (Object item : inputData) {
                if (type.isInstance(item)) {
                    set.add(type.cast(item));
                }
            }
        } else {
            if (type.isInstance(data)) {
                set.add(type.cast(data));
            }
        }
        return set;
    }
