public List<View> extractViewsFromActivity(View parent, boolean onlySufficientlyVisible) {
    List<View> views = new ArrayList<>();
    Activity activity = getActivityFromContext(parent.getContext());
    if (activity != null) {
        View decorView = activity.getWindow().getDecorView();
        extractViewsFromParent(decorView, parent, views);
    }
    if (onlySufficientlyVisible) {
        Predicate<View> isViewSufficientlyVisible = view -> view.getWindowVisibility() == View.VISIBLE && view.getAlpha() > 0 && view.getGlobalVisibleRect(new Rect()) && view.getLocalVisibleRect(new Rect()) && view.getWidth() > 0 && view.getHeight() > 0;
        views = views.stream().filter(isViewSufficientlyVisible).collect(Collectors.toList());
    }
    return views;
}

private void extractViewsFromParent(View parent, View searchParent, List<View> views) {
    if (parent instanceof ViewGroup) {
        ViewGroup viewGroup = (ViewGroup) parent;
        for (int i = 0; i < viewGroup.getChildCount(); i++) {
            View child = viewGroup.getChildAt(i);
            if (searchParent == null || searchParent == child) {
                views.add(child);
            }
            extractViewsFromParent(child, searchParent, views);
        }
    }
}

private Activity getActivityFromContext(Context context) {
    if (context instanceof Activity) {
        return (Activity) context;
    } else if (context instanceof ContextWrapper) {
        return getActivityFromContext(((ContextWrapper) context).getBaseContext());
    }
    return null;
}
