public void validateAndRemoveIfOlder(String localId) {
    List<Item> items = repository.getItems();
    for (int i = 0; i < items.size(); i++) {
        if (items.get(i).getLocalId().equals(localId)) {
            for (int j = i + 1; j < items.size(); j++) {
                if (items.get(j).getLocalId().equals(localId) &&
                    items.get(j).getDate().before(items.get(i).getDate())) {
                    repository.removeItem(items.get(j).getId());
                }
            }
        }
    }
}
