public static ByteArrayOutputStream generateFontDictionary(
        HashMap<String, Object> descendant, 
        String subsetPrefix,
        String toUnicode) throws IOException {

    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    OutputStreamWriter ow = new OutputStreamWriter(baos, StandardCharsets.US_ASCII);

    ow.write("<<\n");
    ow.write("/Type /Font\n");
    ow.write("/Subtype /CIDFontType2\n");
    ow.write("/BaseFont /" + subsetPrefix + "+0\n");

    // descendant dictionary
    ow.write("/CIDSystemInfo << /Registry (Adobe) /Ordering (Identity) /Supplement 0 >>\n");
    ow.write("/FontDescriptor " +
            descendant.get("FontDescriptor").toString().replaceFirst("<<", "<</" + subsetPrefix));
    ow.write("/DW " + descendant.get("DW").toString() + "\n");
    ow.write("/W " + descendant.get("W").toString() + "\n");
    ow.write("/CIDToGIDMap /Identity\n");

    // ToUnicode stream
    if (toUnicode != null) {
        ow.write("/ToUnicode " + toUnicode + "\n");
    }

    ow.write(">>\n");
    ow.flush();
    return baos;
}
