import java.time.*;
import java.time.format.*;
import java.util.*;

public class DatePartToInt {

    public static int getDatePartAsInt(String dateExpression, String part) throws IllegalArgumentException {
        LocalDate date;
        try {
            date = LocalDate.parse(dateExpression, DateTimeFormatter.ISO_LOCAL_DATE);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("Invalid date expression: " + dateExpression);
        }
        int result;
        switch (part.toLowerCase()) {
            case "year":
                result = date.getYear();
                break;
            case "month":
                result = date.getMonthValue();
                break;
            case "day":
                result = date.getDayOfMonth();
                break;
            case "dayofyear":
                result = date.getDayOfYear();
                break;
            case "dayofweek":
            case "weekday":
                result = date.getDayOfWeek().getValue();
                break;
            default:
                throw new IllegalArgumentException("Invalid date part: " + part);
        }
        return result;
    }

}
