import java.awt.image.BufferedImage;
import java.util.Random;

public class ImageUtils {

    public static BufferedImage randomlyCropImage(BufferedImage image, Random random){
        if(image == null){
            return null;
        }

        // Get the width and height of the input image
        int width = image.getWidth();
        int height = image.getHeight();

        int newWidth = random.nextInt(width);
        int newHeight = random.nextInt(height);

        // Check if the newWidth and newHeight values are greater than zero
        if(newWidth == 0 || newHeight == 0) {
            return null;
        }

        // Create a new BufferedImage object and crop the input image
        BufferedImage newImage = new BufferedImage(newWidth, newHeight, image.getType());
        newImage = image.getSubimage(0, 0, newWidth, newHeight);

        return newImage;
    }
}
