public static long waitForNextTick(long currentTick, long tickSize) throws InterruptedException {
    long now = System.currentTimeMillis();
    long nextTick = ((now / tickSize) + 1) * tickSize;
    long sleepTime = nextTick - now;
    if(sleepTime > 0) {
        Thread.sleep(sleepTime);
    }
    return nextTick;
}
