public String[] translatePosTagSequence(String[] posTagSequence) {
    String[] internalRepresentation = new String[posTagSequence.length];
    for (int i = 0; i < posTagSequence.length; i++) {
        if (posTagSequence[i].startsWith("N")) {
            internalRepresentation[i] = "noun";
        } else if (posTagSequence[i].startsWith("V")) {
            internalRepresentation[i] = "verb";
        } else if (posTagSequence[i].startsWith("JJ")) {
            internalRepresentation[i] = "adjective";
        } else if (posTagSequence[i].startsWith("RB")) {
            internalRepresentation[i] = "adverb";
        } else {
            internalRepresentation[i] = "other";
        }
    }
    return internalRepresentation;
}
