import javax.xml.xpath.XPath;
import org.apache.xalan.extensions.XPathFunctionResolverImpl;
import org.apache.xalan.extensions.ExtensionHandlerJavaPackage;
import org.apache.xpath.XPathProcessorImpl;

public static void makeXPathXalanExtensionAware(XPath xpath) {
    XPathProcessorImpl xpathProcessor = (XPathProcessorImpl) xpath;
    xpathProcessor.getXPathContext().getNamespaceContext().setNamespace(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE, ExtensionHandlerJavaPackage.PACKAGE_NAMESPACE);

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":redirect",
                    new org.apache.xalan.lib.Redirect());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":evaluate",
                    new org.apache.xpath.functions.FuncExtFunction());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":lines",
                    new org.apache.xalan.lib.Lines());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":nodeset",
                    new org.apache.xalan.lib.NodeSetExtension());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":objectType",
                    new org.apache.xalan.lib.ObjectType());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":request",
                    new org.apache.xalan.lib.SendMail());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":transform",
                    new org.apache.xalan.lib.Transform());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":unparsed-entity-uri",
                    new org.apache.xpath.functions.FuncUnparsedEntityUri());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":document",
                    new org.apache.xalan.extensions.ExtensionsTable().newDocumentFunction());

    xpathProcessor.getXPathContext().getFunctionTable()
            .installFunction(XPathFunctionResolverImpl.XALAN_EXTENSIONS_NAMESPACE + ":node-set",
                    new org.apache.xpath.objects.XNodeSetForDOM());
}
