public void drawString(AttributedCharacterIterator iterator, int x, int y) {
    // check if iterator is not null
    if(iterator == null) throw new IllegalArgumentException("Iterator cannot be null");

    // create a graphics object
    Graphics g = this.getGraphics();

    // set the color and font of the iterator
    g.setColor((Color) iterator.getAttribute(TextAttribute.FOREGROUND));
    g.setFont((Font) iterator.getAttribute(TextAttribute.FONT));

    // create a string from the iterator
    StringBuilder sb = new StringBuilder();
    for (char c = iterator.first(); c != CharacterIterator.DONE; c = iterator.next()) {
        sb.append(c);
    }
    String str = sb.toString();

    // draw the string at (x,y)
    g.drawString(str, x, y);
}
