public List<List<Integer>> getCyclesInGraph(int[][] graph) {
    List<List<Integer>> cycles = new ArrayList<>();

    boolean[] visited = new boolean[graph.length];
    for (int i = 0; i < graph.length; i++) {
        if (!visited[i]) {
            List<Integer> cycle = new ArrayList<>();
            getCycle(graph, visited, i, -1, cycle);
            if (cycle.size() > 1 || (cycle.size() == 1 && graph[cycle.get(0)][cycle.get(0)] == 1)) {
                cycles.add(cycle);
            }
        }
    }

    return cycles;
}

private void getCycle(int[][] graph, boolean[] visited, int vertex, int parent, List<Integer> cycle) {
    visited[vertex] = true;
    cycle.add(vertex);

    for (int i = 0; i < graph.length; i++) {
        if (graph[vertex][i] == 1) {
            if (i != parent && visited[i]) {
                int index = cycle.indexOf(i);
                if (index != -1) {
                    cycle.subList(0, index).clear();
                }
            } else if (!visited[i]) {
                getCycle(graph, visited, i, vertex, cycle);
            }
        }
    }
}
