public double rescale(double value, double maxAbsolute) {
    if (Double.isNaN(value)) {
        return 0.0;
    } else if (value == Double.POSITIVE_INFINITY) {
        return maxAbsolute;
    } else if (value == Double.NEGATIVE_INFINITY) {
        return -maxAbsolute;
    } else {
        return value * maxAbsolute;
    }
}
