public void writeObjectPointerToTable(Object obj, Object[][] tables) {
    if (tables.length == 2) { // if we are in the process of doubling
        int index = obj.hashCode() & (tables[0].length - 1); // find index using hashcode
        if (tables[0][index] == null) { // if index is empty in first table
            tables[0][index] = obj; // update in first table
        } else { // if collision occurs in first table
            tables[1][index] = obj; // update in second table
        }
    } else { // if only one table is active
        int index = obj.hashCode() & (tables[0].length - 1);
        tables[0][index] = obj; // update in table
    }
}
