public void readData(RandomAccessFile raf, String gateRange, int ii[]) throws IOException {
    // Convert the gate range string to array of integers
    String[] rangeArray = gateRange.split("-");
    int start = Integer.parseInt(rangeArray[0]);
    int end = Integer.parseInt(rangeArray[1]);

    // Total number of integers to read
    int count = end - start + 1;

    // Allocate memory for the array
    int[] data = new int[count];

    // Set file pointer to the starting position
    raf.seek(start * 4); // Multiplying by 4 as each integer is 4 bytes long

    // Read the data from the file
    for(int i = 0; i < count; i++) {
        data[i] = raf.readInt();
    }

    // Copy the data to the ii array
    System.arraycopy(data, 0, ii, 0, count);
}
