/**
 * Returns the first n characters of the given string, or the entire string if it is shorter than n.
 *
 * @param str the string to extract characters from
 * @param n   the number of characters to extract
 * @return a substring of the first n characters of str, or the entire string if it is shorter than n
 */
public static String getFirstNCharacters(String str, int n) {
    if (str == null || str.length() == 0 || n <= 0) {
        return "";
    } else if (n >= str.length()) {
        return str;
    } else {
        return str.substring(0, n);
    }
}
