public Node applyFilterAndGetParent(Node current, String whatToShow) {
    Node parent = current.getParentNode();
    if (parent != null) {
        // Apply filter
        if (whatToShow.equals("text")) {
            if (parent.getNodeType() == Node.TEXT_NODE) {
                // Set current Node if result is not null
                if (parent.getNodeValue() != null) {
                    current = parent;
                }
            }
        } else if (whatToShow.equals("element")) {
            if (parent.getNodeType() == Node.ELEMENT_NODE) {
                // Set current Node if result is not null
                if (parent.getNodeName() != null) {
                    current = parent;
                }
            }
        }
    }
    return parent;
}
