public static int calcLOBHashCode(long seed, byte[] lobData) {
    CRC32 crc = new CRC32();
    crc.update(lobData);
    long crcValue = crc.getValue();
    int hashCode = (int) (seed ^ crcValue);
    return hashCode;
}
