public static MessageTuple convertToMessageTuple(String messagePattern, Object... args) {
    if (args != null && args.length > 0 && args[args.length - 1] instanceof Throwable) {
        // If the last argument is a Throwable, remove it from the arguments array to be used later
        Throwable throwable = (Throwable) args[args.length - 1];
        Object[] newArgs = new Object[args.length - 1];
        System.arraycopy(args, 0, newArgs, 0, args.length - 1);
        args = newArgs;
        return new MessageTuple(MessageFormat.format(messagePattern, args), throwable);
    } else {
        return new MessageTuple(MessageFormat.format(messagePattern, args), null);
    }
}
