public void performSASLAuthentication(String token) throws SASLAuthenticationException {
    try {
        boolean authenticated = false;
        while (!authenticated) {
            byte[] challenge = getSASLChallenge(token);
            if (challenge == null) {
                authenticated = true;
            } else {
                token = generateSASLResponse(challenge);
            }
        }
    } catch (SASLAuthenticationException e) {
        throw new SASLAuthenticationException("SASL authentication failed", e);
    }
}

