public int[] computeMemoryUsage(SceneBlock sceneBlock, HashMap<Integer, Integer> countedTiles) {
    int[] memoryUsage = new int[3];
    for (Tile tile : sceneBlock.getBaseTiles()) {
        if (!countedTiles.containsKey(tile.getId())) {
            countedTiles.put(tile.getId(), 1);
            memoryUsage[0] += tile.getMemoryUsage();
        }
    }
    for (Tile tile : sceneBlock.getFringeTiles()) {
        if (!countedTiles.containsKey(tile.getId())) {
            countedTiles.put(tile.getId(), 1);
            memoryUsage[1] += tile.getMemoryUsage();
        }
    }
    for (Tile tile : sceneBlock.getObjectTiles()) {
        if (!countedTiles.containsKey(tile.getId())) {
            countedTiles.put(tile.getId(), 1);
            memoryUsage[2] += tile.getMemoryUsage();
        }
    }
    return memoryUsage;
}
