public class PoolSchedulable {
    // Fields for the group and pool names
    private String group;
    private String pool;

    // Constructor to set the group and pool names
    public PoolSchedulable(String group, String pool) {
        this.group = group;
        this.pool = pool;
    }

    // Getters for the group and pool names
    public String getGroup() {
        return group;
    }
    public String getPool() {
        return pool;
    }
}

public class Scheduler {
    // List to store all created PoolSchedulables
    private List<PoolSchedulable> pools = new ArrayList<>();

    // Method to get or create a PoolSchedulable with a given name
    public PoolSchedulable getSchedulable(Map<String, String> poolInfo) {
        String group = poolInfo.get("group");
        String pool = poolInfo.get("pool");

        // Check if there is already a PoolSchedulable with the given name
        for (PoolSchedulable p : pools) {
            if (p.getGroup().equals(group) && p.getPool().equals(pool)) {
                return p;
            }
        }

        // If not, create a new PoolSchedulable and add it to the list
        PoolSchedulable newPool = new PoolSchedulable(group, pool);
        pools.add(newPool);
        return newPool;
    }
}
