      Resource originResource = getResourceFromURI(origin);
      for (Resource resource : getAllResources()) {
         if (resource.getType() == type && resource.matches(originResource)) {
            resourcesTable.put(origin, resource.getURI().toString(), resource);
         }
      }
   }
   return resourcesTable;
}
