public static int countItemsInAdapter(Adapter adapter, boolean countHeaders) {
    int count = 0;
    for (int i = 0; i < adapter.getCount(); i++) {
        count++;
        if (adapter instanceof ExpandableListAdapter) { //check if adapter has subitems
            ExpandableListAdapter expandableListAdapter = (ExpandableListAdapter) adapter;
            int numberOfSubItems = expandableListAdapter.getNumberOfChildren(i);
            if (countHeaders) {
