public boolean processLockRequest(boolean lockRequest) throws JournalException {
    if(lockRequest) {
        try {
            File lockAcceptedFile = new File("lockAccepted.txt");
            if(lockAcceptedFile.createNewFile()) {
                return true;
            } else {
                return false;
            }
        } catch(IOException e) {
            throw new JournalException("Failed to create 'lock accepted' file.");
        }
    } else {
        File lockAcceptedFile = new File("lockAccepted.txt");
        if(lockAcceptedFile.exists()) {
            lockAcceptedFile.delete();
        }
        return false;
    }
}
