public void validateSequenceNextId(int nextIdToGive) {
    int maxValue = 0;

    // loop through all tables to get the maximum primary key value
    for (Table table : tables) {
        int primaryKeyMaxValue = table.getPrimaryKeyMaxValue();
        if (primaryKeyMaxValue > maxValue) {
            maxValue = primaryKeyMaxValue;
        }
    }

    // check if next id to give is greater than the maximum primary key value
    if (nextIdToGive <= maxValue) {
        nextIdToGive = maxValue + 1;
    }
}
