public void validateHTMLFile(String validationResultDir, Properties props, File file) throws IOException {
    String validationUrl = props.getProperty(WebConstants.W3C_MARKUP_VALIDATION_URL);
    String validationLevel = props.getProperty(WebConstants.W3C_MARKUP_VALIDATION_LEVEL);

    // Create the URL for the validation request
    String url = validationUrl + "?out=json&level=" + validationLevel + "&doc=" + file.toURI().toString();

    // Send the HTTP request to the validation service
    HttpURLConnection connection = (HttpURLConnection) new URL(url).openConnection();
    connection.setRequestMethod("GET");
    connection.setRequestProperty("Accept", "application/json");

    // Save the validation result to a file
    try (InputStream inputStream = connection.getInputStream();
        OutputStream outputStream = new FileOutputStream(new File(validationResultDir, file.getName() + ".json"))) {
        byte[] buffer = new byte[4096];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            outputStream.write(buffer, 0, bytesRead);
        }
    }
}
