public boolean hasCyclicDependencies(Map<String, Set<String>> definitions) {
    Map<String, Set<String>> dependencies = new HashMap<>();

    for (Map.Entry<String, Set<String>> entry : definitions.entrySet()) {
        Set<String> variables = new HashSet<>(entry.getValue());
        variables.retainAll(definitions.keySet());
        dependencies.put(entry.getKey(), variables);
    }

    Set<String> visited = new HashSet<>();
    Set<String> path = new HashSet<>();

    for (String variable : definitions.keySet()) {
        if (hasCyclicDependenciesHelper(visited, path, dependencies, variable)) {
            return true;
        }
    }

    return false;
}

private boolean hasCyclicDependenciesHelper(Set<String> visited, Set<String> path, Map<String, Set<String>> dependencies, String variable) {
    if (visited.contains(variable)) {
        return false;
    }

    visited.add(variable);
    path.add(variable);

    for (String dependency : dependencies.getOrDefault(variable, new HashSet<>())) {
        if (path.contains(dependency) || hasCyclicDependenciesHelper(visited, path, dependencies, dependency)) {
            return true;
        }
    }

    path.remove(variable);

    return false;
}
