public static int expandCluster(int clusterid, int[] clusterids, KNNQuery knnq, List<Integer> neighbors, double maxkdist, ProgressLogger progress) {
    int clusterSize = 0;
    int neighborIdx = 0;
    while (neighborIdx < neighbors.size()) {
        int other = neighbors.get(neighborIdx++);
        if (clusterids[other] == 0) {
            clusterids[other] = clusterid;
            List<Integer> secondNeighbors = knnq.getNeighbors(other, maxkdist);
            if (secondNeighbors.size() >= knnq.getMinPts()) {
                neighbors.addAll(secondNeighbors);
            }
        }
        if (clusterids[other] != clusterid) {
            continue;
        }
        clusterSize++;
        progress.incrementProcessedItems();
    }
    return clusterSize;
}
