public void advanceNode(int pos) {
    if(pos < 0 || pos >= queueSize){
        System.out.println("Invalid position: "+pos);
        return;
    }
    int current = pos;
    int parent = (current - 1) / 2;
    while(current > 0 && queue.get(current).compareTo(queue.get(parent)) > 0){
        swapNodes(current, parent);
        current = parent;
        parent = (current - 1) / 2;
    }
}
