public CompositeScore updateCompositeScore(CompositeScore compositeScore, List<FilteringRemainder> newRemainders) {
    compositeScore.setFilteringRemainder(newRemainders);
    double recalculatedCoveringMatches = 0.0;
    for (FilteringRemainder remainder : newRemainders) {
        recalculatedCoveringMatches += remainder.getCoveringMatches();
    }
    compositeScore.setCoveringMatches(recalculatedCoveringMatches);
    return compositeScore;
}
