public int getMatrixRank(double t) {
    int rank = 0;
    double tolerance = Math.max(rows, columns) * t * Math.abs(matrix[0]);
    for (int i = 0; i < columns; i++) {
        int pivotRow = rank;
        double pivotElement = Math.abs(matrix[pivotRow][i]);
        for (int j = rank + 1; j < rows; j++) {
            double currElement = Math.abs(matrix[j][i]);
            if (currElement > pivotElement) {
                pivotElement = currElement;
                pivotRow = j;
            }
        }
        if (pivotElement <= tolerance) {
            continue;
        }
        swapRows(rank, pivotRow);
        for (int j = rank + 1; j < rows; j++) {
            double f = matrix[j][i] / matrix[rank][i];
            for (int k = i + 1; k < columns; k++) {
                matrix[j][k] -= matrix[rank][k] * f;
            }
            matrix[j][i] = 0;
        }
        rank++;
        if (rank == Math.min(rows, columns)) {
            break;
        }
    }
    return rank;
}
