import java.beans.PropertyDescriptor;
import java.beans.IntrospectionException;
import java.beans.Introspector;
import java.lang.reflect.InvocationTargetException;

public PropertyDescriptor getPropertyDescriptor(Object instance, Object propertyValue) throws IntrospectionException {
    PropertyDescriptor[] propertyDescriptors = Introspector.getBeanInfo(instance.getClass()).getPropertyDescriptors();
    for (PropertyDescriptor propertyDescriptor : propertyDescriptors) {
        try {
            Object value = propertyDescriptor.getReadMethod().invoke(instance);
            if (value != null && value.equals(propertyValue)) {
                return propertyDescriptor;
            }
        } catch (IllegalAccessException | InvocationTargetException ex) {
            // Handle the exception
        }
    }
    return null; // PropertyDescriptor not found
}
