public static double computeVariance(Mat img, double mean) {
    double sum = 0;
    double var = 0;
    for (int i = 0; i < img.rows(); i++) {
        for (int j = 0; j < img.cols(); j++) {
            double pixelValue = img.get(i, j)[0];
            sum += Math.pow(pixelValue - mean, 2);
        }
    }
    var = sum / (img.rows() * img.cols());
    return var;
}
