public static int[] insertValueIntoArray(int[] originalArray, int insertValue, int insertIndex) {
    int[] newArray = new int[originalArray.length + 1]; // create a new array with length one larger than original array
    for (int i = 0; i < insertIndex; i++) {
        newArray[i] = originalArray[i]; // copy elements from original array up to insert index
    }
    newArray[insertIndex] = insertValue; // insert value at specified index
    for (int i = insertIndex + 1; i < newArray.length; i++) {
        newArray[i] = originalArray[i - 1]; // copy remaining elements from original array shifted one position
    }
    return newArray;
}
