public CounterValue createInitialCounterValue(CounterConfiguration configuration) {
    int initialValue = configuration.getDefaultValue();
    CounterType counterType = configuration.getCounterType();
    switch(counterType) {
        case INCREMENT:
            return new IncrementCounterValue(initialValue);
        case DECREMENT:
            return new DecrementCounterValue(initialValue);
        case RANDOM:
            int maxValue = configuration.getMaxValue();
            return new RandomCounterValue(initialValue, maxValue);
        default:
            throw new IllegalArgumentException("Invalid counter type: " + counterType);
    }
}
