public Set<NFAState> createDFAState(Set<NFAState> scope) {
   Set<NFAState> result = new HashSet<>();
   Queue<NFAState> stateQueue = new LinkedList<>();

   for (NFAState state : scope) {
      stateQueue.offer(state);
   }

   while (!stateQueue.isEmpty()) {
      NFAState currState = stateQueue.poll();

      for (NFAEdge edge : currState.getOutgoingEdges()) {
         if (edge.isEpsilonTransition()) {
            NFAState nextState = edge.getTargetState();

            if (!result.contains(nextState)) {
               result.add(nextState);
               stateQueue.offer(nextState);
            }
         }
      }
   }

   return result;
}
