public void readPESignature(File file) throws FileFormatException, IOException {
    RandomAccessFile raf = new RandomAccessFile(file, "r");
    int peOffset = 0;
    byte[] signature = new byte[4];

    // read signature
    raf.read(signature);
    if (signature[0] != 'M' || signature[1] != 'Z') {
        throw new FileFormatException("Not a PE file");
    }

    // skip to PE header
    raf.seek(60);
    byte[] peHeaderOffset = new byte[4];
    raf.read(peHeaderOffset);

    // calculate and set peOffset
    peOffset = ByteBuffer.wrap(peHeaderOffset).getInt();
    raf.close();
    this.peOffset = peOffset;
}
