public static void addBeanPropertyAlias(String alias, Class<?> type, String name) {
    PropertyDescriptor[] descriptors = BeanUtils.getPropertyDescriptors(type);
    for (PropertyDescriptor descriptor : descriptors) {
        if (descriptor.getName().equals(name)) {
            BeanUtils.addPropertyChangeListener(descriptor.getName(), evt -> {
                String propertyName = evt.getPropertyName();
                if (propertyName.equals(alias)) {
                    try {
                        Method writer = descriptor.getWriteMethod();
                        Object value = evt.getNewValue();
                        writer.invoke(evt.getSource(), value);
                    } catch (IllegalAccessException | InvocationTargetException ex) {
                        throw new RuntimeException("Failed to set property " + alias + " on " + type + " with value " + evt.getNewValue(), ex);
                    }
                }
            });
            return;
        }
    }
    throw new IllegalArgumentException("Invalid bean property '" + name + "' for type " + type);
}
