public void addRepeatableAnnotationValue(String annotationName, String annotationValue) {
   RepeatableAnnotation repeatableAnnotation = this.getClass().getAnnotation(RepeatableAnnotation.class);
   if(repeatableAnnotation != null) {
      Annotation[] annotations = repeatableAnnotation.value();
      List<Annotation> annotationList = new ArrayList<>(Arrays.asList(annotations));
      boolean exists = false;
      for (Annotation annotation : annotationList) {
         if (annotation.annotationType().getSimpleName().equals(annotationName)) {
            exists = true;
            InvokerHelper.setProperty(annotation, "value", ArrayUtils.add((String[]) InvokerHelper.getProperty(annotation, "value"), annotationValue));
            break;
         }
      }
      if (!exists) {
         try {
            Class<?> annotationClass = Class.forName(annotationName);
            Annotation[] newAnnotations = (Annotation[]) ArrayUtils.add(annotations, Proxy.newProxyInstance(annotationClass.getClassLoader(),
                  new Class<?>[]{annotationClass}, (proxy, method, args) -> {
                     if (method.getName().equals("value")) {
                        return new String[]{annotationValue};
                     } else if (method.getName().equals("annotationType")) {
                        return annotationClass;
                     }
                     return null;
                  }));
            Method annotationMethod = this.getClass().getClassLoader().getClass().getDeclaredMethod("annotationData");
            annotationMethod.setAccessible(true);
            Object annotationData = annotationMethod.invoke(this.getClass().getClassLoader());
            Field annotationsField = annotationData.getClass().getDeclaredField("annotations");
            annotationsField.setAccessible(true);
            annotationsField.set(annotationData, newAnnotations);
         } catch (ClassNotFoundException | NoSuchMethodException | IllegalAccessException |
                 InvocationTargetException | NoSuchFieldException e) {
            throw new RuntimeException(e);
         }
      }
   }
}
