public Object[] getPKValues(Object objectOrProxy, boolean convertToSql) throws PersistenceBrokerException {
    if(objectOrProxy == null) {
        return new Object[]{};
    }
    if(objectOrProxy instanceof Proxy || objectOrProxy instanceof VirtualProxy) {
        return ((Identity)objectOrProxy).getPrimaryKeyValues();
    } else if(convertToSql) {
        return broker.serviceSql().getPreparedStatementCreator(objectOrProxy.getClass(), 
                                                                OJBqlStatement.SELECT, 
                                                                null, 
                                                                null, 
                                                                true).getSqlParams(objectOrProxy);
    } else {
        return broker.serviceIdentity().getPkValues(objectOrProxy);
    }
}
