public static String getFirstArgument(String inString) {
    if (inString == null || inString.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }
    int startIndex = 0;
    int endIndex = inString.length() - 1;
    if (inString.charAt(startIndex) == '(') {
        int endBracketIndex = inString.indexOf(')');
        if (endBracketIndex == -1 || endBracketIndex == endIndex) {
            throw new IllegalArgumentException("Invalid input string");
        }
        endIndex = endBracketIndex;
        startIndex = inString.indexOf(',') + 1;
        if (startIndex == 0) {
            throw new IllegalArgumentException("Invalid input string");
        }
    } else {
        endIndex = inString.indexOf(',');
        if (endIndex == -1) {
            endIndex = inString.length();
        }
    }
    return inString.substring(startIndex, endIndex).trim();
}
