public static String extractCellValue(byte[] value, int value_idx, byte flags) throws IllegalDataException {
    if (value == null || value.length <= value_idx) {
        throw new IllegalDataException("Invalid value data");
    }

    int length = Bytes.toInt(value, value_idx, Bytes.SIZEOF_INT);
    if ((flags & HConstants.DEFLATE_COMPRESSION) == HConstants.DEFLATE_COMPRESSION) {
        value_idx += Bytes.SIZEOF_INT;
        int uncompressedSize = Bytes.toInt(value, value_idx, Bytes.SIZEOF_INT);
        if (uncompressedSize < 0) {
            throw new IllegalDataException("Illegal uncompressed size " + uncompressedSize);
        }
        value_idx += Bytes.SIZEOF_INT;
        byte[] uncompressed = new byte[uncompressedSize];
        try {
            Compression.decompress(value, value_idx, length, uncompressed, 0);
        } catch (IOException e) {
            throw new IllegalDataException("Failed to decompress the value", e);
        }
        return Bytes.toStringBinary(uncompressed);
    }

    return Bytes.toString(value, value_idx + Bytes.SIZEOF_INT, length);
}
