public void calculateSparkline(int WIDTH, int HEIGHT) {
    //assuming DATA_LIST is a global variable containing the data to plot
    int[] data = DATA_LIST.toArray(new int[0]);

    //calculate the minimum and maximum values in the data array
    int minVal = data[0];
    int maxVal = data[0];
    for (int i = 1; i < data.length; i++) {
        if (data[i] < minVal) {
            minVal = data[i];
        }
        if (data[i] > maxVal) {
            maxVal = data[i];
        }
    }

    //scale the data to fit within the specified width and height
    double xScale = (double) WIDTH / (double) data.length;
    double yScale = (double) HEIGHT / (double) (maxVal - minVal);
    int[] scaledData = new int[data.length];
    for (int i = 0; i < data.length; i++) {
        scaledData[i] = (int) ((data[i] - minVal) * yScale);
    }

    //plot the scaled data using asterisks and spaces to create a sparkline
    for (int i = 0; i < HEIGHT; i++) {
        for (int j = 0; j < WIDTH; j++) {
            if (i == HEIGHT - scaledData[j]) {
                System.out.print("*");
            } else {
                System.out.print(" ");
            }
        }
        System.out.println();
    }
}
