public class JournalManager {
    private Journal currentJournal;

    public void createNewJournal(String text, String date) {
        Journal newJournal = new Journal(text, date);

        // Check if there is a current journal
        if (currentJournal != null) {
            // Check if the new journal is different from the current one
            if (!newJournal.getText().equals(currentJournal.getText()) ||
                    !newJournal.getDate().equals(currentJournal.getDate())) {
                // Replace the current journal with the new one
                currentJournal = newJournal;
            }
        } else {
            // There is no current journal, create a new one
            currentJournal = newJournal;
        }
    }
}
