public enum FirstReferenceType {
    READ,
    KILL,
    MAY_LIVE
}

public static FirstReferenceType getFirstReferenceType(String expression, String variable) {
    int index = expression.indexOf(variable);
    if (index == -1) {
        return FirstReferenceType.MAY_LIVE;
    } else {
        char prevChar = index - 1 > 0 ? expression.charAt(index - 1) : ' ';
        char nextChar = index + variable.length() < expression.length() ? expression.charAt(index + variable.length()) : ' ';
        if (prevChar == ' ' && nextChar == '=') {
            return FirstReferenceType.KILL;
        } else {
            return FirstReferenceType.READ;
        }
    }
}
