public static boolean addOneToByteArray(byte[] value) {
    int i = value.length - 1;
    while (i >= 0 && value[i] == (byte) 0xFF) {
        value[i] = (byte) 0x00;
        i--;
    }
    if (i < 0) {
        return false;
    }
    value[i]++;
    return true;
}
