public AndroidPublisher setupAPI(String applicationName, String serviceAccountEmail) throws GeneralSecurityException, IOException {
    NetHttpTransport transport = GoogleNetHttpTransport.newTrustedTransport();
    JsonFactory factory = JacksonFactory.getDefaultInstance();

    GoogleCredentials credentials;
    if(serviceAccountEmail.isEmpty()) {
        credentials = GoogleCredentials.getApplicationDefault()
                .createScoped(Collections.singleton(AndroidPublisherScopes.ANDROIDPUBLISHER));
    } else {
        credentials = new ServiceAccountCredentials.Builder()
                .setTransport(transport)
                .setJsonFactory(factory)
                .setServiceAccountId(serviceAccountEmail)
                .setServiceAccountScopes(Collections.singleton(AndroidPublisherScopes.ANDROIDPUBLISHER))
                .build();
    }

    AndroidPublisher.Builder builder = new AndroidPublisher.Builder(transport, factory, credentials)
            .setApplicationName(applicationName);

    return builder.build();
}
