public RectF getViewBox() throws IllegalArgumentException {
   if (svgDocument == null) {
      throw new IllegalArgumentException("No SVG document is loaded.");
   }
   String viewBoxStr = svgDocument.getRootElement().getAttribute("viewBox");
   if (viewBoxStr == null || viewBoxStr.isEmpty()) {
      return null;
   }
   String[] viewBoxValues = viewBoxStr.split("\\s+");
   if (viewBoxValues.length != 4) {
      return null;
   }
   float left = Float.parseFloat(viewBoxValues[0]);
   float top = Float.parseFloat(viewBoxValues[1]);
   float width = Float.parseFloat(viewBoxValues[2]);
   float height = Float.parseFloat(viewBoxValues[3]);
   return new RectF(left, top, left + width, top + height);
}
