public static double computeFalsePositiveProbability(int inputEntries, int bitSize) {
    double m = bitSize;
    double n = inputEntries;
    double k = Math.ceil(m / n * Math.log(2));
    double p = Math.pow(1 - Math.exp(-k * n / m), k);
    return Math.pow(p, k);
}
