import java.util.Arrays;

public class ConfidenceInterval {
    public static double[] binomialConfidenceInterval(int successes, int trials, double confidence) {
        double lowerBound, upperBound;
        int n = trials;
        int x = successes;
        double p = (double) x / n;
        double z = getCriticalValue(confidence);
        double delta = z * Math.sqrt(p * (1 - p) / n);
        lowerBound = p - delta;
        upperBound = p + delta;
        return new double[]{lowerBound, upperBound};
    }

    private static double getCriticalValue(double confidence) {
        double z;
        if (confidence == 0.90) {
            z = 1.645;
        } else if (confidence == 0.95) {
            z = 1.96;
        } else if (confidence == 0.98) {
            z = 2.33;
        } else if (confidence == 0.99) {
            z = 2.58;
        } else {
            throw new IllegalArgumentException("Valid confidence levels: 0.90, 0.95, 0.98, 0.99");
        }
        return z;
    }

    public static void main(String[] args) {
        int successes = 50;
        int trials = 100;
        double confidence = 0.95;
        double[] interval = binomialConfidenceInterval(successes, trials, confidence);
        System.out.println("Binomial confidence interval for " + successes + " successes in " + trials + " trials with " +
                confidence + " confidence: " + Arrays.toString(interval));
    }
}
