public static long readLong(byte[] source, int position) {
    return ((long) source[position] << 56) | ((long) (source[position + 1] & 255) << 48)
            | ((long) (source[position + 2] & 255) << 40) | ((long) (source[position + 3] & 255) << 32)
            | ((long) (source[position + 4] & 255) << 24) | ((source[position + 5] & 255) << 16)
            | ((source[position + 6] & 255) << 8) | ((source[position + 7] & 255));
}
