import java.util.*;
import java.util.function.*;

public class MyClass {

    public static <T, U, V> List<V> zip(List<T> a, List<U> b, BiFunction<T, U, V> zipFunction) {
        List<V> result = new ArrayList<>();
        Iterator<T> aIterator = a.iterator();
        Iterator<U> bIterator = b.iterator();
        while (aIterator.hasNext() && bIterator.hasNext()) {
            T aValue = aIterator.next();
            U bValue = bIterator.next();
            result.add(zipFunction.apply(aValue, bValue));
        }
        return result;
    }
}
