public LegendTitle createLegend(JFreeChart chart) {
    LegendTitle legendTitle = chart.getLegend();
    if (legendTitle == null) {
        return null;
    }
    StandardChartTheme theme = new StandardChartTheme("enhanced");
    theme.setExtraLargeFont(new java.awt.Font("Arial", java.awt.Font.BOLD, 16));
    theme.setLargeFont(new java.awt.Font("Arial", java.awt.Font.PLAIN, 14));
    theme.setRegularFont(new java.awt.Font("Arial", java.awt.Font.PLAIN, 12));
    chart.getTitle().setFont(new java.awt.Font("Arial", java.awt.Font.BOLD, 14));
    theme.setLegendBackgroundPaint(java.awt.Color.white);
    theme.setPlotBackgroundPaint(java.awt.Color.white);
    theme.setAxisOffset(new RectangleInsets(5.0, 5.0, 5.0, 5.0));
    theme.setAxisLabelPaint(java.awt.Color.darkGray);
    theme.setTickLabelPaint(java.awt.Color.black);
    theme.setBarPainter(new StandardBarPainter());
    theme.setErrorIndicatorPaint(java.awt.Color.black);

    legendTitle.setMargin(new RectangleInsets(2, 2, 2, 2));
    legendTitle.setFrame(BlockBorder.NONE);
    legendTitle.setPosition(RectangleEdge.TOP);
    legendTitle.setHorizontalAlignment(HorizontalAlignment.CENTER);
    legendTitle.setVerticalAlignment(VerticalAlignment.BOTTOM);
    legendTitle.setBackgroundPaint(java.awt.Color.white);
    legendTitle.setItemPaint(java.awt.Color.black);

    return legendTitle;
}
