public static double[] getTileBounds(int x, int y, int zoom) {
    double[] bounds = new double[4];

    double n = Math.PI - (2.0 * Math.PI * y) / Math.pow(2.0, zoom);
    bounds[0] = ((360.0 * x) / Math.pow(2.0, zoom)) - 180.0;
    bounds[1] = 180.0 / Math.PI * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));
    n = Math.PI - (2.0 * Math.PI * (y + 1)) / Math.pow(2.0, zoom);
    bounds[2] = ((360.0 * (x + 1)) / Math.pow(2.0, zoom)) - 180.0;
    bounds[3] = 180.0 / Math.PI * Math.atan(0.5 * (Math.exp(n) - Math.exp(-n)));

    return bounds;
}
