public void writeVariableByteInt(byte[] bytes, int value, int offset) {
    int index = offset;

    do {
        int b = value & 0x7f;
        value >>>= 7;

        if (value != 0) {
            b |= 0x80;
        }

        bytes[index++] = (byte) b;
    } while (value != 0);
}
