public static double[] fitPolynomial(double[] samplePoints, double[] observations, int degree) {
        // Create matrix of x values
        double[][] x = new double[samplePoints.length][degree + 1];
        for (int i = 0; i < samplePoints.length; i++) {
            for (int j = 0; j <= degree; j++) {
                x[i][j] = Math.pow(samplePoints[i], j);
            }
        }

        // Create matrix of y values
        double[] y = new double[observations.length];
        for (int i = 0; i < observations.length; i++) {
            y[i] = observations[i];
        }

        // Find transpose of x matrix
        double[][] xT = new double[degree + 1][samplePoints.length];
        for (int i = 0; i <= degree; i++) {
            for (int j = 0; j < samplePoints.length; j++) {
                xT[i][j] = x[j][i];
            }
        }

        // Multiply transpose of x matrix by x matrix
        double[][] temp = new double[degree + 1][degree + 1];
        for (int i = 0; i <= degree; i++) {
            for (int j = 0; j <= degree; j++) {
                double sum = 0;
                for (int k = 0; k < samplePoints.length; k++) {
                    sum += xT[i][k] * x[k][j];
                }
                temp[i][j] = sum;
            }
        }

        // Find inverse of temp matrix
        double[][] tempInv = new double[degree + 1][degree + 1];
        for (int i = 0; i <= degree; i++) {
            for (int j = 0; j <= degree; j++) {
                if (i == j) {
                    tempInv[i][j] = 1;
                } else {
                    tempInv[i][j] = 0;
                }
            }
        }

        for (int i = 0; i <= degree; i++) {
            double factor = temp[i][i];
            for (int j = 0; j <= degree; j++) {
                temp[i][j] /= factor;
                tempInv[i][j] /= factor;
            }
            for (int j = 0; j <= degree; j++) {
                if (i != j) {
                    double subFactor = temp[j][i];
                    for (int k = 0; k <= degree; k++) {
                        temp[j][k] -= subFactor * temp[i][k];
                        tempInv[j][k] -= subFactor * tempInv[i][k];
                    }
                }
            }
        }

        // Multiply tempInv by transpose of x matrix
        double[][] finalTemp = new double[degree + 1][observations.length];
        for (int j = 0; j <= degree; j++) {
            for (int k = 0; k < observations.length; k++) {
                double sum = 0;
                for (int i = 0; i <= degree; i++) {
                    sum += tempInv[j][i] * xT[i][k];
                }
                finalTemp[j][k] = sum;
            }
        }

        // Multiply finalTemp by y matrix to get coefficients
        double[] coefficients = new double[degree + 1];
        for (int i = 0; i <= degree; i++) {
            double sum = 0;
            for (int j = 0; j < observations.length; j++) {
                sum += finalTemp[i][j] * y[j];
            }
            coefficients[i] = sum;
        }

        return coefficients;
    }
