import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.ArrayList;
import java.util.List;

public class IPAddressResolver {

    /**
     * Resolves all IPv4 and IPv6 addresses for the hostname. A single IP address will be returned in the singleValue
     * field (IPv4 address will be returned if present). All IPv4 and IPv6 addresses will be included in the multiValue
     * field.
     *
     * @param key a hostname
     * @return a list of all resolved IP addresses
     */
    public static IPAddresses resolveIPAddresses(String key) throws UnknownHostException {
        IPAddresses addresses = new IPAddresses();
        InetAddress[] inetAddresses = InetAddress.getAllByName(key);
        List<String> ipv4Addresses = new ArrayList<>();
        List<String> ipv6Addresses = new ArrayList<>();
        for (InetAddress inetAddress : inetAddresses) {
            if (inetAddress instanceof java.net.Inet4Address) {
                ipv4Addresses.add(inetAddress.getHostAddress());
            } else if (inetAddress instanceof java.net.Inet6Address) {
                ipv6Addresses.add(inetAddress.getHostAddress());
            }
        }
        if (!ipv4Addresses.isEmpty()) {
            addresses.setSingleValue(ipv4Addresses.get(0));
        } else if (!ipv6Addresses.isEmpty()) {
            addresses.setSingleValue(ipv6Addresses.get(0));
        }
        addresses.setMultiValue(ipv4Addresses);
        addresses.getMultiValue().addAll(ipv6Addresses);
        return addresses;
    }

    public static class IPAddresses {
        private String singleValue;
        private List<String> multiValue = new ArrayList<>();

        public String getSingleValue() {
            return singleValue;
        }

        public void setSingleValue(String singleValue) {
            this.singleValue = singleValue;
        }

        public List<String> getMultiValue() {
            return multiValue;
        }

        public void setMultiValue(List<String> multiValue) {
            this.multiValue = multiValue;
        }
    }

}
