public void sendAuditEventMessage(AuditEventMessage msg) {
    String hostName = msg.getHostName();
    int port = msg.getPort();

    // Retrieve transport sender and queue
    TransportSender transportSender = msg.getTransportSender();
    AuditQueue auditQueue = msg.getAuditQueue();

    // Prepare message for delivery
    byte[] messageBytes = msg.getMessageBytes();
    String messagePayload = new String(messageBytes);

    // Send message to designated audit record repository
    try {
        Socket socket = new Socket(hostName, port);
        OutputStream outputStream = socket.getOutputStream();
        outputStream.write(messageBytes);

        // Send message to designated audit queue
        transportSender.send(messagePayload, auditQueue);

        socket.close();
    } catch (IOException e) {
        // Handle exception
    }

}
