/**
 * Pick a matrix element based on the specified window coordinates
 *
 * @param winX  the window x-coordinate
 * @param winY  the window y-coordinate
 * @param winZ  the window z-coordinate
 * @param viewport  the viewport of the window
 * @param dest  will receive the picked position
 * @return this
 */
@Override
public Matrix4dc pick(double winX, double winY, double winZ, double[] viewport, int[] dest) {
    double x = (2.0 * winX - viewport[0]) / viewport[2] - 1.0;
    double y = (2.0 * winY - viewport[1]) / viewport[3] - 1.0;
    double z = 2.0 * winZ - 1.0;
    Matrix4dc inverse = invertAffine(this);
    inverse.transformProject(x, y, z, dest);
    return this;
}
