private int computePk1Measure(double[] objectiveScores,
                                  double pk1Threshold) {
        LOGGER.fine("Computing the PK1 measure");

        double average = 0;
        for (int k = 0; k < objectiveScores.length; ++k)
            average += objectiveScores[k];
        average /= objectiveScores.length;

        double stdev = 0;
        for (int k = 0; k < objectiveScores.length; ++k)
            stdev += Math.pow(objectiveScores[k], 2);
        stdev /= objectiveScores.length;
        stdev = Math.sqrt(stdev);

        for (int k = 0; k < objectiveScores.length; ++k) {
            objectiveScores[k] = (objectiveScores[k] - average) / stdev;
            if (objectiveScores[k] > pk1Threshold)
                return k;
        }
        return 0;
    },0

public boolean checkCompatibility(Method method, Object item, String property) {
    //implementation of the function
    if(method.getParameterTypes().length != 1) {
        return false; //the method can only have one argument
    }

    Class<?> parameterType = method.getParameterTypes()[0];

    try {
        //check if the item has the same type as the parameter of the method
        return parameterType.isInstance(item) && item.getClass().getMethod(property) != null;
    } catch (NoSuchMethodException e) {
        return false;
    }
}
