public Enumeration findEnumeration(String name) {
    Enumeration enum = findEnumerationInGroup(name, this);
    if (enum != null) {
        return enum;
    }
    if (parentGroup != null) {
        return parentGroup.findEnumeration(name);
    }
    return null;
}

private Enumeration findEnumerationInGroup(String name, Group group) {
    Enumeration[] enums = group.getEnumerations();
    for (Enumeration e : enums) {
        if (e.getName().equals(name)) {
            return e;
        }
    }
    Group[] groups = group.getGroups();
    for (Group g : groups) {
        Enumeration e = findEnumerationInGroup(name, g);
        if (e != null) {
            return e;
        }
    }
    return null;
}
