public int incrementPositionWithoutChangingChannel(int ch, int align) throws IOException {
    int currentPosition = getCurrentPosition(); // fetch the current position
    int offset = (align - currentPosition % align) % align;

    // check if incrementing the position will result in changing the channel
    if (ch != getCurrentChannel()) {
        throw new IOException("Cannot change channel while incrementing position");
    }

    return currentPosition + offset;
}
