public CompilationStatistics processTemplates(CompilerOptions options) {
    CompilationStatistics stats = new CompilationStatistics();
    try {
        // compiling process
        compile(options);

        // building process
        build(options);

        // validation process
        validate(options);
    } catch (CompilationException e) {
        stats.addException(e);
    } catch (BuildingException e) {
        stats.addException(e);
    } catch (ValidationException e) {
        stats.addException(e);
    } finally {
        stats.setCompilationTime(calculateCompilationTime());
        stats.setMemoryUsage(calculateMemoryUsage());
    }
    return stats;
}
