public static <T1, T2, T3, T4> Serializer<Tuple4<T1, T2, T3, T4>> tuple4(Serializer<T1> first, Serializer<T2> second, Serializer<T3> third, Serializer<T4> fourth) {
    return new Serializer<Tuple4<T1, T2, T3, T4>>() {
        @Override
        public void write(Kryo kryo, Output output, Tuple4<T1, T2, T3, T4> object) {
            first.write(kryo, output, object.v1);
            second.write(kryo, output, object.v2);
            third.write(kryo, output, object.v3);
            fourth.write(kryo, output, object.v4);
        }

        @Override
        public Tuple4<T1, T2, T3, T4> read(Kryo kryo, Input input, Class<? extends Tuple4<T1, T2, T3, T4>> type) {
            T1 v1 = first.read(kryo, input, null);
            T2 v2 = second.read(kryo, input, null);
            T3 v3 = third.read(kryo, input, null);
            T4 v4 = fourth.read(kryo, input, null);
            return new Tuple4<>(v1, v2, v3, v4);
        }
    };
}
