			return false;
		if (!(o instanceof Interval))
			return false;
		Interval<T> query;
		query = (Interval<T>)o;
		TreeNode<T> node = root;
		while (node != null){
			if (query.contains(node.midpoint)){
				return node.increasing.contains(query);
			}
			if (query.isLeftOf(node.midpoint)){
				node = node.left;
			} else {
				node = node.right;
			}
		}
		return false;
