import javax.jdo.JDOHelper;
import javax.jdo.PersistenceManagerFactory;
import javax.jdo.metadata.ClassMetadata;
import javax.jdo.metadata.JDOMetadata;

public Class<?> getTopLevelClass(Class<?> clazz) throws ClassNotPersistenceCapableException {
    PersistenceManagerFactory pmf = JDOHelper.getPersistenceManagerFactory("persistence-unit");
    JDOMetadata jdoMetadata = pmf.getMetadata(JDOMetadata.class);
    ClassMetadata classMetadata = jdoMetadata.getMetadata(clazz.getName());
    if (classMetadata == null) {
        throw new ClassNotPersistenceCapableException(clazz.getName() + " is not persistence capable.");
    }
    ClassMetadata currentMetadata = classMetadata;
    while (currentMetadata.getSuperclass() != null) {
        currentMetadata = currentMetadata.getSuperclass();
    }
    return currentMetadata.getDescribedType();
}
