public static void writeErlangPid(String node, int id, int serial, int creation, OutputStream out) throws IOException {
    byte[] pid = new byte[9];
    pid[0] = (byte) 103;
    pid[1] = (byte) ((id >> 8) & 0xff);
    pid[2] = (byte) (id & 0xff);
    pid[3] = (byte) ((serial >> 8) & 0xff);
    pid[4] = (byte) (serial & 0xff);
    pid[5] = (byte) (creation & 0x03);
    byte[] nodeNameBytes = node.getBytes();
    pid[6] = (byte) nodeNameBytes[0];
    pid[7] = (byte) nodeNameBytes[1];
    pid[8] = (byte) nodeNameBytes[2];
    out.write(pid);
}
