public void prepareHttpRequest(HttpRequest request, String basicAuthUsername, String basicAuthPassword, Map<String, String> parameters) {
    if (request != null && basicAuthUsername != null && basicAuthPassword != null) {
        String auth = basicAuthUsername + ":" + basicAuthPassword;
        byte[] encodedAuth = Base64.encodeBase64(auth.getBytes(Charset.forName("US-ASCII")));
        String authHeader = "Basic " + new String(encodedAuth);
        request.setHeader(HttpHeaders.AUTHORIZATION, authHeader);
    }

    if (parameters != null && parameters.size() > 0) {
        List<NameValuePair> queryParams = parameters.entrySet()
                .stream()
                .map(e -> new BasicNameValuePair(e.getKey(), e.getValue()))
                .collect(Collectors.toList());
        String queryString = URLEncodedUtils.format(queryParams, StandardCharsets.UTF_8);
        request.setUri(request.getUri() + "?" + queryString);
    }
}
