@Component
public class ExceptionUtil {

    public ResponseEntity<Object> renderException(Exception ex, HttpStatus status) {

        // Add error messages and stack trace to the json model.
        StringBuilder errorMessage = new StringBuilder();
        errorMessage.append(ex.getMessage());
        for (StackTraceElement ste : ex.getStackTrace()) {
            errorMessage.append(", " + ste.toString());
        }

        // Set the response status accordingly.
        return new ResponseEntity<>(errorMessage.toString(), status);
    }
}
