        httpPost.addHeader("Authorization", "Bearer " + getToken(CorpNum).getAccess_token());
        httpPost.setHeader("Content-Type", "multipart/form-data");

        MultipartEntityBuilder builder = MultipartEntityBuilder.create();
        builder.setMode(HttpMultipartMode.BROWSER_COMPATIBLE);

        File file = new File(FilePath);
        builder.addBinaryBody("Filedata", file, ContentType.DEFAULT_BINARY, file.getName());
        HttpEntity entity = builder.build();

        httpPost.setEntity(entity);
        CloseableHttpClient httpclient = HttpClients.createDefault();

        CloseableHttpResponse response = null;
        try {
            response = httpclient.execute(httpPost);
            int statusCode = response.getStatusLine().getStatusCode();
            if(statusCode == 200) {
                String responseString = EntityUtils.toString(response.getEntity(), "UTF-8");
                Response result = gson.fromJson(responseString, Response.class);
                return result;
            } else {
                ErrorResponse errorResponse = getErrorContent(response.getEntity().getContent());
                throw new PopbillException(errorResponse);
            }
        } catch (IOException e) {
            throw new PopbillException(e.getMessage());
        } finally {
            closeResponse(response);
            closeClient(httpclient);
        }
    } else {
        throw new PopbillException(-99999999, "0보다 큰 값을 입력하세요.");
    }
