    // If displayToggleTimeMenuButton is true, set the time picker's toggle button to visible
    // Otherwise, set it to invisible
    if (displayToggleTimeMenuButton) {
        try {
            Field field = timePicker.getClass().getDeclaredField("mDelegate");
            field.setAccessible(true);
            Class<?> delegateClass = Class.forName("android.widget.TimePickerClockDelegate");
            Object delegate = field.get(timePicker);
            Class<?> spinnerDelegateClass = Class.forName("android.widget.TimePickerSpinnerDelegate");
            if (delegateClass.isInstance(delegate) && spinnerDelegateClass.isInstance(delegate)) {
                Method method = delegateClass.getDeclaredMethod("setToggleVisibility", boolean.class);
                method.setAccessible(true);
                method.invoke(delegate, true);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    } else {
        try {
            Field field = timePicker.getClass().getDeclaredField("mDelegate");
            field.setAccessible(true);
            Class<?> delegateClass = Class.forName("android.widget.TimePickerClockDelegate");
            Object delegate = field.get(timePicker);
            Class<?> spinnerDelegateClass = Class.forName("android.widget.TimePickerSpinnerDelegate");
            if (delegateClass.isInstance(delegate) && spinnerDelegateClass.isInstance(delegate)) {
                Method method = delegateClass.getDeclaredMethod("setToggleVisibility", boolean.class);
                method.setAccessible(true);
                method.invoke(delegate, false);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
