public static Document cloneSVGDocument(Document doc) {
    try {
        DOMImplementation domImpl = doc.getImplementation();
        String svgNamespaceURI = SVGDOMImplementation.SVG_NAMESPACE_URI;
        Document clonedDoc = (Document) domImpl.createDocument(svgNamespaceURI, "svg", null);
        Element clonedRoot = clonedDoc.getDocumentElement();
        // Clone the element tree in the source document into the target document
        Node sourceRoot = doc.getDocumentElement();
        cloneElement(sourceRoot, clonedDoc, clonedRoot);
        return clonedDoc;
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}

private static void cloneElement(Node source, Document targetDoc, Element target) {
    // Create a new element in the target document
    Element newElement = targetDoc.createElementNS(source.getNamespaceURI(), source.getNodeName());
    // Copy all attributes from the source element to the new element
    NamedNodeMap sourceAttrs = source.getAttributes();
    for (int i = 0; i < sourceAttrs.getLength(); i++) {
        Attr attr = (Attr) sourceAttrs.item(i);
        newElement.setAttributeNS(attr.getNamespaceURI(), attr.getNodeName(), attr.getValue());
    }
    // Attach the new element to the target document
    target.appendChild(newElement);
    // Recursively clone all children of the source element
    NodeList sourceChildren = source.getChildNodes();
    for (int i = 0; i < sourceChildren.getLength(); i++) {
        Node sourceChild = sourceChildren.item(i);
        if (sourceChild.getNodeType() == Node.ELEMENT_NODE) {
            cloneElement(sourceChild, targetDoc, newElement);
        } else if (sourceChild.getNodeType() == Node.TEXT_NODE) {
            // Copy the text content of the source element to the new element
            Text textNode = targetDoc.createTextNode(sourceChild.getTextContent());
            newElement.appendChild(textNode);
        }
    }
}
