public Driver getEnvironmentDriver(SystemImageType systemImageType) throws ExecutorException {
    // retrieve all available drivers for the given systemImageType
    List<Driver> drivers = DriverRegistry.getDrivers(systemImageType);

    // filter the drivers to keep those that can manage the requested environment
    List<Driver> suitableDrivers = drivers.stream()
            .filter(driver -> driver.canManage(environment))
            .collect(Collectors.toList());

    // if no suitable driver was found, throw an ExecutorException
    if (suitableDrivers.isEmpty()) {
        throw new ExecutorException("No suitable driver for selected environment was found");
    }

    // return the first (and hopefully only) suitable driver
    return suitableDrivers.get(0);
}
