public Map<String, String> extractEventMetadata(GobblinTrackingEvent event) throws IOException {
    Map<String, String> eventMetadata = new HashMap<>();

    // Extract event type and add to metadata
    eventMetadata.put("event.type", event.getName());

    // Extract event metadata and add to metadata
    for (Map.Entry<String, Object> entry : event.getMetadata().entrySet()) {
        String key = entry.getKey();
        Object value = entry.getValue();
        if (value instanceof String || value instanceof Number || value instanceof Boolean || value instanceof Date) {
            eventMetadata.put(key, value.toString());
        }
    }

    // Extract event timestamp and add to metadata
