public boolean isInstanceVariableAccess(String node, String prototypeDeclaration) {
    String[] prototypeParts = prototypeDeclaration.split("\\.");
    String prototypeName = prototypeParts[prototypeParts.length-2]; //Get the object prototype name

    String[] nodeParts = node.split("\\.");
    String objectName = "";
    boolean isThisAccess = false;
    for(int i = 0; i < nodeParts.length; i++) {
        String part = nodeParts[i];
        if(part.equals("this")) { //Check for access via 'this'
            isThisAccess = true;
            objectName = prototypeName;
            break;
        }
        if(part.equals(prototypeName)) { //Check for direct object reference
            objectName = prototypeName;
            break;
        }
        if(part.equals("prototype")) { //Skip prototype keyword
            continue;
        }
        if(i == nodeParts.length-1) { //Check for access via object property
            objectName = prototypeName;
        }
    }

    if(objectName.equals("")) { //Object not found
        return false;
    }

    //Check if instance variable access is performed on the correct object
    if(node.contains("." + objectName + ".")) {
        return true;
    }

    //Check if 'this' keyword is used for access
    if(isThisAccess && !node.contains(".")) {
        return true;
    }

    return false;
}
