public boolean isTransformableToH2OType(Schema s) {
    if (s.getType() == Schema.Type.BOOLEAN ||
            s.getType() == Schema.Type.INT ||
            s.getType() == Schema.Type.LONG ||
            s.getType() == Schema.Type.FLOAT ||
            s.getType() == Schema.Type.DOUBLE ||
            s.getType() == Schema.Type.STRING ||
            s.getType() == Schema.Type.ENUM) {
        return true;
    } else if (s.getType() == Schema.Type.ARRAY) {
        return isTransformableToH2OType(s.getElementType());
    } else if (s.getType() == Schema.Type.MAP) {
        return isTransformableToH2OType(s.getValueType());
    } else if (s.getType() == Schema.Type.RECORD) {
        List<Schema.Field> fields = s.getFields();
        for (Schema.Field field : fields) {
            if (!isTransformableToH2OType(field.schema())) {
                return false;
            }
        }
        return true;
    }
    return false;
}
