public static void setPropertiesOnBean(Object bean, String[][] properties) {
    try {
        BeanInfo beanInfo = Introspector.getBeanInfo(bean.getClass());
        PropertyDescriptor[] propertyDescriptors = beanInfo.getPropertyDescriptors();

        for (String[] row : properties) {
            String propertyName = row[0];
            String propertyValue = row[1];

            for (PropertyDescriptor propertyDescriptor : propertyDescriptors) {
                if (propertyDescriptor.getName().equals(propertyName)) {
                    Method setter = propertyDescriptor.getWriteMethod();
                    if (setter != null) {
                        Class<?>[] parameterTypes = setter.getParameterTypes();
                        if (parameterTypes.length == 1) {
                            Object value = convertValue(parameterTypes[0], propertyValue);
                            setter.invoke(bean, value);
                        }
                    }
                    break;
                }
            }
        }
    } catch (IntrospectionException | InvocationTargetException | IllegalAccessException e) {
        e.printStackTrace();
    }
}

private static Object convertValue(Class<?> targetType, String stringValue) {
    Object value = null;
    if (targetType.equals(String.class)) {
        value = stringValue;
    } else if (targetType.equals(boolean.class) || targetType.equals(Boolean.class)) {
        value = Boolean.valueOf(stringValue);
    } else if (targetType.equals(int.class) || targetType.equals(Integer.class)) {
        value = Integer.valueOf(stringValue);
    } else if (targetType.equals(long.class) || targetType.equals(Long.class)) {
        value = Long.valueOf(stringValue);
    } else if (targetType.equals(float.class) || targetType.equals(Float.class)) {
        value = Float.valueOf(stringValue);
    } else if (targetType.equals(double.class) || targetType.equals(Double.class)) {
        value = Double.valueOf(stringValue);
    }
    return value;
}
