public static double round(double value, int accuracy) {
    if (accuracy < 0) {
        double scale = Math.pow(10, -accuracy);
        return Math.round(value / scale) * scale;
    } else {
        double scale = Math.pow(10, accuracy);
        return Math.round(value * scale) / scale;
    }
}
