public Map<Integer, List<Object>> assignObjectsToClusters(List<Object> m_current, Map<Integer, Set<Integer>> dimensions, List<Object> database) {
   Map<Integer, List<Object>> clusterAssignments = new HashMap<Integer, List<Object>>();
   for (Object object : database) {
      double minDistance = Double.MAX_VALUE;
      int assignedCluster = -1;
      for (int clusterIndex = 0; clusterIndex < m_current.size(); clusterIndex++) {
         Set<Integer> correlatedDimensions = dimensions.get(clusterIndex);
         double distance = calculateDistance(object, m_current.get(clusterIndex), correlatedDimensions);
         if (distance < minDistance) {
            minDistance = distance;
            assignedCluster = clusterIndex;
         }
      }
      if (!clusterAssignments.containsKey(assignedCluster)) {
         clusterAssignments.put(assignedCluster, new ArrayList<Object>());
      }
      clusterAssignments.get(assignedCluster).add(object);
   } 
   return clusterAssignments;
}

private double calculateDistance(Object object, Object center, Set<Integer> correlatedDimensions) {
   double distance = 0;
   for (int dimIndex : correlatedDimensions) {
      double dimDistance = calculateDimensionDistance(object.getDimension(dimIndex), center.getDimension(dimIndex));
      distance += dimDistance;
   }
   return distance;
}

private double calculateDimensionDistance(double dim1, double dim2) {
   return Math.abs(dim1 - dim2);
}
