public static byte[] decrementPrimary(byte[] primary) {
    // Make sure the input is the correct size
    if (primary.length != 3) {
        throw new IllegalArgumentException("Input must be a 3-byte array");
    }

    // Decrement the primary
    if (primary[2] > 0) {
        primary[2]--;
    } else if (primary[1] > 0) {
        primary[1]--;
        primary[2] = (byte) 0x7f;
    } else if (primary[0] > 0) {
        primary[0]--;
        primary[1] = (byte) 0xff;
        primary[2] = (byte) 0x7f;
    } else {
        throw new IllegalStateException("Cannot decrement further, primary is zero");
    }

    return primary;
}
