import org.apache.commons.math3.distribution.BinomialDistribution;

public double[] binomialConfidenceInterval(int trials, int successes, double confidenceLevel) {
    BinomialDistribution binomial = new BinomialDistribution(trials, (double) successes / trials);
    double alpha = (1 - confidenceLevel) / 2;
    double lowerBound = binomial.inverseCumulativeProbability(alpha);
    double upperBound = binomial.inverseCumulativeProbability(1 - alpha);
    return new double[] {lowerBound, upperBound};
}
