public byte[] decryptBlocks(byte[] encryptedData, Cipher cipher) throws Exception {
    int blockSize = cipher.getBlockSize();
    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    for (int i = 0; i < encryptedData.length; i += blockSize) {
        byte[] encryptedBlock = Arrays.copyOfRange(encryptedData, i, i + blockSize);
        byte[] decryptedBlock = cipher.update(encryptedBlock);
        outputStream.write(decryptedBlock);
    }
    byte[] finalBlock = cipher.doFinal();
    outputStream.write(finalBlock);
    return outputStream.toByteArray();
}
