public String prefixAliasWithProductExtension(String alias, String bundleLocation) {
    if(bundleLocation == null) {
        return alias;
    }
    String extensionName = null;
    String[] entries = bundleLocation.split("/");
    String lastEntry = entries[entries.length - 1];

    if(lastEntry.endsWith(".jar")) {
        int index = lastEntry.lastIndexOf(".");
        extensionName = lastEntry.substring(0, index);
    } else {
        extensionName = lastEntry;
    }

    return extensionName + "_" + alias;
}
