import java.io.FileInputStream;
import java.security.KeyStore;
import java.security.PrivateKey;
import java.security.cert.Certificate;
import java.security.cert.CertificateFactory;

public KeyStore loadToKeystore(String certResourceLocation, String privateKeyResourceLocation, String alias, String keyPassword) throws Exception {

    CertificateFactory cf = CertificateFactory.getInstance("X.509");

    // Load certificate from resource location
    FileInputStream certInputStream = new FileInputStream(certResourceLocation);
    Certificate certificate = cf.generateCertificate(certInputStream);

    // Load private key from resource location
    FileInputStream keyInputStream = new FileInputStream(privateKeyResourceLocation);
    byte[] keyBytes = new byte[keyInputStream.available()];
    keyInputStream.read(keyBytes);
    keyInputStream.close();

    // Load private key to keystore
    KeyStore keystore = KeyStore.getInstance(KeyStore.getDefaultType());
    keystore.load(null, keyPassword.toCharArray());
    keystore.setKeyEntry(alias, (PrivateKey) key, keyPassword.toCharArray(), new Certificate[] { certificate });

    return keystore;
}
