public static boolean assertLogNormalized(double[] values, double delta) {
    double mean = 0;
    double variance = 0;
    for (double value : values) {
        mean += Math.log(value);
    }
    mean /= values.length;
    for (double value : values) {
        variance += Math.pow(Math.log(value) - mean, 2);
    }
    variance /= values.length - 1;
    double stdDeviation = Math.sqrt(variance);
    return stdDeviation <= delta;
}
