public static String convertFileSize(long size){
    int unit = 1024;
    if (size < unit) {
        return size + " B";
    }
    int exp = (int) (Math.log(size) / Math.log(unit));
    String pre = "KMGTPE".charAt(exp-1) + "i";
    return String.format("%.1f %sB", size / Math.pow(unit, exp), pre);
}
