public String addPolygonSymbolizer(String styleJson) {
    // Parse the old style JSON
    JSONParser parser = new JSONParser();
    JSONObject json = null;
    try {
        json = (JSONObject) parser.parse(styleJson);
    } catch (ParseException e) {
        e.printStackTrace();
        return null; // Return null if parsing fails
    }

    // Check if the "rules" array exists
    JSONArray rules = (JSONArray) json.get("rules");
    if (rules == null) {
        rules = new JSONArray();
        json.put("rules", rules);
    }

    // Create a new rule with a polygon symbolizer
    JSONObject rule = new JSONObject();
    rules.add(rule);
    JSONArray symbolizers = new JSONArray();
    JSONObject symbolizer = new JSONObject();
    symbolizer.put("type", "polygon");
    symbolizers.add(symbolizer);
    rule.put("symbolizers", symbolizers);

    // Return the updated JSON as a string
    return json.toJSONString();
}
