public byte[] encodeInt(int value, int numBytes) {
    byte[] bytes = new byte[numBytes];
    for (int i = numBytes - 1; i >= 0; i--) {
        bytes[i] = (byte)(value & 0xff);
        value >>= 8;
    }
    return bytes;
}
