import java.net.InetAddress;

public static String getIPAddressString(InetAddress ipAddress) throws IOException {
   if (ipAddress == null) {
       throw new IllegalArgumentException("IPAddress cannot be null.");
   }

   try {
      byte[] address = ipAddress.getAddress();
      StringBuilder str = new StringBuilder();

      if (address.length == 4) {
         // IPv4 address
         for (int i = 0; i < address.length; i++) {
            str.append(Integer.toString((address[i] & 0xff), 10));
            if (i < address.length - 1) {
               str.append(".");
            }
         }
      } else if (address.length == 16) {
         // IPv6 address
         for (int i = 0; i < address.length; i += 2) {
            int value = (int) ((address[i] << 8) | (address[i + 1] & 0xff));
            str.append(Integer.toHexString(value));
            if (i < address.length - 2) {
               str.append(":");
            }
         }
         str.insert(0, "[");
         str.append("]");
      } else {
         throw new IllegalArgumentException("IPAddress format is unsupported.");
      }
      return str.toString();
   } catch (Exception e) {
      throw new IOException("Unable to convert IPAddress to String", e);
   }
}
