public String getAddedFileName(int index) {
    List<String> addedFiles = new ArrayList<>();
    try {
        Process p = Runtime.getRuntime().exec("git diff --name-only --cached");
        BufferedReader reader = new BufferedReader(new InputStreamReader(p.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            addedFiles.add(line);
        }
    } catch (IOException e) {
        e.printStackTrace();
    }

    if (index >= addedFiles.size() || index < 0) {
        throw new IndexOutOfBoundsException("Index out of bounds for the list of new files to commit.");
    }
    return addedFiles.get(index);
}
