import java.util.Date;
import java.util.TimeZone;
import java.text.SimpleDateFormat;

public static DateTime convertToObject(Object o, TimeZone timezone) throws PageException {
    try {
        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
        if (timezone != null) {
            dateFormat.setTimeZone(timezone);
        } else {
            dateFormat.setTimeZone(TimeZone.getTimeZone("UTC"));
        }
        Date date = dateFormat.parse(o.toString());
        return new DateTime(date.getTime(), DateTimeZone.forTimeZone(dateFormat.getTimeZone()));
    } catch (Exception e) {
        throw new PageException("Error converting to DateTime Object", e);
    }
}
