public boolean checkCollatingSequence(Node node) {
    List<String> keys = new ArrayList<>(node.getKeys());
    Collections.sort(keys); // sort the keys in ascending order
    for (int i = 1; i < keys.size(); i++) {
        if (keys.get(i - 1).compareTo(keys.get(i)) > 0) {
            return false; // keys are not in correct collating sequence
        }
    }
    return true; // all keys are in correct collating sequence
}
