import java.io.FileDescriptor;
import java.nio.ByteBuffer;

public class PreadFunction {

  public static int pread(FileDescriptor fd, long position, ByteBuffer buffer, int count) {
    int nread;
    ByteBuffer tempBuffer = ByteBuffer.allocateDirect(count);

    try {
      nread = fd.read(tempBuffer, position);
      if (nread > 0) {
        buffer.put(tempBuffer.array(), 0, nread);
      }
    } catch (Exception e) {
      nread = -1;
    }

    return nread;
  }

}
