import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class LoggingFunction {
  private static final Logger logger = LoggerFactory.getLogger(LoggingFunction.class);

  public static void expensiveLogging(LogLevel level, String message, Exception e) {
    if (logger.isTraceEnabled()) {
      switch (level) {
        case TRACE:
          logger.trace(message, e);
          break;
        case DEBUG:
          logger.debug(message, e);
          break;
        case INFO:
          logger.info(message, e);
          break;
        case WARN:
          logger.warn(message, e);
          break;
        case ERROR:
          logger.error(message, e);
          break;
        default:
          throw new IllegalArgumentException("Unknown logging level: " + level);
      }
    }
  }
}

public enum LogLevel {
  TRACE, DEBUG, INFO, WARN, ERROR
}
