public int computeLevenshteinDistance(LinkedList<Diff> diffs) {
    int[][] distance = new int[diffs.size() + 1][diffs.size() + 1];
    for (int i = 0; i <= diffs.size(); i++) {
        distance[i][0] = i;
    }
    for (int j = 1; j <= diffs.size(); j++) {
        distance[0][j] = j;
    }
    for (int i = 1; i <= diffs.size(); i++) {
        for (int j = 1; j <= diffs.size(); j++) {
            if (diffs.get(i - 1).equals(diffs.get(j - 1))) {
                distance[i][j] = distance[i - 1][j - 1];
            } else {
                distance[i][j] = Math.min(Math.min(
                        distance[i - 1][j] + 1,
                        distance[i][j - 1] + 1),
                        distance[i - 1][j - 1] + 1);
            }
        }
    }
    return distance[diffs.size()][diffs.size()];
}
