import java.util.HashSet;
import java.util.Set;

public Set<IReaction> extractTopReactions(IReactionScheme reactionScheme) {
    Set<IReaction> topReactions = new HashSet<>();
    for (IReaction reaction : reactionScheme.reactions()) {
        if (reactionScheme.reactantsOf(reaction).stream().anyMatch(reactant -> reactionScheme.productsWithReactant(reactant).size() > 1)) {
            topReactions.add(reaction);
        }
    }
    return topReactions;
}
