public List<Document> searchDocuments(String fieldName, List<String> searchTerms, String operator) {
    List<Document> matchingDocuments = new ArrayList<>();
    for (Document doc : allDocuments) {
        boolean isMatch = false;
        for (String term : searchTerms) {
            if (operator.equals("AND") && doc.getField(fieldName).contains(term)) {
                isMatch = true;
            } else if (operator.equals("OR") && doc.getField(fieldName).contains(term)) {
                isMatch = true;
                break;
            }
        }
        if (isMatch) {
            matchingDocuments.add(doc);
        }
    }
    return matchingDocuments;
}
