import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.apache.avro.Schema;
import org.apache.avro.io.Decoder;
import org.apache.avro.io.DecoderFactory;
import org.apache.avro.specific.SpecificDatumReader;

import java.io.IOException;

public class RecordConverter {

    public static JsonObject convertRecordToJsonObject(String inputSchema, String record) throws IOException {
        Schema.Parser parser = new Schema.Parser();
        Schema schema = parser.parse(inputSchema);

        SpecificDatumReader<Object> reader = new SpecificDatumReader<>(schema);
        Decoder decoder = DecoderFactory.get().jsonDecoder(schema, record);

        Object datum = reader.read(null, decoder);

        Gson gson = new Gson();
        JsonParser jsonParser = new JsonParser();
        return jsonParser.parse(gson.toJson(datum)).getAsJsonObject();
    }
}
