public void aggregateEsaJavaVersionRequirements(File esa, Resource resource) throws RepositoryException, IOException {
    JarFile jar = new JarFile(esa);
    Enumeration<JarEntry> entries = jar.entries();
    String aggregateJavaVersion = null;
    while (entries.hasMoreElements()) {
        JarEntry entry = entries.nextElement();
        if (entry.getName().endsWith(".MF")) {
            Manifest manifest = new Manifest(jar.getInputStream(entry));
            String javaVersion = manifest.getMainAttributes().getValue("Bundle-RequiredExecutionEnvironment");
            if (javaVersion != null) {
                if (aggregateJavaVersion == null) {
                    aggregateJavaVersion = javaVersion;
                } else {
                    if (!aggregateJavaVersion.equals(javaVersion)) {
                        throw new RepositoryException("Conflicting Java version requirements.");
                    }
                }
            }
        }
    }
    if (aggregateJavaVersion != null) {
        resource.setProperty("Java-Version", aggregateJavaVersion);
    }
}
