public void handleException(Exception exception) throws Exception {
    // Check if exception is retry-able
    boolean retryable = isRetryable(exception);

    // Check the retry policy and decide whether to retry or not
    boolean retry = retryPolicy.retry();

    if (retryable && retry) {
        // If exception is retry-able and retry is allowed, log and retry
        log.error("Exception caught: " + exception.getMessage() + ". Retrying...");
        retry();
    } else {
        // If exception is not retry-able or retry is not allowed, throw exception
        throw exception;
    }
}

