public void fillMarkersField() {
    // Get the current line number in the text editor's ruler margin
    int lineNumber = textEditor.getRulerMargin().getCurrentLineNumber();

    // Get all FindBugs markers associated with the current line
    IMarker[] markers;
    try {
        markers = ResourcesPlugin.getWorkspace().getRoot().findMarkers("edu.umd.cs.findbugs.marker", true, IResource.DEPTH_INFINITE);
    } catch (CoreException e) {
        e.printStackTrace();
        return;
    }
    List<IMarker> markersList = new ArrayList<>();
    for (IMarker marker : markers) {
        if (marker.getAttribute(IMarker.LINE_NUMBER, -1) == lineNumber) {
            markersList.add(marker);
        }
    }
    IMarker[] markersArray = markersList.toArray(new IMarker[markersList.size()]);

    // Set the markers field
    markersField.setMarkers(markersArray);
}
