public String parseClef(String input) {
    String clefNote = "";
    String clefName = "";
    int clefLine = -1;
    int clefOctave = -1;
    String clefMiddle = "";

    Pattern pattern = Pattern.compile("clef=((?<clefNote>[A-G][b#]?)|(?<clefName>[a-z]+))?(\\s+(?<clefLine>\\d+))?(\\s+(?<clefOctave>[+-]\\d+))?(\\s+(?<clefMiddle>[a-g]))?");
    Matcher matcher = pattern.matcher(input);

    if (matcher.find()) {
        clefNote = matcher.group("clefNote");
        clefName = matcher.group("clefName");
        clefLine = Integer.parseInt(matcher.group("clefLine"));
        clefOctave = Integer.parseInt(matcher.group("clefOctave"));
        clefMiddle = matcher.group("clefMiddle");
    }

    // do something with the extracted values
    return clefNote + "," + clefName + "," + clefLine + "," + clefOctave + "," + clefMiddle;
}
