public String sendMessageAndGetReply(Node nodeMessage, String strDest) {
    String replyMessage = null;
    try {
        URL urlDest = new URL(strDest);
        HttpURLConnection connection = (HttpURLConnection) urlDest.openConnection();
        connection.setRequestMethod("POST");
        connection.setRequestProperty("Content-Type", "application/xml");
        connection.setDoOutput(true);
        OutputStream outStream = connection.getOutputStream();
        TransformerFactory tf = TransformerFactory.newInstance();
        Transformer transformer = tf.newTransformer();
        transformer.transform(new DOMSource(nodeMessage), new StreamResult(outStream));
        outStream.flush();
        outStream.close();
        int responseCode = connection.getResponseCode();
        if (responseCode == HttpURLConnection.HTTP_OK) {
            InputStream inStream = connection.getInputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(inStream));
            StringBuilder response = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                response.append(line);
            }
            reader.close();
            replyMessage = response.toString();
        }
        connection.disconnect();
    } catch (Exception e) {
        e.printStackTrace();
    }
    return replyMessage;
}
