public static BinaryFast thinOnce(BinaryFast b, int[] kernel) {
    int width = b.getWidth();
    int height = b.getHeight();
    BinaryFast thinned = b.clone();
    boolean hasChanged = false;
    for(int y = 1; y < height - 1; y++) {
        for(int x = 1; x < width - 1; x++) {
            int pixelIndex = y * width + x;
            if(thinned.get(pixelIndex)) {
                int surroundingPixels = 0;
                for(int i = 0; i < kernel.length; i++) {
                    if(thinned.get(pixelIndex + kernel[i])) {
                        surroundingPixels++;
                    }
                }
                if(surroundingPixels >= 2 && surroundingPixels <= 6) {
                    int transitions = 0;
                    for(int i = 0; i < kernel.length - 1; i++) {
                        if(!thinned.get(pixelIndex + kernel[i]) && thinned.get(pixelIndex + kernel[i + 1])) {
                            transitions++;
                        }
                    }
                    if(!thinned.get(pixelIndex + kernel[kernel.length - 1]) && thinned.get(pixelIndex + kernel[0])) {
                        transitions++;
                    }
                    if(transitions == 1) {
                        thinned.clear(pixelIndex);
                        hasChanged = true;
                    }
                }
            }
        }
    }
    return hasChanged ? thinned : b;
}
