import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;

public static Method[] getAllPublicMethods(Class<?> beanClass) {
    List<Method> methodsList = new ArrayList<>();
    // add all public methods of beanClass
    Method[] declaredMethods = beanClass.getDeclaredMethods();
    for (Method declaredMethod : declaredMethods) {
        if (declaredMethod.getModifiers() == Modifier.PUBLIC) {
            methodsList.add(declaredMethod);
        }
    }

    // add all public methods of its super classes recursively
    Class<?> superClass = beanClass.getSuperclass();
    while (superClass != null) {
        Method[] superDeclaredMethods = superClass.getDeclaredMethods();
        for (Method declaredMethod : superDeclaredMethods) {
            if (declaredMethod.getModifiers() == Modifier.PUBLIC) {
                methodsList.add(declaredMethod);
            }
        }
        superClass = superClass.getSuperclass();
    }

    return methodsList.toArray(new Method[methodsList.size()]);
}
