import java.time.*;

public class CustomDateTime {

    public static void main(String[] args) {
        String input = "2021-05-19T12:34:00Z";
        Object output = getDateTime(input);
        System.out.println(output);

        input = "-01:00";
        output = getDateTime(input);
        System.out.println(output);
    }

    public static Object getDateTime(String input) {
        if (input.startsWith("+") || input.startsWith("-")) {
            // return offset if input starts with + or -
            return ZoneOffset.of(input);
        } else {
            // return instant if the input is in ISO-8601 format
            return Instant.parse(input);
        }
    }
}
