public boolean checkInterface(String host, int port, String transport) {
    //Implementation
    try {
        InetAddress address = InetAddress.getByName(host);
        NetworkInterface networkInterface = NetworkInterface.getByInetAddress(address);
        if (networkInterface != null && networkInterface.supportsMulticast()) {
            for (InterfaceAddress interfaceAddress : networkInterface.getInterfaceAddresses()) {
                InetSocketAddress socketAddress = new InetSocketAddress(interfaceAddress.getAddress(), port);
                if (socketAddress.getAddress().equals(address)
                        && (transport.equalsIgnoreCase("UDP") || transport.equalsIgnoreCase("TCP"))) {
                    return true;
                }
            }
        }
    } catch (Exception e) {
        // log exception
    }
    return false;
}
