public static <A> Lens<HMap, Maybe<A>> lensAt(TypeSafeKey.Simple<A> key) {
    return new Lens<HMap, Maybe<A>>() {
        @SuppressWarnings("unchecked")
        @Override public Maybe<A> get(HMap s) {
            return s.get(key).map(a -> (A) a);
        }

        @Override public HMap set(Maybe<A> a, HMap s) {
            return a.mapValue(key, s::put).orElse(s.remove(key));
        }

        @Override public Maybe<Maybe<A>> getMaybe(HMap s) {
            return Maybe.just(get(s));
        }
    };
}
