public List<Node> sortNodes(Set<Node> nodes) {
    List<Node> sortedNodes = new ArrayList<>();
    List<Node> roots = new ArrayList<>();

    for (Node node : nodes) {
        if (node.getDependencies().isEmpty()) {
            roots.add(node);
        }
    }

    while (!roots.isEmpty()) {
        Node root = roots.remove(0);
        sortedNodes.add(root);

        for (Node node : nodes) {
            node.removeDependency(root);
            if (node.getDependencies().isEmpty()) {
                roots.add(node);
            }
        }
    }

    return sortedNodes;
}
