public boolean isSessionIdle(int sec) {
    long currTime = System.currentTimeMillis();
    long lastAccessTime = ((HttpServletRequest)request).getSession().getLastAccessedTime();
    int idleTime = (int)((currTime - lastAccessTime) / 1000);

    if(idleTime > sec) {
        return true;
    } else {
        return false;
    }
}
