public boolean isDpiValueSet(String geoserverUrl, String layerName) throws Exception {
    String requestUrl = geoserverUrl + "/rest/layers/" + layerName + ".xml";
    DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
    DocumentBuilder builder = factory.newDocumentBuilder();
    Document document = builder.parse(new URL(requestUrl).openStream());
    NodeList dpiElements = document.getElementsByTagName("sld:PolygonSymbolizer");
    if (dpiElements.getLength() > 0) {
        Node dpiElement = dpiElements.item(0).getAttributes().getNamedItem("dpi");
        if (dpiElement != null && !dpiElement.getNodeValue().isEmpty()) {
            return true;
        }
    }
    return false;
}
