public void setTimeRange(String rangeStartingTimeString, String rangeEndingTimeString) {
    SimpleDateFormat dateFormat = new SimpleDateFormat("HH:mm:ss");
    try {
        Date rangeStartingTime = dateFormat.parse(rangeStartingTimeString);
        Date rangeEndingTime = dateFormat.parse(rangeEndingTimeString);

        Calendar calendar = new GregorianCalendar();
        calendar.setTime(rangeStartingTime);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        Date rangeStartingDate = calendar.getTime();

        calendar.setTime(rangeEndingTime);
        calendar.add(Calendar.DATE, 1);
        calendar.set(Calendar.HOUR_OF_DAY, 0);
        calendar.set(Calendar.MINUTE, 0);
        calendar.set(Calendar.SECOND, 0);
        Date rangeEndingDate = calendar.getTime();

        DailyCalendar dailyCalendar = new DailyCalendar(rangeStartingDate, rangeEndingDate);
        setExcludedDay(dailyCalendar);

    } catch (ParseException e) {
        e.printStackTrace();
    }
}
