public static Set<Character> getRemovableSymbols(Map<Character, Set<String>> productions) {
    Set<Character> removableSymbols = new HashSet<>();

    // Find all symbols that can derive the empty word
    for (Map.Entry<Character, Set<String>> entry : productions.entrySet()) {
        boolean producesEmpty = false;

        for (String production : entry.getValue()) {
            if (production.equals("ε")) { // Case where production is the empty word
                producesEmpty = true;
                break;
            }

            boolean allSymbolsProduceEmpty = true;
            for (int i = 0; i < production.length(); i++) {
                char symbol = production.charAt(i);

                // Check if the symbol can derive the empty word
                if (!removableSymbols.contains(symbol)) {
                    allSymbolsProduceEmpty = false;
                    break;
                }
            }

            if (allSymbolsProduceEmpty) {
                producesEmpty = true;
                break;
            }
        }

        if (producesEmpty) {
            removableSymbols.add(entry.getKey());
        }
    }

    return removableSymbols;
}
