public String parseExpressionToken(String expressionToken, String delimiters, Set<String> validValues, String visibilityLevel, String display) {
    String[] tokens = expressionToken.split(delimiters);
    StringBuilder parsedToken = new StringBuilder();
    for (String token : tokens) {
        if (validValues.contains(token)) {
            parsedToken.append(token).append(" ");
        }
    }
    if (parsedToken.length() > 0) {
        parsedToken.deleteCharAt(parsedToken.length() - 1);
        parsedToken.insert(0, visibilityLevel + " ").append(" " + display);
        return parsedToken.toString();
    } else {
        return "";
    }
}
