public ArrayList<Shape> makeShapeList(ArrayList<Feature> featureList, Projection displayProjection) {
    ArrayList<Shape> shapeList = new ArrayList<Shape>(); // create a new ArrayList to store the Shapes

    for (Feature feature : featureList) { // iterate through the featureList
        Geometry geom = feature.getGeometry(); // get the geometry from the feature

        // check if the geometry is null or empty
        if (geom == null || geom.isEmpty()) {
            continue; // skip to the next iteration
        }

        // transform the geometry to the display projection
        Geometry transformedGeom = geom.transform(displayProjection);

        // create a shape from the transformed geometry
        Shape shape = new Shape(transformedGeom);

        shapeList.add(shape); // add the shape to the shapeList
    }

    return shapeList; // return the final shapeList
}
