import java.util.*;

public static String normalizeEntryPath(String entryPath) {

    String normalPath = entryPath.replace("\\", "/");
    List<String> pathElements = new LinkedList<>(Arrays.asList(normalPath.split("/")));
    Iterator<String> it = pathElements.iterator();
    while(it.hasNext()) {
        String entry = it.next();
        if(entry.equals(".")) {
            it.remove();
        }else if(entry.equals("..")) {
            it.remove();
            if(it.hasNext()) {
                it.next();
                it.remove();
            }
        }
    }
    StringBuilder result = new StringBuilder();
    for(String element : pathElements) {
        result.append(element);
        result.append("/");
    }
    return result.length() == 0 ? "./" : result.toString();
}
