public static ResultSet triangleContouring(Connection connection, String tableName, Value... varArgs) throws SQLException {
        if (connection.getMetaData().getURL().equals(HACK_URL)) {
            return new ExplodeResultSet(connection,tableName, Collections.singletonList(0.0)).getResultSet();
        }
        ExplodeResultSet rowSource = null;
        if(varArgs.length > 3) {

            if(varArgs[0] instanceof ValueString &&
                    varArgs[1] instanceof ValueString &&
                    varArgs[2] instanceof ValueString) {

                List<Double> isoLvls = new ArrayList<Double>(varArgs.length - 3);
                for(int idArg = 3; idArg < varArgs.length; idArg++) {
                    isoLvls.add(varArgs[idArg].getDouble());
                }
                rowSource = new ExplodeResultSet(connection,tableName,varArgs[0].getString(), varArgs[1].getString(),
                        varArgs[2].getString(), isoLvls);
            }
        }
        if(rowSource == null) {

            List<Double> isoLvls = new ArrayList<Double>(varArgs.length);
            for (Value value : varArgs) {
                if (value instanceof ValueArray) {
                    for (Value arrVal : ((ValueArray) value).getList()) {
                        isoLvls.add(arrVal.getDouble());
                    }
                } else {
                    isoLvls.add(value.getDouble());
                }
            }
            rowSource = new ExplodeResultSet(connection,tableName, isoLvls);
        }
        return rowSource.getResultSet();
    },0

public boolean isPolygonDisjointFromEnvelope(int[][] polygon_a, int[][] envelope_b) {
    // get the minimum and maximum x and y values of both arrays
    int poly_a_min_x = Integer.MAX_VALUE, poly_a_max_x = Integer.MIN_VALUE;
    int poly_a_min_y = Integer.MAX_VALUE, poly_a_max_y = Integer.MIN_VALUE;

    int envelope_b_min_x = Integer.MAX_VALUE, envelope_b_max_x = Integer.MIN_VALUE;
    int envelope_b_min_y = Integer.MAX_VALUE, envelope_b_max_y = Integer.MIN_VALUE;

    for (int[] point : polygon_a) {
        poly_a_min_x = Math.min(poly_a_min_x, point[0]);
        poly_a_max_x = Math.max(poly_a_max_x, point[0]);
        poly_a_min_y = Math.min(poly_a_min_y, point[1]);
        poly_a_max_y = Math.max(poly_a_max_y, point[1]);
    }

    for (int[] point : envelope_b) {
        envelope_b_min_x = Math.min(envelope_b_min_x, point[0]);
        envelope_b_max_x = Math.max(envelope_b_max_x, point[0]);
        envelope_b_min_y = Math.min(envelope_b_min_y, point[1]);
        envelope_b_max_y = Math.max(envelope_b_max_y, point[1]);
    }

    // check if polygons intersect
    if (poly_a_max_x < envelope_b_min_x || poly_a_min_x > envelope_b_max_x ||
        poly_a_max_y < envelope_b_min_y || poly_a_min_y > envelope_b_max_y) {
       return true;
    }

    return false;
}
