public static String getSDK41SignatureForBackCompatibility(String appKey, String appSecret, String accessToken, String timestamp) {
    String baseString = appKey + appSecret + accessToken + timestamp;
    try {
        MessageDigest digest = MessageDigest.getInstance("SHA-1");
        byte[] hash = digest.digest(baseString.getBytes("UTF-8"));
        StringBuilder signatureBuilder = new StringBuilder();
        for (byte b : hash) {
            signatureBuilder.append(String.format("%02x", b));
        }
        return signatureBuilder.toString();
    } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
        throw new RuntimeException("Error computing SDK4.1 signature for back compatibility", e);
    }
}
