public BufferedImage fetchAndDecodeResource(String resourceName, Set<ResourceBundle> bundles) throws FileNotFoundException, IOException {
    for (ResourceBundle bundle : bundles) {
        try (InputStream stream = bundle.getResourceAsStream(resourceName)) {
            if (stream != null) {
                return ImageIO.read(new ByteArrayInputStream(stream.readAllBytes()));
            }
        }
    }
    throw new FileNotFoundException("Could not locate resource: " + resourceName);
}
