public static byte[] privateStringToBase64(String yourGooglePrivateKeyString) {
    byte[] privateBytes = yourGooglePrivateKeyString.getBytes(StandardCharsets.UTF_8);
    byte[] encodedBytes = Base64.getEncoder().encode(privateBytes);
    return encodedBytes;
}
