public int incrementBucket(int n, int[] buckets) {
    int minDiff = Integer.MAX_VALUE;
    int closestBucketIndex = 0;

    for (int i = 0; i < buckets.length; i++) {
        int diff = Math.abs(n - buckets[i]);
        if (diff < minDiff) {
            minDiff = diff;
            closestBucketIndex = i;
        }
    }

    buckets[closestBucketIndex]++;

    return buckets[closestBucketIndex];
}
