public void acquireOrTryAcquire(int permits, long timeout, TimeUnit unit, Future<?> future, boolean needRelease) throws InterruptedException, TimeoutException {
    boolean acquired = false;
    try {
        if (timeout > 0) {
            acquired = semaphore.tryAcquire(permits, timeout, unit);
        } else {
            semaphore.acquire(permits);
            acquired = true;
        }
        if (future != null && !future.isDone()) {
            future.get(timeout, unit);
        }
    } catch (ExecutionException e) {
        // handle the exception
    } finally {
        if (needRelease || !acquired) {
            semaphore.release(permits);
        }
    }
}
