public static boolean endsWithIgnoreCase(String source, String target) {
    if (source == null || target == null) {
        return false;
    }
    if (source.length() < target.length()) {
        return false;
    }
    String endOfSource = source.substring(source.length() - target.length()).toLowerCase();
    String targetLowerCase = target.toLowerCase();
    return endOfSource.equals(targetLowerCase);
}
