public Set<Ticket> assignToBucket(Set<Ticket> tickets) throws InterruptedException {
    Set<Ticket> bucket1 = new HashSet<>();
    Set<Ticket> bucket2 = new HashSet<>();

    for (Ticket ticket : tickets) {
        if (ticket.getPriority() == Priority.LOW) {
            bucket1.add(ticket);
        } else {
            bucket2.add(ticket);
        }
    }

    if (bucket2.isEmpty()) {
        return bucket1;
    } else {
        Set<Ticket> result = new HashSet<>(bucket1);
        result.addAll(bucket2);
        return result;
    }
}
