import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.BlockingDeque;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.BlockingQueue;

public class StrategicBlockingQueue<V> {

    private final BlockingQueue<V> queue;

    public StrategicBlockingQueue(QueueingStrategy strategy) {
        this.queue = new LinkedBlockingQueue<>();
        switch (strategy) {
            case FAIR:
                this.queue = new FairQueue<>();
                break;
            case LIFO:
                this.queue = Collections.asLifoQueue(new LinkedList<V>());
                break;
        }
    }

    public V take() throws InterruptedException {
        return queue.take();
    }

    public void put(V element) throws InterruptedException {
        queue.put(element);
    }

    public enum QueueingStrategy {
        FIFO, LIFO, FAIR
    }

    private static class FairQueue<T> extends LinkedBlockingQueue<T> {
        @Override
        public boolean offer(T e) {
            boolean wasAdded = super.offer(e);
            if (wasAdded) {
                unblock();
            }
            return wasAdded;
        }
        @Override
        public boolean offer(T e, long timeout, TimeUnit unit) throws InterruptedException {
            boolean wasAdded = super.offer(e, timeout, unit);
            if (wasAdded) {
                unblock();
            }
            return wasAdded;
        }
        private void unblock() {
            while (size() > 1) {
                synchronized (this) {
                    notify();
                }
                Thread.yield();
            }
        }
    }

}
