import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;

public class FileComparator {

    public static FileContentResultBean compareFiles(File sourceFile, File fileToCompare) throws IOException {
        FileContentResultBean result = new FileContentResultBean();

        try (FileInputStream sourceStream = new FileInputStream(sourceFile); FileInputStream compareStream = new FileInputStream(fileToCompare)) {
            int sourceByte;
            int compareByte;
            long byteCount = 0;

            while ((sourceByte = sourceStream.read()) != -1 && (compareByte = compareStream.read()) != -1) {
                byteCount++;

                if (sourceByte != compareByte) {
                    result.setFilesMatch(false);
                    result.setByteMismatchIndex(byteCount);
                }
            }

            if (sourceStream.read() == compareStream.read()) {
                result.setFilesMatch(true);
            }
        } 

        return result;
    }

}
