public double perlinNoise2D(double x, double y) {
    double noise = 0.0;
    double persistence = 0.5;
    int octaves = 6;
    int frequency = 1;
    int amplitude = 1;

    for (int i = 0; i < octaves; i++) {
        double fx = x / frequency;
        double fy = y / frequency;

        int ix1 = (int) Math.floor(fx);
        int iy1 = (int) Math.floor(fy);
        int ix2 = ix1 + 1;
        int iy2 = iy1 + 1;

        double tx = fx - ix1;
        double ty = fy - iy1;

        double w1 = (1 - tx) * (1 - ty);
        double w2 = tx * (1 - ty);
        double w3 = (1 - tx) * ty;
        double w4 = tx * ty;

        double val1 = getNoise(ix1, iy1);
        double val2 = getNoise(ix2, iy1);
        double val3 = getNoise(ix1, iy2);
        double val4 = getNoise(ix2, iy2);

        double value = w1 * val1 + w2 * val2 + w3 * val3 + w4 * val4;

        noise += value * amplitude;

        amplitude *= persistence;
        frequency *= 2;
    }

    return noise;
}

private double getNoise(int x, int y) {
