public static ApproximateHistogram constructApproxHistogram(ByteBuffer buf) {
    int numBins = buf.getInt();
    int subBucketSize = buf.getInt();
    int minVal = buf.getInt();
    long totalCount = buf.getLong();

    int numSubBuckets = (numBins + subBucketSize - 1) / subBucketSize; // Equivalent to ceil(numBins/subBucketSize)
    int[] subBucketCounts = new int[numSubBuckets];
    boolean[] nonZeroSubBucket = new boolean[numSubBuckets];

    for (int i = 0; i < numSubBuckets; ++i) {
        int count = buf.getInt();
        subBucketCounts[i] = count;
        if (count != 0) {
            nonZeroSubBucket[i] = true;
        }
    }

    int bucketCount = buf.getInt();
    int[] bucketOffsets = new int[bucketCount + 1];
    int[] bucketVals = new int[bucketCount];

    for (int i = 0; i < bucketCount; ++i) {
        bucketOffsets[i] = buf.getInt();
        bucketVals[i] = buf.getInt();
    }

    bucketOffsets[bucketCount] = numBins;

    return new ApproximateHistogram(subBucketSize, numSubBuckets, minVal, totalCount, subBucketCounts, nonZeroSubBucket, bucketOffsets, bucketVals);
}
