public static void prewittEdgeDetector(Mat orig, Mat derivX, Mat derivY, Mat border) {
    if (border == null) {
        Imgproc.filter2D(orig, derivX, CvType.CV_32F, new Mat(-1, -1, new float[] {-1, 0, 1, -1, 0, 1, -1, 0, 1}));
        Imgproc.filter2D(orig, derivY, CvType.CV_32F, new Mat(-1, -1, new float[] {-1, -1, -1, 0, 0, 0, 1, 1, 1}));
    } else {
        Mat padded = new Mat();
        int padding = 1;
        Core.copyMakeBorder(orig, padded, padding, padding, padding, padding, border);
        prewittEdgeDetector(padded, derivX, derivY, null);
    }
}
