public void checkForChanges(File xmlConfigFile, String lastTimeRead) {
    Path filePath = Paths.get(xmlConfigFile.getAbsolutePath());
    long lastModifiedTime = xmlConfigFile.lastModified();

    if(lastTimeRead == null || Long.parseLong(lastTimeRead) < lastModifiedTime) {
        // There has been a change in file
        DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
        try {
            DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();
            Document document = documentBuilder.parse(xmlConfigFile);
            document.getDocumentElement().normalize();

            Element root = document.getDocumentElement();

            // Perform necessary actions with the root element...

            // Update last read time
            updateLastReadTime(filePath, Long.toString(lastModifiedTime));
        } catch (ParserConfigurationException | IOException | SAXException e) {
            e.printStackTrace();
        }
    }
}

private void updateLastReadTime(Path filePath, String lastModifiedTime) {
    try {
        DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();
        Document document = documentBuilder.newDocument();

        Element rootElement = document.createElement("settings");
        document.appendChild(rootElement);

        Element nameElement = document.createElement("last-read-time");
        nameElement.appendChild(document.createTextNode(lastModifiedTime));
        rootElement.appendChild(nameElement);

        TransformerFactory transformerFactory = TransformerFactory.newInstance();
        Transformer transformer = transformerFactory.newTransformer();
        DOMSource source = new DOMSource(document);

        StreamResult result = new StreamResult(filePath.toFile());
        transformer.transform(source, result);
    } catch (ParserConfigurationException | TransformerException e) {
        e.printStackTrace();
    }
}
