public BeanDefinition defineBean(String name, Object[] args) {
    Class<?> clazz = null;
    Object[] constructorArgs = null;
    Object closure = null;
    if (args.length > 0) {
        clazz = (Class<?>) args[0];
    }
    if (args.length > 2) {
        constructorArgs = Arrays.copyOfRange(args, 1, args.length - 1);
    }
    if (args.length > 1) {
        closure = args[args.length - 1];
    }
    BeanDefinition beanDefinition = new BeanDefinition();
    beanDefinition.setName(name);
    beanDefinition.setClazz(clazz);
    beanDefinition.setConstructorArgs(constructorArgs);
    beanDefinition.setClosure(closure);
    return beanDefinition;
}
