public static long readCompactInt(ByteBuffer buf) {
    int numBytes = 1;
    byte b = buf.get();
    long value = b & 0x7F;
    while ((b & 0x80) != 0) {
        if (!buf.hasRemaining()) {
            return -1L;
        }
        b = buf.get();
        value |= (long)(b & 0x7F) << (7 * numBytes);
        numBytes++;
    }
    return value;
}
