public PublicKey getPublicKey(String alg, byte[] keyBytes) throws InvalidPublicKeyException {
    if(!alg.equals("RSA")) {
        throw new InvalidPublicKeyException("The algorithm type is not RSA");
    }
    try {
        X509EncodedKeySpec spec = new X509EncodedKeySpec(keyBytes);
        KeyFactory kf = KeyFactory.getInstance("RSA");
        return kf.generatePublic(spec);
    } catch (InvalidKeySpecException | NoSuchAlgorithmException e) {
        throw new InvalidPublicKeyException("PublicKey can not be built", e);
    }
}
