import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public static String generateDigest(String algorithm, String key) throws NoSuchAlgorithmException {
    MessageDigest digest = MessageDigest.getInstance(algorithm);
    byte[] hashedBytes = digest.digest(key.getBytes());

    StringBuilder stringBuilder = new StringBuilder();

    for (int i = 0; i < hashedBytes.length; i++) {
        stringBuilder.append(Integer.toString((hashedBytes[i] & 0xff) + 0x100, 16).substring(1));
    }

    return stringBuilder.toString();
}
