public void writeTrampoline(long address, long target) {
    byte[] trampoline = new byte[] {(byte) 0xE9, 0, 0, 0, 0}; // Opcode for 'JMP'

    long relativeJump = target - address - 5; // '5' is size of opcode plus size of address
    byte[] relativeJumpBytes = ByteBuffer.allocate(4).putInt((int)relativeJump).array(); // Convert int to byte array
    System.arraycopy(relativeJumpBytes, 0, trampoline, 1, 4); // Write the relative jump offset into trampoline

    // Write the trampoline into code at address
    for (int i = 0; i < trampoline.length; i++) {
        unsafe.putByte(address + i, trampoline[i]);
    }
}
