public class AttributeConverter {

    public static Set<String> convertToAttributeNames(Class<?> classToInspect, Predicate<Field> filter) {
        Set<String> attributeNames = new HashSet<>();
        for (Field field : getAllAttributes(classToInspect)) {
            if (filter.test(field)) {
                attributeNames.add(field.getName());
            }
        }
        return attributeNames;
    }

    public static Field[] getAllAttributes(Class<?> classToInspect) {
        return classToInspect.getDeclaredFields();
