import java.io.File;
import java.io.FileWriter;
import java.io.IOException;

public class MergeFiles {

    public static void main(String[] args) {
        String sourceFilePath1 = "sourceFile1.txt";
        String sourceFilePath2 = "sourceFile2.txt";
        String parityFilePath = "parityFile.txt";

        createSourceFile(sourceFilePath1);
        createSourceFile(sourceFilePath2);
        createParityFile(sourceFilePath1, sourceFilePath2, parityFilePath);
    }

    private static void createSourceFile(String filePath) {
        try (FileWriter fileWriter = new FileWriter(filePath)) {
            fileWriter.write("This is a mock source file.");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void createParityFile(String sourceFilePath1, String sourceFilePath2, String parityFilePath) {
        try (FileWriter fileWriter = new FileWriter(parityFilePath)) {
            File file1 = new File(sourceFilePath1);
            File file2 = new File(sourceFilePath2);

            if (file1.exists() && file2.exists()) {
                String sourceContents1 = readFileContents(file1);
                String sourceContents2 = readFileContents(file2);

                fileWriter.write(sourceContents1 + " " + sourceContents2);
            } else {
                System.out.println("Error: One or both of the source files do not exist.");
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static String readFileContents(File file) throws IOException {
        StringBuilder stringBuilder = new StringBuilder();

        try (java.util.Scanner scanner = new java.util.Scanner(file)) {
            while (scanner.hasNextLine()) {
                stringBuilder.append(scanner.nextLine());
            }
        }

        return stringBuilder.toString();
    }
}
