public static boolean masks(String r1, String r2) {
    int i = 0;
    int j = 0;
    int n1 = r1.length();
    int n2 = r2.length();
    while (i < n1 && j < n2) {
        if (r1.charAt(i) == r2.charAt(j)) {
            i++;
            j++;
        } else if (r1.charAt(i) == '[') {
            i++;
            while (i < n1 && r1.charAt(i) != ']') {
                if (r1.charAt(i) == r2.charAt(j)) {
                    i++;
                    j++;
                } else {
                    return false;
                }
            }
            i++;
        } else {
            return false;
        }
    }
    return j == n2;
}
