import java.lang.reflect.*;

public class TypeDescription {
    public static String describe(Type type) {
        StringBuilder sb = new StringBuilder();

        if (type instanceof Class<?>) {
            Class<?> clazz = (Class<?>)type;
            if (clazz.isArray()) {
                sb.append(describe(clazz.getComponentType())).append("[]");
            } else {
                sb.append(clazz.getName());
            }
        } else if (type instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) type;

            Type[] typeArgs = parameterizedType.getActualTypeArguments();
            StringBuilder typeArgsStr = new StringBuilder();
            for (Type typeArg : typeArgs) {
                if (typeArgsStr.length() > 0) {
                    typeArgsStr.append(", ");
                }
                typeArgsStr.append(describe(typeArg));
            }

            sb.append(describe(parameterizedType.getRawType()))
                .append("<").append(typeArgsStr).append(">");
        } else if (type instanceof TypeVariable<?>) {
            TypeVariable<?> typeVariable = (TypeVariable<?>) type;
            sb.append(typeVariable.getName());
        }

        return sb.toString();
    }
}
