public double[] adaptClassifier(double[] origWeights, double[][] adaptDataset) {
  double[] adaptedWeights = new double[origWeights.length];
  double n = (double) adaptDataset.length;
  double[] mean = getMean(adaptDataset);

  for (int i = 0; i < origWeights.length; i++) {
    adaptedWeights[i] = (origWeights[i] * n) / (n + 1);
    adaptedWeights[i] += (mean[i] / (n + 1));
  }

  return adaptedWeights;
}

private double[] getMean(double[][] data) {
  double[] mean = new double[data[0].length];
  for (int i = 0; i < data[0].length; i++) {
    double sum = 0;
    for (int j = 0; j < data.length; j++) {
      sum += data[j][i];
    }
    mean[i] = sum / (double) data.length;
  }
  return mean;
}
