public static String[] appendLength(int[] values, int givenValue) {
    String[] result = new String[values.length];
    int lengthSum = 0;
    for (int i = 0; i < values.length; i++) {
        lengthSum += String.valueOf(values[i]).length();
        if (values[i] == givenValue) {
            break;
        }
    }
    for (int j = 0; j < values.length; j++) {
        if (values[j] == givenValue) {
            break;
        }
        result[j] = values[j] + String.valueOf(lengthSum);
        lengthSum -= String.valueOf(values[j]).length();
    }
    return result;
}
