public void replaceAddresses(List<Address> existingAddresses, List<Address> newAddresses) {
    Iterator<Address> existingIter = existingAddresses.iterator();
    while (existingIter.hasNext()) {
        Address existingAddress = existingIter.next();
        Iterator<Address> newIter = newAddresses.iterator();
        while (newIter.hasNext()) {
            Address newAddress = newIter.next();
            if (existingAddress.getHost().equals(newAddress.getHost()) &&
                existingAddress.getPort() == newAddress.getPort()) {
                newIter.remove();
            }
        }
    }
    existingAddresses.addAll(newAddresses);
}
