public static String getPropertyName(String methodName,
                                         int parameterCount,
                                         String returnType) {
        if ( methodName == null ) {
            return null;
        }
        String simpleName = methodName.replaceAll( "\\(\\)",
                                                   "" );
        int prefixLength = 0;
        if ( isIsGetter( simpleName,
                         parameterCount,
                         returnType ) ) {
            prefixLength = 2;
        } else if ( isGetter( simpleName,
                              parameterCount,
                              returnType )  
                    || isSetter( simpleName,
                                 parameterCount,
                                 returnType ) ) {
            prefixLength = 3;
        } else {
            return methodName;
        }
        char firstChar = Character.toLowerCase( simpleName.charAt( prefixLength ) );
        String propertyName = firstChar + simpleName.substring( prefixLength + 1 );
        return propertyName;
