public static float scanSVGNumber(String str, int startPos, int maxPos) {
    int endPos = startPos;
    boolean hasExp = false;
    boolean hasDot = false;
    boolean hasSign = false;

    while (endPos < maxPos) {
        char c = str.charAt(endPos);
        if ((c == '-') || (c == '+')) {
            if (!hasSign) {
                hasSign = true;
            } else {
                break;
            }
        } else if (c == '.') {
            if (!hasDot) {
                hasDot = true;
            } else {
                break;
            }
        } else if ((c == 'e') || (c == 'E')) {
            if (!hasExp) {
                hasExp = true;
                hasSign = false;
                hasDot = true;
            } else {
                break;
            }
        } else if ((c >= '0') && (c <= '9')) {
            if (hasExp) {
                hasSign = true;
                hasDot = true;
            }
        } else {
            break;
        }
        endPos++;
    }

    if (endPos == startPos) {
        return Float.NaN;
    }

    return Float.parseFloat(str.substring(startPos, endPos));
}
