public static long compress(long inputAddr, long inputSize, long destAddr) throws IOException {
    long result = -1;

    try (MemorySegment input = MemorySegment.mapFromAddress(inputAddr, inputSize, MemorySegment.ReadOnlyOption.READ_ONLY);
         MemorySegment output = MemorySegment.mapFromAddress(destAddr, inputSize)) {

        // Compress the data using zero-copy technique
        // Here you can use any compression algorithm of your choice
        // I'm using Snappy as an example
        int compressedSize = Snappy.compress(input.asByteBuffer(), output.asByteBuffer());

        result = compressedSize;
    }

    return result;
}
