public List<DoubleSolution> createNonDominatedSolutionList(Problem<DoubleSolution> problem) throws FileNotFoundException {

    List<DoubleSolution> solutionList = new ArrayList<>();

    // Read in the FUNx.tsv and VARx.tsv files
    List<List<Double>> funList = Utils.readFront(Utils.getInputFile(problem.getName() + ".FUN.tsv"));
    List<List<Double>> varList = Utils.readVars(Utils.getInputFile(problem.getName() + ".VAR.tsv"));

    // Create the solution list and add each solution
    for (int i = 0; i < funList.size(); i++) {
        DoubleSolution solution = problem.createSolution();
        for (int j = 0; j < problem.getNumberOfObjectives(); j++) {
            solution.setObjective(j, funList.get(i).get(j));
        }
        for (int j = 0; j < problem.getNumberOfVariables(); j++) {
            solution.setVariable(j, new RealVariable(varList.get(i).get(j)));
        }
        solutionList.add(solution);
    }

    // Return the list of non dominated solutions
    return new NonDominatedSolutionList<>(solutionList);
}
