public ReportLayout addHiddenFunctionsToFooter(ReportLayout layout) {
    List<Function> headerFunctions = getFunctionsInHeader(layout);
    List<Function> groupHeaderFunctions = getFunctionsInGroupHeader(layout);

    for (Function headerFunction : headerFunctions) {
        Function footerFunction = headerFunction.clone();
        footerFunction.setHidden(true);
        layout.getFooter().getFunctions().add(footerFunction);
    }

    for (Group group : layout.getGroups()) {
        List<Function> groupFunctions = getFunctionsInGroup(group);
        for (Function groupFunction : groupFunctions) {
            Function groupFooterFunction = groupFunction.clone();
            groupFooterFunction.setHidden(true);
            group.getFooter().getFunctions().add(groupFooterFunction);
        }
    }

    return layout;
}

private List<Function> getFunctionsInHeader(ReportLayout layout) {
    List<Function> headerFunctions = new ArrayList<>();
    headerFunctions.addAll(layout.getHeader().getFunctions());
    return headerFunctions;
}

private List<Function> getFunctionsInGroupHeader(ReportLayout layout) {
    List<Function> groupHeaderFunctions = new ArrayList<>();
    for (Group group : layout.getGroups()) {
        groupHeaderFunctions.addAll(group.getHeader().getFunctions());
    }
    return groupHeaderFunctions;
}

private List<Function> getFunctionsInGroup(Group group) {
    List<Function> groupFunctions = new ArrayList<>();
    groupFunctions.addAll(group.getHeader().getFunctions());
    groupFunctions.addAll(group.getFunctions());
    return groupFunctions;
}
