public int readRawVarint32() throws IOException
    {
        byte tmp = readRawByte();
        if (tmp >= 0)
        {
            return tmp;
        }
        int result = tmp & 0x7f;
        if ((tmp = readRawByte()) >= 0)
        {
            result |= tmp << 7;
        }
        else
        {
            result |= (tmp & 0x7f) << 7;
            if ((tmp = readRawByte()) >= 0)
            {
                result |= tmp << 14;
            }
            else
            {
                result |= (tmp & 0x7f) << 14;
                if ((tmp = readRawByte()) >= 0)
                {
                    result |= tmp << 21;
                }
                else
                {
                    result |= (tmp & 0x7f) << 21;
                    result |= (tmp = readRawByte()) << 28;
                    if (tmp < 0)
                    {

                        for (int i = 0; i < 5; i++)
                        {
                            if (readRawByte() >= 0)
                            {
                                return result;
                            }
                        }
                        throw ProtobufException.malformedVarint();
                    }
                }
            }
        }
        return result;
    },0

public static Histogram decodeFromByteBuffer(ByteBuffer buffer, long minBarForHighestTrackableValue) {
    Histogram histogram = new Histogram(minBarForHighestTrackableValue);
    int cookie = buffer.getInt();
    if (cookie != PackedHistogram.COOKIES_BASE) {
        throw new IllegalStateException("The buffer does not contain a Histogram");
    }
    histogram.updatedMaxValue(buffer.getLong());
    histogram.setStartTimeStamp(buffer.getLong());
    histogram.setEndTimeStamp(buffer.getLong());
    histogram.setTotalCount(buffer.getLong());
    histogram.countsLen = buffer.getInt();
    histogram.wordSizeInBytes = buffer.getInt();
    int compressedSizeInBytes = buffer.getInt();
    int uncompressedSizeInBytes = buffer.getInt();
    ByteBuffer uncompressedBuffer = ByteBuffer.allocate(uncompressedSizeInBytes);

    if (compressedSizeInBytes > 0) {
        ByteBuffer compressedBuffer = buffer.slice();
        compressedBuffer.limit(compressedSizeInBytes);
        Inflater inflater = new Inflater();
        inflater.setInput(compressedBuffer.array(), compressedBuffer.arrayOffset() + compressedBuffer.position(), compressedSizeInBytes);
        try {
            inflater.inflate(uncompressedBuffer.array());
        } catch (DataFormatException ex) {
            throw new RuntimeException("Could not decompress buffer", ex);
        }
        inflater.end();
    } else {
        uncompressedBuffer.put(buffer);
        uncompressedBuffer.flip();
    }

    int[] counts = new int[histogram.countsLen];
    LongBuffer src = uncompressedBuffer.order(ByteOrder.nativeOrder()).asLongBuffer();
    for (int i = 0; i < counts.length; i++) {
        counts[i] = (int) src.get();
    }
    histogram.setCounts(counts);
    return histogram;
}
