public static <T> T[] evaluate(List<?> values, Class<T> targetType) {
    // Create array of the target attribute type with the same size as the input list
    T[] result = (T[]) Array.newInstance(targetType, values.size());

    // Iterate through the input list and cast each element to the target attribute type
    for (int i = 0; i < values.size(); i++) {
        result[i] = targetType.cast(values.get(i));
    }

    return result;
}
