public String determineInputEncoding(Node nodeArg) {
    String inputEncoding = null;
    if (nodeArg instanceof Document) {
        Document document = (Document) nodeArg;
        inputEncoding = document.getInputEncoding();
    }
    else if (nodeArg instanceof DocumentType) {
        DocumentType documentType = (DocumentType) nodeArg;
        inputEncoding = documentType.getOwnerDocument().getInputEncoding();
    }
    else if (nodeArg instanceof DOMImplementation) {
        DOMImplementation domImplementation = (DOMImplementation) nodeArg;
        inputEncoding = domImplementation.getFeature("Core","3.0").getInputEncoding();
    }
    return inputEncoding;
}
