public List<Object> checkForConflicts(List<Update> updates) {
    List<Object> conflicts = new ArrayList<>();
    for (int i = 0; i < updates.size(); i++) {
        for (int j = i + 1; j < updates.size(); j++) {
            if (updates.get(i).overlaps(updates.get(j))) {
                conflicts.add(updates.get(i));
                conflicts.add(updates.get(j));
            }
        }
    }
    return conflicts;
}
