public boolean isDistinctOperation(Node node) {
   // Assuming that the node object contains the corresponding SQL statement
   String sqlStatement = node.getSqlStatement(); 
   // Regular expression to match DISTINCT keyword in SQL statement
   String regex = "\\bDISTINCT\\b"; 

   // Testing whether the SQL statement contains DISTINCT keyword or not
   if (sqlStatement.matches("(?i).*" + regex + ".*")) {
      return true;
   } else {
      return false;
   }
}
