public int determineDataSize(Source source) throws DataSourceException {
    int size = 0;
    try {
        Object obj = source.getObjectInstance();
        ByteArrayOutputStream byteOutStream = new ByteArrayOutputStream();
        ObjectOutputStream objectOutStream = new ObjectOutputStream(byteOutStream);
        objectOutStream.writeObject(obj);
        objectOutStream.flush();
        objectOutStream.close();
        size = byteOutStream.toByteArray().length;
    } catch (IOException e) {
        throw new DataSourceException("Size information cannot be acquired", e);
    }
    return size;
}
