public boolean check(ByteBuffer data)
    {
        assert (data != null);
        int size = data.limit();


        Trie current = this;
        int start = 0;
        while (true) {

            if (current.refcnt > 0) {
                return true;
            }

            if (size == 0) {
                return false;
            }


            byte c = data.get(start);
            if (c < current.min || c >= current.min + current.count) {
                return false;
            }

            if (current.count == 1) {
                current = current.next[0];
            }
            else {
                current = current.next[c - current.min];
                if (current == null) {
                    return false;
                }
            }
            start++;
            size--;
        }
    },0

