public static DistanceFunction createCachedDistanceFunction(DistanceFunction distanceFunction) {
    return new DistanceFunction() {
        private final Map<Pair<Object, Object>, Double> cache = new HashMap<>();

        @Override
        public double calculate(Object o1, Object o2) {
            Pair<Object, Object> pair = new Pair<>(o1, o2);
            Double cachedValue = cache.get(pair);
            if (cachedValue != null) {
                return cachedValue;
            }
            double distance = distanceFunction.calculate(o1, o2);
            cache.put(pair, distance);
            return distance;
        }
    };
}
