public void getBoundingBox(double[] xcoords, double[] ycoords) {
    double xmin = xcoords[0];
    double xmax = xcoords[0];
    double ymin = ycoords[0];
    double ymax = ycoords[0];

    for (int i = 1; i < xcoords.length; i++) {
        xmin = Math.min(xmin, xcoords[i]);
        xmax = Math.max(xmax, xcoords[i]);
        ymin = Math.min(ymin, ycoords[i]);
        ymax = Math.max(ymax, ycoords[i]);
    }

    System.out.println("BoundingBox: xmin=" + xmin + ", xmax=" + xmax + ", ymin=" + ymin + ", ymax=" + ymax);
}
