public void startAndroidEmulator() throws MojoExecutionException {
    try {
        String[] cmdArray = {"emulator", "-avd", emulatorAvd, "-no-snapshot-load", "-no-snapshot-save", "-no-window", emulatorOptions};
        Process process = Runtime.getRuntime().exec(cmdArray);
        // Wait for the emulator to start (default 2 minutes)
        boolean emulatorStarted = false;
        long startTime = System.currentTimeMillis();
        long emulatorWaitTime = emulatorWait * 1000;
        do {
            if (process.getInputStream().available() > 0) {
                Scanner scanner = new Scanner(process.getInputStream());
                while (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    if (line.contains("boot completed")) {
                        emulatorStarted = true;
                        break;
                    }
                }
                scanner.close();
            }
            Thread.sleep(100);
        } while (!emulatorStarted && System.currentTimeMillis() - startTime < emulatorWaitTime);
        if (!emulatorStarted) {
            throw new MojoExecutionException("Failed to start the emulator");
        }
    } catch (Exception e) {
        throw new MojoExecutionException("Failed to start the emulator", e);
    }
}
