public void closeEntry() throws IOException, ZipException {
    if (closed) {
        throw new IOException("Stream is closed");
    }
    if (entry == null) {
        throw new ZipException("No current zip entry");
    }
    // finalize current entry
    def.finish();
    // update central directory
    cdos.write(def.getLocalFileHeader());
    if (def.zip64 && !skipWriting) {
        Zip64EndOfCentralDirectoryRecord zip64eocd =
            new Zip64EndOfCentralDirectoryRecord(entries.size(),
                                                 cdos.getByteCount(),
                                                 cdos.getStart(),
                                                 def.getZip64EndCentralDirLocator().getOffset());
        zip64eocd.write(cdos);
        def.getZip64EndCentralDirLocator().write(cdos);
    }
    // write central directory entry
    byte[] commentBytes = (entry.comment != null) ? getBytes(entry.comment) : null;
    def.writeEntry(entry, commentBytes, cdos);
    // and reset for next entry
    def.reset();
    written += def.getBytesWritten();
    entry = null;
}
