public Set<String> findImportableFiles(File appDirectory, File editedFile, String fileContent) {
    Set<String> importableFiles = new HashSet<>();
    if (appDirectory == null || editedFile == null || fileContent == null) {
        return importableFiles;
    }
    String editedFilePath = editedFile.getAbsolutePath();
    File[] files = appDirectory.listFiles();
    if (files != null) {
        for (File file : files) {
            String relativePath = appDirectory.toPath().relativize(file.toPath()).toString();
            String content = readFile(file);
            if (!editedFilePath.equals(file.getAbsolutePath()) && content != null && content.contains(fileContent)) {
                importableFiles.add(relativePath);
            }
        }
    }
    return importableFiles;
}

private String readFile(File file) {
    StringBuilder stringBuilder = new StringBuilder();
    try (Scanner scanner = new Scanner(file)) {
        while (scanner.hasNextLine()) {
            stringBuilder.append(scanner.nextLine());
        }
    } catch (FileNotFoundException e) {
        e.printStackTrace();
    }
    return stringBuilder.toString();
}
