public Map<Object, Object> populateBlobData(Map<Class<?>, Class<?>> mapGenericClasses, Class<?> keyClass, Class<?> valueClass, Map<?, ?> rawMap) {
    Map<Object, Object> resultMap = new HashMap<>();

    if (mapGenericClasses.containsKey(keyClass) && mapGenericClasses.get(keyClass).equals(byte[].class)) {
        keyClass = byte[].class;
    }

    if (mapGenericClasses.containsKey(valueClass) && mapGenericClasses.get(valueClass).equals(byte[].class)) {
        valueClass = byte[].class;
    }

    for (Map.Entry<?, ?> entry : rawMap.entrySet()) {
        Object key = entry.getKey();
        Object value = entry.getValue();

        if (valueClass.equals(byte[].class)) {
            value = iterateAndUpdateBlobData(value);
        }

        if (keyClass.equals(byte[].class)) {
            key = iterateAndUpdateBlobData(key);
        }

        resultMap.put(key, value);
    }

    return resultMap;
}

private Object iterateAndUpdateBlobData(Object data) {
    if (data instanceof Blob) {
        data = populateBlobData(((Blob) data).getMapGenericClasses(), ((Blob) data).getKeyClass(),
                ((Blob) data).getValueClass(), ((Blob) data).getRawMap());
    }

    if (data instanceof List) {
        List<?> dataList = (List<?>) data;
        List<Object> modifiedList = new ArrayList<>();

        for (Object listData : dataList) {
            modifiedList.add(iterateAndUpdateBlobData(listData));
        }

        return modifiedList;
    }

    if (data instanceof Map) {
        Map<?, ?> dataMap = (Map<?, ?>) data;

        return populateBlobData(((Blob) data).getMapGenericClasses(), ((Blob) data).getKeyClass(),
                ((Blob) data).getValueClass(), dataMap);
    }

    return data;
}
