public List<GET_DIGEST_RSP> multicastGetDigestReq(int N) {
    List<GET_DIGEST_RSP> responses = new ArrayList<>();
    List<Member> members = getSubPartitionMembers(); // get a list of members in this sub partition

    // multicast GET_DIGEST_REQ to all members
    for (Member member : members) {
        GET_DIGEST_REQ req = new GET_DIGEST_REQ();
        req.setSubPartition(getSubPartitionId());
        req.setSender(getLocalMemberId());
        req.send(member.getAddress());
    }

    // wait for responses for N milliseconds
    long endTime = System.currentTimeMillis() + N;
    while (System.currentTimeMillis() < endTime) {
        GET_DIGEST_RSP rsp = receiveGetDigestRsp(); // receive response
        if (rsp != null) {
            responses.add(rsp);
        }
    }
    return responses;
}
