public ConfigObject resolveTokens(ConfigObject datasetConfig, String realDbAndTable, String logicalDbAndTable) {
    String realDB = realDbAndTable.split("\\.")[0];
    String realTable = realDbAndTable.split("\\.")[1];
    String logicalDB = logicalDbAndTable.split("\\.")[0];
    String logicalTable = logicalDbAndTable.split("\\.")[1];

    String rawConfig = datasetConfig.getRawConfig();
    rawConfig = rawConfig.replace("DB", realDB);
    rawConfig = rawConfig.replace("TABLE", realTable);
    rawConfig = rawConfig.replace("LOGICAL_DB", logicalDB);
    rawConfig = rawConfig.replace("LOGICAL_TABLE", logicalTable);

    datasetConfig.setRawConfig(rawConfig);
    return datasetConfig;
}
