import org.apache.zookeeper.CreateMode;
import org.apache.zookeeper.ZooDefs;
import org.apache.zookeeper.ZooKeeper;
import org.apache.zookeeper.data.ACL;
import org.apache.zookeeper.KeeperException;

import java.util.List;

public class ZkDirectoryCreator {

    private static final List<ACL> DEFAULT_ACL = ZooDefs.Ids.OPEN_ACL_UNSAFE;
    private static final CreateMode DEFAULT_CREATE_MODE = CreateMode.PERSISTENT;

    /**
     * Creates all the required base directories in ZK for the application to run.
     * @param zk the ZooKeeper client instance.
     * @param path the path of the base directories to create.
     * @throws KeeperException if there's an error accessing ZK.
     * @throws InterruptedException if the current thread is interrupted.
     */
    public static void createBaseDirectories(ZooKeeper zk, String path) throws KeeperException, InterruptedException {
        String[] pathParts = path.split("/");
        String currentPath = "";
        for (String pathPart : pathParts) {
            if (!pathPart.isEmpty()) {
                currentPath += "/" + pathPart;
                try {
                    zk.create(currentPath, new byte[0], DEFAULT_ACL, DEFAULT_CREATE_MODE);
                } catch (KeeperException.NodeExistsException e) {
                    // Node already exists, ignore.
                }
            }
        }
    }
}
