    if (sm != null) {
        sm.checkPermission(SecurityConstants.GET_CLASSLOADER_PERMISSION);
        if (privileged) {
            sm.checkPermission(SecurityConstants.GET_CLASSLOADER_PERMISSION_WITH_ACC);
        }
    }

    Class<?> c = this.getClass();
    if (privileged && (c.getClassLoader() == null)) {
        return getDeclaredMethodsInternal(c, true);
    }
    return c.getMethods();
