public List<ns_conf_upgrade_history> fetchFilteredNsConfUpgradeHistory(String filter) {
    // Initialize list to hold filtered ns_conf_upgrade_history resources
    List<ns_conf_upgrade_history> filteredResources = new ArrayList<>();

    // Parse and extract filter parameters from input JSON
    JsonObject filterJson = new Gson().fromJson(filter, JsonObject.class);
    String vmState = filterJson.get("vm_state").getAsString();
    String namePattern = filterJson.get("name").getAsString();

    // Filter ns_conf_upgrade_history resources based on the extracted parameters
    for (ns_conf_upgrade_history resource : ns_conf_upgrade_historyList) {
        if (resource.getVmState().equals(vmState) && resource.getName().matches(namePattern)) {
            filteredResources.add(resource);
        }
    }

    // Return filtered list of ns_conf_upgrade_history resources
    return filteredResources;
}
