import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.linalg.api.memory.MemoryWorkspace;
import org.nd4j.linalg.api.memory.MemoryWorkspaceManager;
import org.nd4j.linalg.api.ops.executioner.OpExecutioner;
import org.nd4j.linalg.api.ops.executioner.OpStatus;

public class Example {

    public static void markActualLocation(INDArray array, OpExecutioner.Location location) {

        try(MemoryWorkspace ws = Nd4j.getWorkspaceManager().scopeOutOfWorkspaces()) {

            MemoryWorkspaceManager mgr = Nd4j.getWorkspaceManager();
            if (mgr.checkIfWorkspaceExistsAndActive("SOME_OTHER_WORKSPACE"))
                mgr.getWorkspace("SOME_OTHER_WORKSPACE").destroyWorkspace(false);

            OpExecutioner executioner = Nd4j.getExecutioner();
            executioner.push();

            // Mark actual on the specified location
            OpStatus status = executioner.exec(
                new SetOp(array, array.dup(), location)
            );

            switch(location) {
                case HOST:
                    array.migrate();
                    break;
                case DEVICE:
                    ((BaseCudaDataBuffer) array.data()).lazyAllocateHostPointer();
                    break;
                default:
                    throw new UnsupportedOperationException("Unknown arrays location: " + location);
            }

            executioner.commit();
        }
    }

    public static void main(String[] args) {

        INDArray array = Nd4j.ones(5, 5);

        // Mark the array as actual on the device
        markActualLocation(array, OpExecutioner.Location.DEVICE);

        // Print the array
        System.out.println(array.toString());

    }
}
