        throw new MojoExecutionException("Invalid configuration: repositories is null or empty.");
    }

    // create the artifact store from repositories configuration
    ArtifactStore store = new ArtifactStore();
    // add repositories to the store
    for(Repository repo : repositories) {
        store.addRepository(repo);
    }

    return store;
}
