public static Point2D.Double applyDistortion(Point2D.Double normPt, double[] radial, double t1, double t2) {

    double r2 = Math.pow(normPt.x, 2) + Math.pow(normPt.y, 2);
    double radialDistortion = 1 + (radial[0] * r2) + (radial[1] * Math.pow(r2, 2)) + (radial[4] * Math.pow(r2, 3));
    double xTanDistortion = 2 * t1 * normPt.x * normPt.y + t2 * (r2 + 2 * Math.pow(normPt.x, 2));
    double yTanDistortion = t1 * (r2 + 2 * Math.pow(normPt.y, 2)) + 2 * t2 * normPt.x * normPt.y;

    double xDistorted = normPt.x * radialDistortion + xTanDistortion;
    double yDistorted = normPt.y * radialDistortion + yTanDistortion;
    return new Point2D.Double(xDistorted, yDistorted);
}
