public List<Node> rangeSearch(Node node, Query q, double k) {
    List<Node> neighbors = new ArrayList<>();

    // If the current node is null, return empty neighbors list
    if (node == null) {
        return neighbors;
    }

    // Check if current node is within the range of query
    if (q.withinRange(node)) {
        if (q.distanceTo(node) <= k) {
            neighbors.add(node);
        }
    }

    // Recursively call rangeSearch on the left subtree
    if (node.left != null && node.left.subtreeMaxDistTo(q.target) >= q.targetDist - k) {
        neighbors.addAll(rangeSearch(node.left, q, k));
    }

    // Recursively call rangeSearch on the right subtree
    if (node.right != null && node.right.subtreeMaxDistTo(q.target) >= q.targetDist - k) {
        neighbors.addAll(rangeSearch(node.right, q, k));
    }

    return neighbors;
}
