public static int[] getSolutionRank(List<Solution> population) {
    int popSize = population.size();
    int[] ranks = new int[popSize];
    List<Solution> currentFront = new ArrayList<>();

    for (int i = 0; i < popSize; i++) {
        Solution p = population.get(i);
        ranks[i] = 1;
        for (int j = 0; j < popSize; j++) {
            if (i == j) continue;
            Solution q = population.get(j);
            if (q.isFeasible() && p.isDominant(q)) {
                ranks[i]++;
            }
        }
        if (ranks[i] == 1) {
            currentFront.add(p);
        }
    }
    int front = 0;
    while (!currentFront.isEmpty()) {
        List<Solution> nextFront = new ArrayList<>();
        for (Solution p : currentFront) {
            for (int j = 0; j < popSize; j++) {
                if (ranks[j] != front+1) continue;
                Solution q = population.get(j);
                if (p.isDominant(q)) {
                    ranks[j]--;
                    if (ranks[j] == 1) {
                        nextFront.add(q);
                    }
                }
            }
        }
        front++;
        currentFront = nextFront;
    }
    return ranks;
}
