public int removeNeurons(List<Neuron> neurons, int minPts) {
    Set<Neuron> removableNeurons = new HashSet<>();
    Set<Neuron> neighborlessNeurons = new HashSet<>();

    for (Neuron neuron : neurons) {
        if (neuron.getSamples().size() < minPts) {
            removableNeurons.add(neuron);
        } else if (neuron.getNeighbors().isEmpty()){
            neighborlessNeurons.add(neuron);
        }
    }

    // Remove neurons without neighbors
    neurons.removeAll(neighborlessNeurons);

    // Remove neurons with less than minPts samples
    neurons.removeAll(removableNeurons);

    return neurons.size();
}
