import java.lang.reflect.Method;
import java.lang.reflect.Parameter;

public static void validateMethod(Method method) throws Exception {
    // Check if method is public and return void
    if (method.getReturnType() != void.class ||
            !method.getModifiers().contains(Modifier.PUBLIC)) {
        throw new Exception("Method should be public and return void.");
    }

    // Check if all parameters are annotated
    Parameter[] params = method.getParameters();
    for (Parameter param : params) {
        if (!param.isAnnotationPresent(Annotation.class)) {
            throw new Exception("All parameters should be annotated.");
        }
    }
