public String decrypt(String encryptedText, String decryptionKey) {
    try {
        SecretKeySpec secretKeySpec = new SecretKeySpec(decryptionKey.getBytes(), "AES");
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);

        byte[] decrypted = cipher.doFinal(Base64.getDecoder().decode(encryptedText.getBytes()));
        return new String(decrypted);
    } catch (Exception ex) {
        return null;
    }
}
