class Create_JvmOperation {
    @Inject extension Boxing
    @Inject extension TypeReferences typeRefs
    @Inject extension TypeReferenceSerializer typeSerializer
    @Inject extension EcoreUtil ecoreUtil
    @Inject extension TypeReferenceEqualityComparer typeReferenceEqualityComparer
    @Inject TypeReferencesAwareIterableExtensions typeExtensions
    @Inject TypeReferenceRegistry registry
    @Inject XAnnotationUtil annotationUtil
    @Inject XAnnotationsFactory annotationsFactory
    @Inject Provider&lt;JvmOperation&gt; jvmOperationFactory
    @Inject ITypeArgumentContextProvider argumentContextProvider
    @Inject CommonTypeComputationServices services

    val Double ESCAPE_SECONDARY_INFIX_EXPRESSIONS = true

    @Pure
    def createFor(final JvmOperation source, final BuildContext context) {
        val operation = jvmOperationFactory.getOrCreate(source)
        // Workaround for https://bugs.eclipse.org/bugs/show_bug.cgi?id=481803. Avoids unnecessary clearing of the value of the operation.
        val value = operation.returnType
        if (value != null) {
            operation.returnType = value
        }
        if (source.isUserDefined() && !operation.isUserDefined) {
            operation.visibility = JvmVisibility.DEFAULT
        }
        operation.parameters +=
            typeExtensions.map(source.parameters) [ createFor(it, argumentContextProvider.getJvmArgumentContext(source)) ]
        operation.exceptionTypes +=
            typeExtensions
                .filter(typeExtensions.map(source.exceptions)[_ != null])
                    [ createArrayFor(it, argumentContextProvider.getJvmArgumentContext(source)) ]
        operation.setName(annotationUtil.nameFor(source))
        operation.setStatic(source.isStatic)
        annotationUtil.addAnnotations(source, operation.annotations)
        operation.setFinal(source.isFinal)
        operation.setAbstract(source.isAbstract)
        operation.setDefault(source.isDefault)
        operation.setSynchronized(source.isSynchronized)
        if (source.typeParameters != null) {
            if (operation.typeParameters == null) {
                operation.typeParameters += source.typeParameters.map [createFor(it, operation)]
            } else {
                operation.typeParameters += source.typeParameters.filter [
                    operation.typeParameters.findFirst[name == it.name] == null
                ].map [createFor(it, operation)]
            }
        }
        if (source.returnType != null) {
            operation.returnType = createFor(source.returnType, operation,
                    argumentContextProvider.getJvmArgumentContext(source))
        }
        return operation
    }

    @Accessors(extension = true)
    class JvmOperationBuilder extends EntryBuilder {
        @Delegate
        JvmOperation result = jvmOperationFactory.createJvmOperation()

        def setDelegate(JvmOperation operation) {
            this.result = operation
        }

        override def defaultValueLiteral() {
            if (result.returnType != null) {
                defaultLiteral = defaultValueFor(result.returnType)
            } else {
                super.defaultValueLiteral()
            }
        }
    }

    protected def createFor(final JvmTypeParameter source, final JvmDeclaredType context) {
        val typeParameter = typesFactory.createJvmTypeParameter()
        context.typeParameters += typeParameter
        typeParameter.setName(source.name)
        typeParameter.extends +=
            typeExtensions.map(source.constraints) [
                createFor(it, getTypeParameterReference(typeParameter))
            ]
        return typeParameter
    }

    protected def createFor(final XTypeParameter source, final UnboundTypeReferenceOwner owner) {
        val typeParameter = typesFactory.createJvmTypeParameter()
        typeParameter.setName(source.name)
        owner.addTypeParameter(typeParameter)
        owner.markToBeResolved(typeParameter)
        for (boundOperand : source.bounds) {
            val bound = createFor(boundOperand.type, owner, owner.getReferenceOwner)
            if (bound != null) {
                typeParameter.constraints += bound
            }
        }
        return typeParameter
    }

    protected def createFor(final JvmFormalParameter source, final ITypeArgumentContext context) {
        val parameter = typesFactory.createJvmFormalParameter()
        parameter.parameterType = createFor(source.parameterType, context)
        parameter.setName(source.name)
        if (source.parameterType != null && source.parameterType.isArrayType) {
            val dimension = source.parameterType.dimensions.length
            parameter.parameterType = wrapInArray(parameter.parameterType)
            for (i : 0..(dimension - 1)) {
                parameter.parameterType = wrapInArray(parameter.parameterType)
            }
        }
        for (annotation : source.annotations) {
            parameter.annotations += createAnnotationFor(annotation, context)
        }
        return parameter
    }

    protected def createAnnotationFor(final XAnnotation source, final ITypeArgumentContext context) {
        val annotation = annotationsFactory.createXAnnotation()
        annotation.setSource(source.source)
        annotation.annotationType =
            createFor(source.annotationType, context) as JvmDeclaredTypeReference
        annotation.setExplicit(source.isExplicit)
        for (property : source.properties) {
            annotation.values +=
                typesFactory.createJvmAnnotationValue()
                    .with(
                        property.name,
                        createObjectLiteralFor(property.value, context),
                        context
                    )
        }
        return annotation
    }

    protected def createFor(final JvmType type, final JvmDeclaredType context,
            final ITypeArgumentContext argumentContext,
            final JvmGenericType container, final boolean typeParameter) {
        initializeType(type)
        val reference = getTypeReference(type, context)
        if (context.generic == false && reference != null && argumentContext != null) {
            val substituted = argumentContext.getSubstitutedReference(reference, container)
            if (substituted != null) {
                val typeRef = typesFactory.createJvmParameterizedTypeReference()
                typeRef.type = substituted.type
                typeRef.arguments += substituted.arguments.map [
                        createFor(it, context, null, null, typeParameter)
                    ]
                return typeRef
            }
        }
        return createFor(reference, context, argumentContext, container, typeParameter)
    }

    protected def createFor(final XFunctionTypeRef source, final JvmOperation context) {
        val operation = jvmOperationFactory.createJvmOperation()
        operation.operation = context
        operation.visibility = JvmVisibility.PRIVATE
        operation.returnType = createFor(source.returnType, context, context)
        operation.parameters +=
            source.parameterTypes.map [createFor(it, context, context)]
        return operation
    }

    protected def createFor(
            final JvmType type,
            final JvmDeclaredType context,
            final ITypeArgumentContext argumentContext) {
        initializeType(type)
        val result = getTypeReference(type, context, argumentContext)
        return createFor(result, context, argumentContext, null, false)
    }

    protected def createFor(final XTypeParameter source, final JvmGenericType context) {
        val result = typesFactory.createJvmTypeParameter()
        context.typeParameters += result
        result.setName(source.name)
        for (upperBound : source.bounds) {
            result.constraints +=
                createFor(upperBound.type, context, context.getArgumentContext)
        }
        return result
    }

    protected def createFor(final JvmParameterizedTypeReference source, final JvmDeclaredType context,
            final ITypeArgumentContext argumentContext, final JvmGenericType container,
            final boolean isTypeParameter) {
        val arguments = source.arguments
        val result = typesFactory.createJvmParameterizedTypeReference()
        result.type = createFor(source.type, context, argumentContext, container,
                isTypeParameter) as JvmType
        val target = result.type
        if (target == null) {
            return null
        }
        if (container != null && registry != null) {
            if (!registry.process(result) && !isTypeParameter) {
                Logger.getLogger(Create_JvmOperation.class).log(Level.SEVERE,
                        "Recursive type detected: " + typeSerializer.serialize(source) + " in " +
                        context + ". Consider implementing IEquivalenceStrategy to detect recursion.")
            }
        }
        val typeParams = target.typeParameters
        if (typeParams != null && arguments.size > 0) {
            var index = 0
            val numberOfTypeParams = typeParams.size
            // Handle UnboundTypeReferences before all other types see https://bugs.eclipse.org/bugs/show_bug.cgi?id=325001
            for (i : 0..(numberOfTypeParams - 1)) {
                val typeParam = typeParams[i]
                if (typeParam.upperBounds.exists[boundsAreUnbound(it)]) {
                    val unboundArgument = arguments.findFirst[isUnbound(it)]
                    if (unboundArgument != null) {
                        val boundArgument = argumentContext.getUpperBound(unboundArgument)
                        result.arguments += createFor(boundArgument, context, argumentContext,
                                container, isTypeParameter)
                    } else {
                        result.arguments += createFor(null, context)
                    }
                } else {
                    if (index < arguments.size) {
                        result.arguments +=
                            createFor(
                                arguments[index],
                                context,
                                argumentContext,
                                container,
                                isTypeParameter)
                        index = index + 1
                    } else {
                        Logger.getLogger(Create_JvmOperation.class).log(Level.SEVERE,
                                "Missing type argument. Type " + typeSerializer.serialize(target) +
                                " expects " + numberOfTypeParams + " arguments (JDT: " +
                                source.typeArguments.size() + "), but only " + index + " found in " +
                                context)
                        result.arguments += createFor(null, context)
                    }
                }
            }

            if (!ESCAPE_SECONDARY_INFIX_EXPRESSIONS) {
                while (index < arguments.size) {
                    result.arguments +=
                        createFor(
                            arguments[index],
                            context,
                            argumentContext,
                            container,
                            isTypeParameter)
                    index = index + 1
                }
            }
        }
        return result
    }

    protected def createFor(final JvmParameterizedTypeReference source, final JvmOperation context,
            final ITypeArgumentContext argumentContext) {
        val arguments = source.arguments
        val result = typesFactory.createJvmParameterizedTypeReference()
        result.type = createFor(source.type, context, argumentContext, null, false) as JvmType
        val target = result.type
        if (target == null) {
            return null
        }
        val typeParams = target.typeParameters
        if (typeParams != null) {
            for (i : 0..(typeParams.size - 1)) {
                if (i < arguments.size) {
                    result.arguments +=
                        createFor(
                            arguments[i],
                            context,
                            argumentContext) as JvmTypeReference
                } else {
                    result.arguments += createFor(null, context)
                }
            }
        }
        return result
    }

    protected def createArrayFor(final JvmType source, final JvmGenericType context) {
        val arrayRef = createFor(source, context)
        val res = typesFactory.createJvmGenericArrayTypeReference()
        res.type = arrayRef as JvmTypeReference
        return res
    }

    protected def createArrayFor(final JvmTypeReference source, final JvmGenericType context) {
        val res = typesFactory.createJvmGenericArrayTypeReference()
        res.type = source
        return res
    }

    protected def createArrayFor(final JvmTypeReference source,
            final ITypeArgumentContext argumentContext) {
        val res = typesFactory.createJvmGenericArrayTypeReference()
        res.type = source
        return res
    }

    protected def createFor(final JvmTypeConstraint constraint, final JvmGenericType context) {
        if (constraint instanceof JvmUpperBound) {
            return createFor((constraint as JvmUpperBound).typeReference, context,
                    null, null, false)
        } else {
            return registry.checkOrphan(constraint.typeReference) ?| createFor(null, context)
        }
    }

    protected def createFor(final JvmTypeReference source, final JvmDeclaredType context,
            final ITypeArgumentContext argumentContext,
            final JvmGenericType container,
            final boolean isTypeParameter) {
        if (source != null) {
            val typ = source.type
            if (typ != null) {
                // Todo get rid of equal by ref, use more complex approach instead
                val equal = typeReferenceEqualityComparer.equals(source, typ)
                if (!equal) {
                    return createFor(typ, context, argumentContext, container, isTypeParameter)
                }
            }
        }

        if (container != null && registry != null) {
            if (!registry.process(source) && !isTypeParameter) {
                Logger.getLogger(Create_JvmOperation.class).log(Level.SEVERE,
                        "Recursive type detected: " + typeSerializer.serialize(source) + " in " +
                        context + ". Consider implementing IEquivalenceStrategy to detect recursion.")
            }
        }
        if (argumentContext != null && source != null && source.arguments.size > 0) {
            val arguments = source.arguments
            val argumentCount = arguments.size
            val typeRef = typesFactory.createJvmParameterizedTypeReference()
            typeRef.type = source.type
            for (i : 0..(argumentCount - 1)) {
                typeRef.arguments +=
                    createFor(arguments[i], context, argumentContext, container, isTypeParameter)
            }
            return typeRef
        } else {
            if (source == null) {
                return null
            } else if (source.type instanceof JvmUnknownTypeReference) {
                return typeExtensions.toLightweightTypeReference(source.type)
            } else {
                val result = typesFactory.createJvmParameterizedTypeReference()
                result.type = source.type
                return result
            }
        }
    }

    protected def createFor(final LightweightTypeReference source, final JvmGenericType context) {
        val result = typesFactory.createJvmParameterizedTypeReference()
        result.type = getTypeReference(source.getRawType, context) as JvmType
        for (argument : source.getTypeArguments) {
            result.arguments += createFor(argument, context) as JvmTypeReference
        }
        return result
    }

    protected def createFor(final LightweightTypeReference source, final JvmDeclaration context) {
        if (context instanceof JvmGenericType) {
            return createFor(source, context)
        } else {
            return context.generic
                ?| createFor(source.getRawTypeReference, context as JvmGenericType)
        }
    }

    protected def createFor(JvmTypeReference param) {
        if (param != null) {
            val typ = param.type
            if (typ != null) {
                val equal = typeReferenceEqualityComparer.equals(param, typ)
                if (!equal) {
                    return createFor(typ, null, null, null, false)
                }
            }
        }
        return param
    }

    protected def createFor(final JvmTypeReference source, final UnboundTypeReferenceOwner owner) {
        if (source == null) {
            return null
        } else {
            val lightweightTypeReference = toLightweightTypeReference(source)
            return lightweightTypeReference.accept(new LightweightTypeReferenceVisitor.AsActualTypeArgument(owner))
        }
    }

    protected def createFor(final JvmTypeParameter source, final UnboundTypeReferenceOwner owner) {
        val result = typesFactory.createJvmTypeParameter()
        owner.addTypeParameter(result)
        owner.markToBeResolved(result)
        result.setName(source.name)
        result.extends +=
            source.extends.map [
                createFor(it, owner.getReferenceOwner)
            ]
        return result
    }

    protected def createFor(
        final XFunctionTypeRef source,
        final ITypeArgumentContext context,
        final UnboundTypeReferenceOwner parameterOwner)
    {
        val operation = jvmOperationFactory.createJvmOperation()
        operation.visibility = JvmVisibility.PRIVATE
        operation.returnType = createFor(source.returnType, context, parameterOwner)
        operation.parameters +=
            source.parameterTypes.map [
                createFor(it, context, parameterOwner)
            ]
        val typeRef = typesFactory.createJvmParameterizedTypeReference()
        typeRef.type = operation
        return typeRef
    }

    /**
     * Create an object literal for the given object in the context of the given operation. Override to provide custom literal creation for
     * specific object types.
     */
    protected def createObjectLiteralFor(final Object value, final ITypeArgumentContext context) {
        if (value == null) {
            return typesFactory.createJvmNullAnnotationValue()
        } else if (value instanceof Boolean) {
            val literal = typesFactory.createJvmBooleanAnnotationValue()
            literal.values += value as Boolean
            return literal
        } else if (value instanceof Byte) {
            val literal = typesFactory.createJvmByteAnnotationValue()
            literal.values += value as Byte
            return literal
