import boofcv.abst.tensor.Tensor_F64;
import boofcv.struct.image.Planar;

public void convertImageToTensor(Planar input, Tensor_F64 output, int miniBatch) {
    int width = input.getWidth();
    int height = input.getHeight();
    int bands = input.getNumBands();

    double[] tensorData = output.data;
    int tensorIndex = miniBatch * width * height * bands;

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int pixelIndex = y * width + x;
            for (int band = 0; band < bands; band++) {
                double pixelValue = input.getBand(band).get(x, y);
                tensorData[tensorIndex++] = pixelValue;
            }
        }
    }
}
