    if(message != null && !message.isEmpty()){
        StringBuilder stringBuilder = new StringBuilder();
        int messageLength = message.length();
        int partsCount = 1;

        for(int i = 0; i < messageLength; i += maxPartSize) {
            int endIndex = Math.min(i + maxPartSize, messageLength);
            String part = message.substring(i, endIndex);
            int partLength = part.length();

            if(partLength >= maxPartSize) {
                // Append content data to message
                stringBuilder.append("Part ").append(partsCount++).append(": ").append(part.substring(0, maxPartSize)).append("\n");
                // Convert message part to content data
                stringBuilder.append("Content: ").append(part.substring(maxPartSize)).append("\n\n");
            } else {
                // Append message part to message
                stringBuilder.append("Part ").append(partsCount++).append(": ").append(part).append("\n");
            }               
        }
        // Print the final message with converted message parts
        System.out.println(stringBuilder.toString());
    }
}
