public static void accurateSleep(long millis) throws InterruptedException {
    long start = System.currentTimeMillis();
    long remaining = millis;
    while (remaining > 0) {
        Thread.sleep(remaining);
        remaining = millis - (System.currentTimeMillis() - start);
    }
}
