public static Object doConversion(Class<?> targetType, Object value) {
    // Check if target type and value are not null
    if (targetType == null || value == null) {
        return null;
    }

    // Check if the value is of the same target type, no need for conversion
    if (targetType.isAssignableFrom(value.getClass())) {
        return value;
    }

    // String to numeric conversions
    if(targetType.equals(Byte.class) || targetType.equals(byte.class)){
        return Byte.parseByte(value.toString());
    }
    else if(targetType.equals(Short.class) || targetType.equals(short.class)){
        return Short.parseShort(value.toString());
    }
    else if(targetType.equals(Integer.class) || targetType.equals(int.class)){
        return Integer.parseInt(value.toString());
    }
    else if(targetType.equals(Long.class) || targetType.equals(long.class)){
        return Long.parseLong(value.toString());
    }
    else if(targetType.equals(Float.class) || targetType.equals(float.class)){
        return Float.parseFloat(value.toString());
    }
    else if(targetType.equals(Double.class) || targetType.equals(double.class)){
        return Double.parseDouble(value.toString());
    }

    // String to boolean conversion
    if(targetType.equals(Boolean.class) || targetType.equals(boolean.class)){
        return Boolean.parseBoolean(value.toString());
    }

    // Date to string conversion
    if(targetType.equals(String.class) && value instanceof Date){
        SimpleDateFormat format = new SimpleDateFormat("yyyy-MM-dd");
        return format.format((Date)value);
    }

    // Default case
    return null;
}
