private Class<?> resolveTargetConversionType(Class<?> listenerType, Type declaredTargetType) {
    ParameterizedType parameterizedType = (ParameterizedType) declaredTargetType;
    Type[] listenerGenericTypes = parameterizedType.getActualTypeArguments();
    if (listenerGenericTypes.length == 0) {
        return null;
    }
    Class<?> targetConversionType = null;
    if (listenerType != null) {
        Type resolvedType = TypeResolver.reify(listenerGenericTypes[0], listenerType);
        if (resolvedType instanceof Class) {
            targetConversionType = (Class<?>) resolvedType;
        }
    }
    if (targetConversionType == null) {
        if (listenerGenericTypes[0] instanceof Class) {
            targetConversionType = (Class<?>) listenerGenericTypes[0];
        }
    }
    return targetConversionType;
}
