public byte[] reuseBuffers(byte[] existingBuffer) throws IOException {
    if (existingBuffer != null) {
        // If an existing buffer is available, grow the array by one
        byte[] newBuffer = new byte[existingBuffer.length + 1];
        System.arraycopy(existingBuffer, 0, newBuffer, 0, existingBuffer.length);
        return newBuffer;
    } else {
        // If no existing buffer is available, allocate a new one
        byte[] newBuffer = new byte[1];
        return newBuffer;
    }
}
