public String waitForChange(ZooKeeper zookeeper, String lockNode, String placeInLine) throws KeeperException, InterruptedException {
    String currentNode = null;
    while (true) {
        List<String> nodes = zookeeper.getChildren(lockNode, false);
        Collections.sort(nodes);
        int index = nodes.indexOf(placeInLine);
        if (index == 0) {
            currentNode = placeInLine;
            break;
        } else if (index > 0) {
            String prevNode = lockNode + "/" + nodes.get(index - 1);
            Stat stat = zookeeper.exists(prevNode, true);
            if (stat != null) {
                break;
            }
        }
    }
    return currentNode;
}
