public List<Integer> computeCircleOffsets(int radius, int imgWidth) {
    List<Integer> offsets = new ArrayList<>();
    int x = 0;
    int y = radius;
    int error = 1 - radius;

    while (x <= y) {
        offsets.add(x + y * imgWidth); // Octant 1
        offsets.add(-x + y * imgWidth); // Octant 2
        offsets.add(-x - y * imgWidth); // Octant 3
        offsets.add(x - y * imgWidth); // Octant 4
        offsets.add(y + x * imgWidth); // Octant 5
        offsets.add(-y + x * imgWidth); // Octant 6
        offsets.add(-y - x * imgWidth); // Octant 7
        offsets.add(y - x * imgWidth); // Octant 8

        x++;
        if (error < 0) {
            error += 2 * x + 1;
        } else {
            y--;
            error += 2 * (x - y) + 1;
        }
    }

    return offsets;
}
