public void createMissingTimephasedData(ProjectFile file, ResourceAssignment assignment, 
                              List<TimephasedData> timephasedPlanned, List<TimephasedData> timephasedComplete) {

    List<TimephasedData> missingTimephasedData = new ArrayList<>();

    for (TimephasedData plannedData : timephasedPlanned) {
        boolean isPresent = false;
        for (TimephasedData completeData : timephasedComplete) {
            if (plannedData.getStart().equals(completeData.getStart())) {
                isPresent = true;
                break;
            }
        }
        if (!isPresent) {
            TimephasedData missingData = new TimephasedData(
                    plannedData.getStart(),
                    plannedData.getFinish(),
                    plannedData.getValue(),
                    TimeUnit.getInstance(plannedData.getTimeUnit()),
                    TimephasedDataType.PLANNED,
                    assignment);
            missingTimephasedData.add(missingData);
        }
    }
    timephasedComplete.addAll(missingTimephasedData);

    // Sort the complete data by date if required.
    Collections.sort(timephasedComplete, new Comparator<TimephasedData>() {
        @Override
        public int compare(TimephasedData o1, TimephasedData o2) {
            return o1.getStart().compareTo(o2.getStart());
        }
    });
}
