import java.util.HashMap;
import java.util.Map;

public class IndexCreator {
    public static Map<String, String> createIndex(String originalPath, String... dirs) throws IOException {
        Map<String, String> index = new HashMap<>();

        for(String dir : dirs) {
            Path path = Paths.get(originalPath, dir);
            Files.walk(path)
                    .filter(Files::isRegularFile)
                    .forEach(p -> {
                        File file = p.toFile();
                        String content = null;
                        try {
                            // Read the file contents
                            content = new String(Files.readAllBytes(file.toPath()));
                        } catch (IOException e) {
                            e.printStackTrace();
                        }
                        // Add the file contents to the index
                        index.put(file.getName(), content);
                    });
        }

        return index;
    }
}
