public boolean isSimpleNamespaceObjectLiteral(Object node) {
    if (node instanceof VariableDeclaration) {
        VariableDeclaration variable = (VariableDeclaration) node;
        if (variable.getParent() instanceof ExpressionStatement) {
            ExpressionStatement statement = (ExpressionStatement) variable.getParent();
            if (statement.getExpression() instanceof Assignment) {
                Assignment assignment = (Assignment) statement.getExpression();
                if (assignment.getLeft() instanceof MemberExpression) {
                    MemberExpression member = (MemberExpression) assignment.getLeft();
                    if (member.getProperty() instanceof Identifier) {
                        Identifier property = (Identifier) member.getProperty();
                        if (property.getName().equals("prototype")) {
                            return false;
                        }
                    }
                    if (assignment.getRight() instanceof ObjectExpression) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}
