public static double[] wgs84ToCartesian(double latitude, double longitude, double altitude) {
    double a = 6378137.0; // semi-major axis of WGS84 ellipsoid, in meters
    double f = 1 / 298.257223563; // flattening of WGS84 ellipsoid
    double b = a * (1 - f); // semi-minor axis of WGS84 ellipsoid, in meters
    double eSquared = 2*f - Math.pow(f, 2); // eccentricity squared of WGS84 ellipsoid
    double n = a / Math.sqrt(1 - eSquared * Math.pow(Math.sin(Math.toRadians(latitude)), 2)); // prime vertical radius of curvature
    double x = (n + altitude) * Math.cos(Math.toRadians(latitude)) * Math.cos(Math.toRadians(longitude));
    double y = (n + altitude) * Math.cos(Math.toRadians(latitude)) * Math.sin(Math.toRadians(longitude));
    double z = ((1 - eSquared) * n + altitude) * Math.sin(Math.toRadians(latitude));
    return new double[] {x, y, z};
}
