public static PerformanceStatistic iterateLiveAndDeadThreads(List<Thread> liveThreads, List<ThreadStatistic> deadThreadStatistics) {
    PerformanceStatistic aggregatedStatistic = new PerformanceStatistic();

    for (Thread liveThread : liveThreads) {
        ThreadStatistic threadStatistic = ThreadStatistic.get(liveThread.getId());
        if (threadStatistic != null) {
            aggregatedStatistic.add(threadStatistic.getWriteStatistic());
        }
    }

    for (ThreadStatistic deadThreadStat : deadThreadStatistics) {
        aggregatedStatistic.add(deadThreadStat.getWriteStatistic());
    }

    return aggregatedStatistic;
}
