public void repairLattice(String[][] lattice, int nodeEndIndex) {
    int numRows = lattice.length;
    int numCols = lattice[0].length;

    boolean[] overlapFound = new boolean[numRows];
    int[] overlapAmt = new int[numRows];

    for (int i = 0; i < numRows; i++) {
        overlapFound[i] = false;
        overlapAmt[i] = 0;
    }

    // find all overlaps
    for (int row = 0; row < numRows; row++) {
        for (int col = 0; col < numCols; col++) {
            String curElem = lattice[row][col];
            int overlap = numCols - col;
            if (col + curElem.length() > nodeEndIndex) {
                overlap = nodeEndIndex - col;
            }
            if (overlap > overlapAmt[row]) {
                overlapFound[row] = true;
                overlapAmt[row] = overlap;
            }
        }
    }

    // find row with least overlap and create new Viterbi node
    int minOverlapRow = -1;
    int minOverlapAmt = numCols;
    for (int row = 0; row < numRows; row++) {
        if (overlapFound[row] && overlapAmt[row] < minOverlapAmt) {
            minOverlapRow = row;
            minOverlapAmt = overlapAmt[row];
        }
    }

    if (minOverlapRow != -1) {
        String[] newNode = new String[numCols];
        for (int col = 0; col < numCols; col++) {
            newNode[col] = lattice[minOverlapRow][col];
        }
        for (int row = minOverlapRow + 1; row < numRows; row++) {
            for (int col = 0; col < numCols; col++) {
                lattice[row][col] = lattice[row - 1][col];
            }
        }
        for (int col = 0; col < numCols; col++) {
            lattice[minOverlapRow][col] = newNode[col];
        }
    }
}
