			if (!continuationField.equals(previousContinuationField)) {
				if (continuationString.equals("")) {
					continuationString = token;
				} else {
					compndValueSetter(previousContinuationField,
							continuationString);
					previousContinuationField = continuationField;
					continuationString = token + " ";
