public void removeExpiredTransactions(Queue<Transaction> liveTransactionsSession, long currentTime) {
    List<Transaction> expiredTransactions = new ArrayList<>();
    Iterator<Transaction> iterator = liveTransactionsSession.iterator();

    while (iterator.hasNext()) {
        Transaction currentTransaction = iterator.next();
        if (currentTransaction.getTimestamp() < currentTime) {
            expiredTransactions.add(currentTransaction);
            iterator.remove();
        }
    }
}
