public String createProxyUrlString(URLConnection req) throws MalformedURLException {
    Proxy proxy = req.getProxy();
    if (proxy == null || proxy == Proxy.NO_PROXY) {
        return "";
    } else {
        SocketAddress addr = proxy.address();
        if (addr instanceof InetSocketAddress) {
            InetSocketAddress proxyAddr = (InetSocketAddress) addr;
            return String.format("%s://%s:%d", proxyAddr.getHostName(), proxyAddr.getPort(), req.getURL());
        } else {
            throw new MalformedURLException("Proxy address is not an InetSocketAddress");
        }
    }
}
