    target[targetOffset + 2] = (byte) (tableKey.getTimestamp() >> 16);
    target[targetOffset + 3] = (byte) (tableKey.getTimestamp() >> 8);
    target[targetOffset + 4] = (byte) tableKey.getTimestamp();
    return targetOffset + 5;
}
