public double computeActivationDegree(FuncTerm conjunction, FuncTerm disjunction, Node node){
    if(node.isLeaf()){
        double degree = ((Leaf)node).getFuzzySet().computeDegree(node.getInputValue());
        return degree;
    }else{
        double lDegree = computeActivationDegree(conjunction, disjunction, node.getLeftChild());
        double rDegree = computeActivationDegree(conjunction, disjunction, node.getRightChild());
        String operator = ((NonLeaf)node).getOperator();
        if(operator.equals("and")){
            double degree = conjunction.computeDegree(lDegree, rDegree);
            return degree;
        }else{
            double degree = disjunction.computeDegree(lDegree, rDegree);
            return degree;
        }
    }
}
