public void printStackTraceWithLocale(Throwable cause, Locale locale, Appendable buffer) throws IOException {
    if (cause == null) {
        return;
    }

    // print the stack trace
    PrintWriter writer = new PrintWriter(buffer);
    cause.printStackTrace(writer);
    writer.flush();
    writer.close();

    // translate the stack trace with the given locale
    ResourceBundle bundle = ResourceBundle.getBundle("java/exceptions", locale);
    List<String> lines = Arrays.asList(buffer.toString().split(System.lineSeparator()));
    lines = lines.stream().map(line -> bundle.getString(line.trim())).collect(Collectors.toList());

    // write the translated stack trace to the buffer
    buffer.append(System.lineSeparator());
    for (String line : lines) {
        buffer.append(line).append(System.lineSeparator());
    }
}
