public int judgeMatch(Class<?>[] paramTypes, Object[] destArgs) {
    int weight = 0;
    for(int i = 0; i < paramTypes.length; i++) {
        if(destArgs[i] == null) {
            weight += 0;
        } else if(paramTypes[i].isAssignableFrom(destArgs[i].getClass())) {
            weight += 1;
        } else {
            weight -= 1;
        }
    }
    return weight;
}
