public String getResourceVersion(Object entity) {
    if(entity == null) {
        return null;
    }
    try {
        Method method = entity.getClass().getMethod("getResourceVersion");
        return (String) method.invoke(entity);
    } catch (NoSuchMethodException ex) {
       return null;
    } catch (IllegalAccessException | InvocationTargetException ex) {
       throw new RuntimeException("Error accessing resource version for entity: " + entity, ex);
