public void determineChangeConflict(Change change) throws IllegalArgumentException {
    if (change.getType() == ChangeType.ADD) {
        this.acceptChange = true; // Accepts all ADD changes
        return;
    }

    for (Change c : this.changes) {
        if (c == change) continue; // Excludes the current change from the comparison
        if (change.getType() == c.getType()) {
            throw new IllegalArgumentException("Conflicting changes.");
        }

        // SET and REMOVE changes cannot conflict with ADD changes
        if (change.getType() == ChangeType.SET || change.getType() == ChangeType.REMOVE) {
            if (change.getAttribute().equals(c.getAttribute())) {
                throw new IllegalArgumentException("Conflicting changes.");
            }
        }
    }

    // No conflicts found - mark the change as acceptable
    this.acceptChange = true;
    this.changesToBeAccepted.add(change);
}
