/**
 * Returns a string with the given text repeated a certain number of times.
 *
 * @param text the text to repeat
 * @param times the number of times to repeat the text
 * @return a string with the repeated text
 */
public String repeat(String text, int times) {
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < times; i++) {
        builder.append(text);
    }
    return builder.toString();
}

/**
 * Returns true if the given string is a palindrome, false otherwise.
 *
 * @param str the string to check
 * @return true if the given string is a palindrome, false otherwise
 */
public boolean isPalindrome(String str) {
    int start = 0;
    int end = str.length() - 1;

    while (start < end) {
        if (str.charAt(start) != str.charAt(end)) {
            return false;
        }
        start++;
        end--;
    }

    return true;
}
