public static List<URL> getResources(String name) throws IOException {
    List<URL> resources = new ArrayList<>();
    Enumeration<URL> resourceUrls = ClassLoader.getSystemClassLoader().getResources(name);
    while (resourceUrls.hasMoreElements()) {
        URL url = resourceUrls.nextElement();
        resources.add(url);
    }
    resources.addAll(Collections.list(Thread.currentThread().getContextClassLoader().getResources(name)));
    return resources;
}
