public double applyProgressiveModifications(double value, double dest, double speed) throws LionEngineException {
    if(speed == 0.0) {
        throw new LionEngineException("Invalid argument: speed cannot be 0.0");
    }
    double delta = dest - value;
    double maxDelta = speed * delta;
    double increment = Math.max(Math.min(maxDelta, delta), -maxDelta);
    return value + increment;
}
