public void createScanResultMap(Map<String, MessageHandler> scanResultMap, SagaScanner sagaScanner) {
    // Get all sagas from the scanner
    List<Class<? extends Saga>> sagaClasses = sagaScanner.scan();

    // Iterate over all sagas and add their message handlers to the scan result map
    for (Class<? extends Saga> sagaClass : sagaClasses) {
        List<MessageHandler> messageHandlers = new ArrayList<>();
        Saga saga = null;
        try {
            // Create an instance of the saga
            Constructor<? extends Saga> constructor = sagaClass.getDeclaredConstructor();
            constructor.setAccessible(true);
            saga = constructor.newInstance();
        } catch (InstantiationException | IllegalAccessException | InvocationTargetException | NoSuchMethodException e) {
            // Handle exception
            e.printStackTrace();
        }

        if (saga != null) {
            // Get all message handlers of the saga
            for (Method method : saga.getClass().getMethods()) {
                if (method.isAnnotationPresent(MessageHandlerMethod.class)) {
                    messageHandlers.add(new AnnotatedMethodMessageHandler(saga, method));
                }
            }

            // Add the message handlers to the scan result map
            for (MessageHandler messageHandler : messageHandlers) {
                scanResultMap.put(messageHandler.getMessageType().getName(), messageHandler);
            }
        }
    }
}
