public static int getNextAvailablePort(int fromPort) throws NoSuchElementException {
    while (true) {
        try {
            ServerSocket socket = new ServerSocket(fromPort);
            socket.close();
            return fromPort;
        } catch (IOException e) {
            fromPort++;
            if (fromPort > 65535) {
                throw new NoSuchElementException("No ports are available.");
            }
        }
    }
}
