/**
 * Removes the node with the specified key from the internal map.
 *
 * @param key The key of the node to remove
 * @return The removed node, or null if the key was not found
 */
@Override
protected Entry<K, V> remove(Object key) {
    // Check if the key is null or the map is empty
    if (key == null || mSize == 0) {
        return null;
    }

    // Find the previous and current nodes for the given key
    Entry<K, V> prev = null;
    Entry<K, V> current = mStart;
    while (current != null && !current.mKey.equals(key)) {
        prev = current;
        current = current.mNext;
    }

    // Return null if the key was not found
    if (current == null) {
        return null;
    }

    // Remove the current node from the map
    if (prev != null) {
        prev.mNext = current.mNext;
    } else {
        mStart = current.mNext;
    }

    mSize--;
    return current;
}
