public void stopContainer(String containerId, boolean keepContainer, boolean removeVolumes) throws DockerAccessException {
    DockerClient dockerClient = DefaultDockerClient.fromEnv().build();
    try {
        Container container = dockerClient.inspectContainer(containerId);
        if (container.state().running()) {
            dockerClient.stopContainer(containerId, 0);
        }
        if (!keepContainer) {
            dockerClient.removeContainer(containerId, DockerClient.RemoveContainerParam.forceKill());
        }
        if (removeVolumes) {
            dockerClient.removeVolume(container.id());
        }
    } catch (DockerException | InterruptedException e) {
        throw new DockerAccessException("Failed to stop container: " + containerId, e);
    } finally {
        dockerClient.close();
    }
}
