public static List<String> getMBeanValues(String host_port, String receiver) {
    List<String> values = new ArrayList<>();

    try {
        JMXServiceURL url = new JMXServiceURL("service:jmx:rmi:///jndi/rmi://" + host_port + "/jmxrmi");
        JMXConnector jmxc = JMXConnectorFactory.connect(url, null);
        MBeanServerConnection mbsc = jmxc.getMBeanServerConnection();

        // Get all MBeans registered in the server
        ObjectName mbeanName = new ObjectName("*:*");
        for (ObjectName name : mbsc.queryNames(mbeanName, null)) {
            // Get the value of each attribute of the MBean
            String value = mbsc.getAttributes(name, mbsc.getMBeanInfo(name).getAttributes()).toString();
            values.add(value);
        }

        jmxc.close();
    } catch (Exception e) {
        e.printStackTrace();
    }

    // Pass the values to the receiver in a single thread
    for (String value : values) {
        sendValueToReceiver(value, receiver);
    }

    return values;
}

