public String getLastWord(String str, int pos) {
    if(str.charAt(pos) == ' ' || pos == 0) {
        return null;
    }

    int i = pos;
    while(i >= 0 && str.charAt(i) != ' ') {
        i--;
    }

    return str.substring(i+1, pos+1);
}
