public int addToConstantPool(int value) {
    for (int i = 1; i < constantPool.length; i++) {
        if (constantPool[i] instanceof Integer && ((Integer) constantPool[i]).intValue() == value) {
            return i;
        }
    }
    int newIndex = constantPool.length;
    Object[] newPool = new Object[newIndex + 1];
    System.arraycopy(constantPool, 0, newPool, 0, newIndex);
    newPool[newIndex] = new Integer(value);
    constantPool = newPool;
    return newIndex;
}
