import java.util.*;
import java.util.stream.*;

public class StreamReducerSimple {
    private final Comparator<Object> keyComparator;
    private final Function<Object, Long> keyFunction;

    public StreamReducerSimple(Comparator<Object> keyComparator, Function<Object, Long> keyFunction) {
        this.keyComparator = keyComparator;
        this.keyFunction = keyFunction;
    }

    public <T> Map<Object, Long> reduce(Stream<? extends T> stream, Function<? super T, ?> keyMapper) {
        return stream.collect(Collectors.groupingBy(keyMapper, TreeMap::new, Collectors.summingLong(x -> keyFunction.apply(x))));
    }
}
