                                    if( !button.get("url").equals("") ){
                                        this.message_string += "\"url\":\"" + button.get("url") + "\",";
                                    }
                                    if( !button.get("payload").equals("") ){
                                        this.message_string += "\"payload\":\"" + button.get("payload") + "\",";
