                                    this.message_string = this.message_string.replaceAll(",$", "");
                                    this.message_string += "},";
                                }
                                this.message_string = this.message_string.replaceAll(",$", "");
                            this.message_string += "]";
                        this.message_string += "}";
                    this.message_string += "}";
                this.message_string += "}";
