@Override
    public void sawOpcode(int seen) {
        try {
            stack.precomputation(this);
            if ((seen == Const.ARETURN) && (stack.getStackDepth() > 0)) {
                OpcodeStack.Item item = stack.getStackItem(0);
                if (item.isNull()) {
                    bugReporter.reportBug(new BugInstance(this, BugType.TBP_TRISTATE_BOOLEAN_PATTERN.name(), NORMAL_PRIORITY).addClass(this).addMethod(this)
                            .addSourceLine(this));
                    throw new StopOpcodeParsingException();
                }
            }
        } finally {
            stack.sawOpcode(this, seen);
        }
    },0

public static int getMonthStart(int utcDays){
    Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
    cal.set(2000, 0, 1); // set starting date to Jan 1, 2000
    cal.add(Calendar.DATE, utcDays); // add the number of days to the starting date
    return cal.get(Calendar.MONTH); // return the index of the month (0-11)
}
