public static String bytesToBinaryString(byte[] bytes) {
    StringBuilder binaryString = new StringBuilder();
    for (byte b : bytes) {
        binaryString.append(Integer.toBinaryString(b & 255 | 256).substring(1));
    }
    return binaryString.toString();
}
