public <T> T getResult(Future<T> future, long timeoutMillis) throws ServiceException {
    try {
        return future.get(timeoutMillis, TimeUnit.MILLISECONDS);
    } catch (TimeoutException e) {
        Logger.getLogger(getClass()).warn("Timeout waiting for async result", e);
        throw new ServiceException("Timeout waiting for async result", e);
    } catch (ExecutionException e) {
        Logger.getLogger(getClass()).error("Error waiting for async result", e);
        throw new ServiceException("Error waiting for async result", e.getCause());
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
        throw new ServiceException("Interrupted while waiting for async result", e);
    }
}
